const navButtons = Array.from(document.querySelectorAll(".nav-item"));
const sidebarNavSections = Array.from(document.querySelectorAll("[data-sidebar-section]"));
const sidebarGroupToggles = Array.from(document.querySelectorAll("[data-sidebar-group-toggle]"));
const sidebarSectionByView = Object.freeze({
  campaigns: "gos",
  "strategic-qr": "offer",
  "smart-catalogs": "offer",
  inventory: "offer",
  "reward-passes": "offer",
  leads: "operate",
  sales: "operate",
  validator: "operate",
  redemptions: "optimize",
  affiliates: "optimize",
  dashboard: "gos",
  channels: "gos",
  competition: "gos",
  branches: "operate",
  missions: "optimize",
  account: "admin",
  admin: "admin",
});
navButtons.forEach((button) => {
  const copy = button.querySelector(":scope > span:not(.material-symbols-outlined):not(.feature-tier-badge)");
  const label = String(copy?.querySelector("strong")?.textContent || copy?.textContent || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!label) return;
  if (!button.getAttribute("aria-label")) button.setAttribute("aria-label", label);
  if (!button.getAttribute("title")) button.setAttribute("title", label);
});

function setSidebarAccordionSection(sectionKey, options = {}) {
  const allowCollapse = Boolean(options.allowCollapse);
  const target = sidebarNavSections.find((section) => section.dataset.sidebarSection === sectionKey);
  if (!target) return;
  const shouldCloseTarget = allowCollapse && target.classList.contains("is-open");
  sidebarNavSections.forEach((section) => {
    const isTarget = section === target;
    const isOpen = isTarget && !shouldCloseTarget;
    section.classList.toggle("is-open", isOpen);
    section.classList.toggle("is-current", isTarget);
    const toggle = section.querySelector("[data-sidebar-group-toggle]");
    if (toggle) {
      toggle.setAttribute("aria-expanded", String(isOpen));
      if (isTarget) toggle.setAttribute("aria-current", "page");
      else toggle.removeAttribute("aria-current");
    }
  });
}

function syncSidebarAccordionWithActiveNav(view = state.currentView) {
  const currentSectionKey = sidebarSectionByView[view] || "";
  sidebarNavSections.forEach((section) => {
    const isCurrent = section.dataset.sidebarSection === currentSectionKey;
    section.classList.toggle("is-current", isCurrent);
    const toggle = section.querySelector("[data-sidebar-group-toggle]");
    if (toggle) {
      if (isCurrent) toggle.setAttribute("aria-current", "page");
      else toggle.removeAttribute("aria-current");
    }
  });
  if (currentSectionKey) {
    setSidebarAccordionSection(currentSectionKey);
    return;
  }
  if (view === "rms-machine") {
    // The icon-only machine view still needs a usable first menu group.
    setSidebarAccordionSection("offer");
    return;
  }
  if (!sidebarNavSections.some((section) => section.classList.contains("is-open"))) {
    setSidebarAccordionSection("operate");
  }
}

