function planFeatures() {
  return state.subscription?.plan?.features || {};
}

function planLimits() {
  return state.subscription?.plan?.limits || {};
}

function hasPlanFeature(feature) {
  if (!feature) return true;
  if (feature === "admin_workspace") return isAdmin();
  if (isAdmin()) return true;
  if (feature === "leads_view" && isPrepaidValidatorOnly()) return true;
  const plan = currentPlan();
  const planCode = normalizePlanTierCode(plan.code || plan.plan_code || "");
  if (!state.accountWorkspaceLoaded) {
    return true;
  }
  if (!planCode && !Object.keys(plan.features || {}).length && plan.portal_access_allowed === undefined) {
    return true;
  }
  if (plan.category === "subscription" && plan.portal_access_allowed === false) {
    return false;
  }
  if (planTierIndex(plan.code) < 0) return Boolean(planFeatures()[feature]);
  return planMeetsTier(requiredPlanForFeature(feature), plan) && Boolean(planFeatures()[feature]);
}

function currentPlan() {
  return state.subscription?.plan || session?.user?.subscription?.plan || {};
}

function normalizePlanTierCode(value = "") {
  const code = String(value || "").toUpperCase();
  if (code === "MEDIUM") return "GROWTH";
  if (code === "PREMIUM") return "PRO";
  if (code === "STARTED") return "STARTER";
  if (code === "ENTERPRISE") return "GLOBAL";
  return code;
}

function planTierIndex(value = "") {
  const index = planTierOrder.indexOf(normalizePlanTierCode(value));
  return index >= 0 ? index : -1;
}

function planMeetsTier(requiredCode = "STARTER", plan = currentPlan()) {
  const requiredIndex = planTierIndex(requiredCode);
  const currentIndex = planTierIndex(plan.code || "STARTER");
  if (requiredIndex < 0) return true;
  if (["GLOBAL", "ENTERPRISE"].includes(String(plan.code || "").toUpperCase())) return true;
  return currentIndex >= requiredIndex;
}

function requiredPlanForFeature(feature = "") {
  if (!feature || feature === "admin_workspace") return null;
  const fallbackCode = featureRequiredPlanFallback[feature] || "STARTER";
  const publicPlans = (state.subscriptionPlans || []).filter((plan) => planTierOrder.includes(plan.code));
  const dynamicPlan = publicPlans
    .sort((a, b) => planTierIndex(a.code) - planTierIndex(b.code))
    .find((plan) => Boolean(plan.features?.[feature]));
  return normalizePlanTierCode(dynamicPlan?.code || fallbackCode);
}

function requiredPlanForActivationType(type = "") {
  const legacyType = String(type || "").toUpperCase();
  const interactiveType = interactiveTypeForLegacyType(legacyType);
  if (["TRIVIA", "TRIVIA_QUIZ", "OPEN_QUESTION"].includes(legacyType) || ["TRIVIA_QUIZ", "OPEN_QUESTION"].includes(interactiveType)) {
    return "STARTER";
  }
  return interactiveCategoryForType(legacyType) === "premium" ? "PRO" : "GROWTH";
}

function applyFeatureTierBadge(element, requiredCode, options = {}) {
  if (!element) return;
  const code = normalizePlanTierCode(requiredCode);
  const meta = planTierBadges[code];
  element.querySelector(":scope > .feature-tier-badge")?.remove();
  element.classList.remove("feature-tier-medium", "feature-tier-premium", "feature-tier-applied");
  delete element.dataset.featureTier;
  if (!meta) return;
  const badge = document.createElement("span");
  badge.className = `feature-tier-badge ${code === "PRO" ? "is-premium" : "is-medium"}`;
  const badgeLabel = options.short ? (meta.shortLabel || meta.label.charAt(0)) : meta.label;
  badge.title = `Requiere plan ${meta.label}`;
  badge.setAttribute("aria-label", `Requiere plan ${meta.label}`);
  badge.innerHTML = `
    <span class="${options.short ? "feature-tier-dot" : "material-symbols-outlined"}" aria-hidden="true">${options.short ? "" : meta.icon}</span>
    <span>${escapeHtml(badgeLabel)}</span>
  `;
  element.appendChild(badge);
  element.dataset.featureTier = code;
  element.classList.add("feature-tier-applied", code === "PRO" ? "feature-tier-premium" : "feature-tier-medium");
}

function isPrepaidValidatorOnly() {
  const plan = currentPlan();
  const features = plan.features || {};
  return plan.category === "prepaid" && features.qr_validator && !features.portal_access;
}

function loginRedirectForSession(value) {
  const plan = value?.user?.subscription?.plan || {};
  const features = plan.features || {};
  if (plan.category === "prepaid" && features.qr_validator && !features.portal_access) {
    return "";
  }
  return "";
}

function formatLimitValue(value) {
  return value === null || value === undefined ? "Ilimitado" : Number(value).toLocaleString("es-CO");
}

function renderSubscriptionBanner() {
  if (!subscriptionBanner) return;
  const plan = state.subscription?.plan;
  if (!plan) {
    subscriptionPlanName.textContent = "Plan no cargado";
    subscriptionPlanSummary.textContent = "Sin información de permisos.";
    subscriptionLimits.innerHTML = "";
    if (subscriptionTiming) subscriptionTiming.textContent = "Sin fecha de renovación cargada.";
    return;
  }
  const limits = planLimits();
  const access = state.access || {};
  subscriptionPlanName.textContent = plan.name || plan.code || "Plan";
  subscriptionPlanSummary.textContent = plan.category === "ticket_base"
    ? `Portal Base activo sin mensualidad. Saldo operativo: ${formatNumber(access.ticketBalance || state.qrCreditAccount?.qr_balance || 0)} tickets.`
    : plan.category === "growth_temporal"
      ? `Growth temporal activo${access.daysUntilGrowthExpiration !== null && access.daysUntilGrowthExpiration !== undefined ? `: ${access.daysUntilGrowthExpiration} días restantes` : ""}. Conservas tus tickets al volver a Base.`
      : plan.category === "prepaid"
        ? "Acceso legacy: compra T200 para activar Portal Base con dashboard, validador interno y Sales Tracker."
        : `${subscriptionAccessLabel(plan)}: upgrade mensual activo. Los tickets se compran desde Cuenta y se consumen como saldo operativo.`;
  if (subscriptionTiming) {
    subscriptionTiming.textContent = subscriptionTimingText(plan);
  }
  subscriptionBanner.dataset.accessStatus = plan.access_status || plan.status || "ACTIVE";
  subscriptionLimits.innerHTML = [
    ["Estado", subscriptionAccessLabel(plan)],
    ["Saldo tickets", access.ticketBalance ?? state.qrCreditAccount?.qr_balance ?? 0],
    ["Usuarios", limits.users],
    ["Sedes", limits.branches],
    ["Campañas", limits.active_campaigns],
    ["Exportaciones", limits.lead_exports_month],
    ["Afiliados", limits.affiliates],
  ].map(([label, value]) => `<span class="subscription-limit-chip">${label}: ${formatLimitValue(value)}</span>`).join("");
  syncActivationTypeAccess();
}

