function readDashboardBuilderStorage() {
  try {
    return JSON.parse(window.localStorage.getItem(DASHBOARD_BUILDER_STORAGE_KEY) || "{}") || {};
  } catch {
    return {};
  }
}

function writeDashboardBuilderStorage(layouts) {
  try {
    window.localStorage.setItem(DASHBOARD_BUILDER_STORAGE_KEY, JSON.stringify(layouts || {}));
  } catch {
    // El dashboard sigue funcionando aunque el navegador bloquee localStorage.
  }
}

function getDashboardProfile() {
  try {
    const stored = window.localStorage.getItem(DASHBOARD_BUILDER_PROFILE_KEY) || state.dashboardBuilderProfile || "marketing";
    return DASHBOARD_BUILDER_PROFILES[stored] ? stored : "marketing";
  } catch {
    return DASHBOARD_BUILDER_PROFILES[state.dashboardBuilderProfile] ? state.dashboardBuilderProfile : "marketing";
  }
}

function setDashboardProfile(profile) {
  state.dashboardBuilderProfile = DASHBOARD_BUILDER_PROFILES[profile] ? profile : "marketing";
  try {
    window.localStorage.setItem(DASHBOARD_BUILDER_PROFILE_KEY, state.dashboardBuilderProfile);
  } catch {
    // Ignore storage failures.
  }
}

function getDashboardBuilderLayout(profile = getDashboardProfile()) {
  const layouts = readDashboardBuilderStorage();
  const saved = Array.isArray(layouts[profile]) ? layouts[profile] : null;
  const fallback = DASHBOARD_BUILDER_PROFILES[profile]?.widgets || DASHBOARD_BUILDER_PROFILES.marketing.widgets;
  return (saved || fallback).filter((id) => DASHBOARD_WIDGET_CATALOG.some((widget) => widget.id === id));
}

function setDashboardBuilderLayout(profile, widgets) {
  const layouts = readDashboardBuilderStorage();
  layouts[profile] = Array.from(new Set((widgets || []).filter((id) => DASHBOARD_WIDGET_CATALOG.some((widget) => widget.id === id))));
  writeDashboardBuilderStorage(layouts);
}

function resetDashboardBuilderLayout() {
  const profile = getDashboardProfile();
  const layouts = readDashboardBuilderStorage();
  delete layouts[profile];
  writeDashboardBuilderStorage(layouts);
  renderDashboardBuilder();
  showFeedback("Perfil restaurado con los bloques recomendados.", "success", { title: "Dashboard RMS" });
}

function dashboardBuilderTopCampaigns() {
  return (Array.isArray(state.campaigns) ? state.campaigns : [])
    .map((campaign) => ({
      label: campaign.name || "Campaña sin nombre",
      revenue: toNumber(campaign.attributed_revenue || campaign.observed_revenue),
      investment: toNumber(campaign.budget_total || campaign.investment || campaign.cost_total),
      meta: `${toNumber(campaign.total_leads)} leads | ${toNumber(campaign.total_qr_redeemed)} redenciones`,
    }))
    .filter((row) => row.revenue || row.investment)
    .sort((a, b) => b.revenue - a.revenue)
    .slice(0, 4);
}

function dashboardBuilderTopChannels() {
  const channelRows = Array.isArray(state.acquisitionChannels) && state.acquisitionChannels.length
    ? state.acquisitionChannels.map((channel) => ({
      label: channel.name || channel.platform || channel.channel || "Canal sin nombre",
      revenue: toNumber(channel.attributed_revenue || channel.revenue || channel.total_revenue),
      investment: toNumber(channel.budget_total || channel.monthly_budget || channel.total_investment || channel.investment),
      meta: `${toNumber(channel.leads || channel.total_leads)} leads | ${toNumber(channel.sales_count || channel.sales || channel.total_sales)} ventas`,
    }))
    : (state.dashboard?.acquisition_sources || []).map((row) => ({
      label: `${acquisitionSourceLabel(row.acquisition_source)}${row.acquisition_channel ? ` / ${row.acquisition_channel}` : ""}`,
      revenue: toNumber(row.revenue),
      investment: toNumber(row.investment || row.cost || row.budget_total),
      meta: `${toNumber(row.count)} ventas`,
    }));
  return channelRows.filter((row) => row.revenue || row.investment).sort((a, b) => b.revenue - a.revenue).slice(0, 4);
}

function getDashboardBuilderNextAction(stats) {
  if (!stats.totalLeads) {
    return { title: "Crear entrada de clientes", meta: "Primero alimenta el sistema", body: "Crea una campaña, QR, dinámica o importa contactos para empezar a medir.", cta: "Crear acción de revenue", route: "campaigns" };
  }
  if (!stats.openAgenda) {
    return { title: "Crear seguimiento en agenda", meta: "Leads sin orden de trabajo", body: "Cada lead debe tener próxima tarea: WhatsApp, llamada, redención, venta o recompra.", cta: "Abrir agenda", route: "agenda" };
  }
  if (stats.activeQr) {
    return { title: "Recordar tickets activos", meta: `${stats.activeQr} tickets vivos`, body: "Convierte tickets activos en visitas, redenciones y ventas registradas.", cta: "Ver tickets", route: "strategic-qr" };
  }
  if (stats.totalQrRedeemed && !stats.observedSalesCount) {
    return { title: "Registrar ventas de redenciones", meta: "Hay redenciones sin revenue", body: "Conecta redenciones con ventas para que el ROI sea real.", cta: "Registrar venta", route: "sales" };
  }
  return { title: "Revisar Máquina RMS", meta: "Prioriza la siguiente acción", body: "Ordena oportunidades por riesgo, intención, ticket, recompra o referido.", cta: "Abrir Máquina RMS", route: "rms-machine" };
}

function getDashboardBuilderStats() {
  const summary = state.summary || {};
  const dashboard = state.dashboard || {};
  const acquisitionSources = Array.isArray(dashboard.acquisition_sources) ? dashboard.acquisition_sources : [];
  const branchPerformance = Array.isArray(dashboard.branch_performance) ? dashboard.branch_performance : [];
  const recentLeads = Array.isArray(dashboard.recent_players) ? dashboard.recent_players.slice(0, 8) : [];
  const recentRedemptions = Array.isArray(dashboard.recent_redemptions) ? dashboard.recent_redemptions.slice(0, 8) : [];
  const recentSalesSource = Array.isArray(state.selectedSales) && state.selectedSales.length
    ? state.selectedSales
    : Array.isArray(dashboard.recent_acquisition_sales)
      ? dashboard.recent_acquisition_sales
      : Array.isArray(dashboard.recent_sales)
        ? dashboard.recent_sales
        : [];
  const recentSales = recentSalesSource.slice(0, 8);
  const topCampaigns = dashboardBuilderTopCampaigns();
  const topChannels = dashboardBuilderTopChannels();
  const campaignInvestment = topCampaigns.reduce((sum, row) => sum + toNumber(row.investment), 0)
    || (Array.isArray(state.campaigns) ? state.campaigns.reduce((sum, campaign) => sum + toNumber(campaign.budget_total || campaign.investment || campaign.cost_total), 0) : 0);
  const campaignRevenue = topCampaigns.reduce((sum, row) => sum + toNumber(row.revenue), 0)
    || (Array.isArray(state.campaigns) ? state.campaigns.reduce((sum, campaign) => sum + toNumber(campaign.attributed_revenue || campaign.observed_revenue), 0) : 0);
  const channelInvestment = toNumber(state.acquisitionChannelTotals?.total_investment || state.acquisitionChannelTotals?.investment)
    || topChannels.reduce((sum, row) => sum + toNumber(row.investment), 0);
  const channelRevenue = toNumber(state.acquisitionChannelTotals?.revenue || state.acquisitionChannelTotals?.total_revenue)
    || topChannels.reduce((sum, row) => sum + toNumber(row.revenue), 0);
  const observedSalesCount = toNumber(summary.observed_sales_count || summary.direct_sales_count);
  const observedRevenue = toNumber(summary.observed_revenue || summary.attributed_revenue);
  const openAgenda = (Array.isArray(state.leadAgenda) ? state.leadAgenda : [])
    .filter((item) => !["DONE", "CLOSED", "COMPLETED", "CANCELLED"].includes(String(item.status || item.agenda_status || "").toUpperCase()))
    .length;
  const rmsOpportunities = Array.isArray(state.rmsMachine?.opportunities)
    ? state.rmsMachine.opportunities.length
    : Object.values(state.rmsMachine?.dailyQueue || {}).reduce((sum, list) => sum + (Array.isArray(list) ? list.length : 0), 0);
  const totalLeads = toNumber(summary.total_leads);
  const activeQr = toNumber(dashboard.summary?.active_qr);
  const totalQrRedeemed = toNumber(summary.total_qr_redeemed);
  const nextAction = getDashboardBuilderNextAction({
    totalLeads,
    openAgenda,
    activeQr,
    totalQrRedeemed,
    observedSalesCount,
  });
  return {
    activeQr,
    avgTicket: observedSalesCount ? observedRevenue / observedSalesCount : 0,
    acquisitionSources,
    branchPerformance,
    campaignInvestment,
    campaignRevenue,
    campaignRoi: campaignInvestment ? (campaignRevenue - campaignInvestment) / campaignInvestment : null,
    channelInvestment,
    channelRevenue,
    channelRoi: channelInvestment ? (channelRevenue - channelInvestment) / channelInvestment : null,
    nextAction,
    observedRevenue,
    openAgenda,
    redemptionRate: toNumber(summary.redemption_rate),
    recentLeads,
    recentRedemptions,
    recentSales,
    referralPoints: toNumber(summary.referral_points_awarded),
    referralSales: toNumber(summary.referral_sales_count),
    rmsOpportunities,
    salesCount: observedSalesCount,
    topCampaigns,
    topChannels,
    sourceRows: acquisitionSources.map((row) => ({
      label: `${acquisitionSourceLabel(row.acquisition_source)}${row.acquisition_channel ? ` / ${row.acquisition_channel}` : ""}`,
      revenue: toNumber(row.revenue),
      investment: toNumber(row.investment || row.cost || row.budget_total),
      meta: `${toNumber(row.count)} ventas`,
    })).filter((row) => row.revenue || row.investment).sort((a, b) => b.revenue - a.revenue).slice(0, 5),
    totalLeads,
    totalQrGenerated: toNumber(summary.total_qr_generated),
    totalQrRedeemed,
  };
}

function dashboardBuilderBars(rows = [], key = "revenue") {
  if (!rows.length) return '<div class="dashboard-mini-empty">Sin datos suficientes todavía. Registra inversión, leads y ventas para activar esta lectura.</div>';
  const maxValue = Math.max(...rows.map((row) => toNumber(row[key])), 1);
  return `
    <div class="dashboard-mini-bars">
      ${rows.map((row) => {
        const value = toNumber(row[key]);
        const width = Math.max(8, Math.min(100, Math.round((value / maxValue) * 100)));
        return `
          <div class="dashboard-mini-bar">
            <div class="dashboard-mini-bar-top"><span>${escapeHtml(row.label)}</span><strong>${escapeHtml(money(value))}</strong></div>
            <i><b style="width:${width}%"></b></i>
            <small>${escapeHtml(row.meta || "")}</small>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function dashboardBuilderFunnel(stats) {
  const stages = [
    { label: "Leads", value: stats.totalLeads, meta: "captados" },
    { label: "Tickets", value: stats.totalQrGenerated, meta: "emitidos" },
    { label: "Redenciones", value: stats.totalQrRedeemed, meta: "validadas" },
    { label: "Ventas", value: stats.salesCount, meta: "registradas" },
  ];
  const maxValue = Math.max(...stages.map((stage) => toNumber(stage.value)), 1);
  return `
    <div class="dashboard-funnel-simple">
      ${stages.map((stage) => {
        const width = Math.max(8, Math.min(100, Math.round((toNumber(stage.value) / maxValue) * 100)));
        return `
          <div class="dashboard-funnel-row">
            <span>${escapeHtml(stage.label)}</span>
            <i><b style="width:${width}%"></b></i>
            <strong>${toNumber(stage.value).toLocaleString("es-CO")}</strong>
            <small>${escapeHtml(stage.meta)}</small>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function dashboardBuilderRoiTable(stats) {
  const rows = [
    ...stats.topChannels.map((row) => ({ ...row, type: "Canal" })),
    ...stats.topCampaigns.map((row) => ({ ...row, type: "Campaña" })),
  ]
    .map((row) => ({
      ...row,
      roi: toNumber(row.investment) ? (toNumber(row.revenue) - toNumber(row.investment)) / toNumber(row.investment) : null,
    }))
    .sort((a, b) => toNumber(b.revenue) - toNumber(a.revenue))
    .slice(0, 5);
  if (!rows.length) {
    return '<div class="dashboard-mini-empty">Cuando registres inversión y ventas por canal o campaña, aquí aparecerá el ranking ejecutivo.</div>';
  }
  return `
    <div class="dashboard-roi-table-wrap">
      <table class="dashboard-roi-table">
        <thead>
          <tr>
            <th>Fuente</th>
            <th>Tipo</th>
            <th>Inversión</th>
            <th>Revenue</th>
            <th>ROI</th>
          </tr>
        </thead>
        <tbody>
          ${rows.map((row) => `
            <tr>
              <td>${escapeHtml(row.label)}</td>
              <td>${escapeHtml(row.type)}</td>
              <td>${escapeHtml(money(row.investment))}</td>
              <td>${escapeHtml(money(row.revenue))}</td>
              <td>${escapeHtml(ratioLabel(row.roi))}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function dashboardBuilderSimpleTable(columns = [], rows = [], emptyMessage = "Sin datos para mostrar.") {
  if (!rows.length) return `<div class="dashboard-mini-empty">${escapeHtml(emptyMessage)}</div>`;
  return `
    <div class="dashboard-roi-table-wrap dashboard-data-table-wrap">
      <table class="dashboard-roi-table dashboard-data-table">
        <thead>
          <tr>${columns.map((column) => `<th>${escapeHtml(column.label)}</th>`).join("")}</tr>
        </thead>
        <tbody>
          ${rows.map((row) => `
            <tr>
              ${columns.map((column) => `<td>${escapeHtml(typeof column.value === "function" ? column.value(row) : row[column.key])}</td>`).join("")}
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function dashboardBuilderSalesTable(stats) {
  const rows = stats.recentSales || [];
  return dashboardBuilderSimpleTable([
    { label: "Cliente", value: (row) => saleCustomerText(row) || row.customer_name || "-" },
    { label: "Producto", value: (row) => row.product_name || row.product || "-" },
    { label: "Revenue", value: (row) => money(row.sale_amount || row.amount || row.revenue || 0) },
    { label: "Fecha", value: (row) => formatDateShort(row.sale_date || row.created_at || row.updated_at) },
  ], rows, "Cuando registres ventas, aparecerán aquí para análisis y exportación.");
}

function dashboardBuilderLeadsTable(stats) {
  return dashboardBuilderSimpleTable([
    { label: "Lead", value: (row) => row.name || row.player_name || row.full_name || "-" },
    { label: "Email", value: (row) => row.email || "-" },
    { label: "Teléfono", value: (row) => row.phone || "-" },
    { label: "Fecha", value: (row) => formatDateShort(row.created_at || row.updated_at) },
  ], stats.recentLeads || [], "Sin leads recientes para mostrar.");
}

function dashboardBuilderRedemptionsTable(stats) {
  return dashboardBuilderSimpleTable([
    { label: "Cliente", value: (row) => row.player_name || row.customer_name || "-" },
    { label: "Beneficio", value: (row) => row.reward_name || row.benefit_label || "-" },
    { label: "Validador", value: (row) => row.validator || "-" },
    { label: "Fecha", value: (row) => formatDateShort(row.redeemed_at || row.created_at) },
  ], stats.recentRedemptions || [], "Sin redenciones recientes para mostrar.");
}

function dashboardBuilderBranchTable(stats) {
  return dashboardBuilderSimpleTable([
    { label: "Sucursal", value: (row) => row.branch_name || "Sin sucursal" },
    { label: "Redenciones", value: (row) => toNumber(row.redemptions).toLocaleString("es-CO") },
    { label: "Ventas", value: (row) => toNumber(row.sales).toLocaleString("es-CO") },
    { label: "Revenue", value: (row) => money(row.revenue || 0) },
  ], (stats.branchPerformance || []).slice(0, 8), "Sin actividad por sucursal.");
}

function dashboardWidgetCsvRows(widgetId, stats) {
  const metricRows = {
    revenue: [["Métrica", "Valor", "Detalle"], ["Revenue real", stats.observedRevenue, `${stats.salesCount} ventas registradas`]],
    sales: [["Métrica", "Valor", "Detalle"], ["Ventas registradas", stats.salesCount, money(stats.observedRevenue)]],
    avg_ticket: [["Métrica", "Valor", "Detalle"], ["Ticket promedio", stats.avgTicket, `${stats.salesCount} ventas registradas`]],
    leads: [["Métrica", "Valor", "Detalle"], ["Leads capturados", stats.totalLeads, `${stats.redemptionRate}% redime`]],
    tickets: [["Métrica", "Valor", "Detalle"], ["Tickets emitidos", stats.totalQrGenerated, `${stats.activeQr} activos`]],
    redemptions: [["Métrica", "Valor", "Detalle"], ["Redenciones", stats.totalQrRedeemed, `${stats.redemptionRate}% tasa de redención`]],
    redemption_rate: [["Métrica", "Valor", "Detalle"], ["Tasa de redención", `${stats.redemptionRate}%`, `${stats.totalQrRedeemed} redenciones / ${stats.totalQrGenerated} tickets`]],
  };
  if (metricRows[widgetId]) return metricRows[widgetId];
  if (widgetId === "revenue_funnel") {
    return [
      ["Etapa", "Cantidad", "Detalle"],
      ["Leads", stats.totalLeads, "captados"],
      ["Tickets", stats.totalQrGenerated, "emitidos"],
      ["Redenciones", stats.totalQrRedeemed, "validadas"],
      ["Ventas", stats.salesCount, "registradas"],
    ];
  }
  if (["channel_roi", "campaign_roi", "source_mix"].includes(widgetId)) {
    const rows = widgetId === "campaign_roi" ? stats.topCampaigns : widgetId === "source_mix" ? stats.sourceRows : stats.topChannels;
    return [["Fuente", "Revenue", "Inversión", "ROI", "Detalle"], ...rows.map((row) => [
      row.label,
      toNumber(row.revenue),
      toNumber(row.investment),
      toNumber(row.investment) ? ratioLabel((toNumber(row.revenue) - toNumber(row.investment)) / toNumber(row.investment)) : "-",
      row.meta || "",
    ])];
  }
  if (widgetId === "roi_table") {
    return [["Fuente", "Tipo", "Inversión", "Revenue", "ROI"], ...[
      ...stats.topChannels.map((row) => ({ ...row, type: "Canal" })),
      ...stats.topCampaigns.map((row) => ({ ...row, type: "Campaña" })),
    ].map((row) => [
      row.label,
      row.type,
      toNumber(row.investment),
      toNumber(row.revenue),
      toNumber(row.investment) ? ratioLabel((toNumber(row.revenue) - toNumber(row.investment)) / toNumber(row.investment)) : "-",
    ])];
  }
  if (widgetId === "sales_table") {
    return [["Cliente", "Producto", "Revenue", "Fecha"], ...(stats.recentSales || []).map((row) => [
      saleCustomerText(row) || row.customer_name || "-",
      row.product_name || row.product || "-",
      toNumber(row.sale_amount || row.amount || row.revenue),
      formatDateShort(row.sale_date || row.created_at || row.updated_at),
    ])];
  }
  if (widgetId === "leads_table") {
    return [["Lead", "Email", "Teléfono", "Fecha"], ...(stats.recentLeads || []).map((row) => [
      row.name || row.player_name || row.full_name || "-",
      row.email || "-",
      row.phone || "-",
      formatDateShort(row.created_at || row.updated_at),
    ])];
  }
  if (widgetId === "redemptions_table") {
    return [["Cliente", "Beneficio", "Validador", "Fecha"], ...(stats.recentRedemptions || []).map((row) => [
      row.player_name || row.customer_name || "-",
      row.reward_name || row.benefit_label || "-",
      row.validator || "-",
      formatDateShort(row.redeemed_at || row.created_at),
    ])];
  }
  if (widgetId === "branch_table") {
    return [["Sucursal", "Redenciones", "Ventas", "Revenue"], ...(stats.branchPerformance || []).map((row) => [
      row.branch_name || "Sin sucursal",
      toNumber(row.redemptions),
      toNumber(row.sales),
      toNumber(row.revenue),
    ])];
  }
  return [["Métrica", "Valor"], ["Sin datos", ""]];
}

function exportDashboardWidget(widgetId) {
  const widget = DASHBOARD_WIDGET_CATALOG.find((item) => item.id === widgetId);
  const rows = dashboardWidgetCsvRows(widgetId, getDashboardBuilderStats());
  downloadCsv(`dashboard-revenue-${widgetId || "bloque"}`, rows);
  showFeedback(`${widget?.title || "Bloque"} exportado en CSV.`, "success", { title: "Centro de Revenue" });
}

function renderDashboardWidget(widget, stats) {
  if (widget.id === "revenue") return { value: money(stats.observedRevenue), meta: `${stats.salesCount} ventas registradas`, body: `Ticket promedio: ${money(stats.avgTicket)}.`, tone: "money" };
  if (widget.id === "avg_ticket") return { value: money(stats.avgTicket), meta: `${stats.salesCount} ventas registradas`, body: "Úsalo para comparar CAC, inversión y revenue por canal.", tone: "money" };
  if (widget.id === "revenue_funnel") return { value: `${stats.totalLeads} leads`, meta: "Captura a venta registrada", body: dashboardBuilderFunnel(stats), tone: "chart" };
  if (widget.id === "sales") return { value: stats.salesCount, meta: "ventas observadas", body: `${money(stats.observedRevenue)} revenue medido.`, tone: "neutral" };
  if (widget.id === "channel_roi") return { value: ratioLabel(stats.channelRoi), meta: `${money(stats.channelInvestment)} invertido`, body: dashboardBuilderBars(stats.topChannels, "revenue"), tone: "chart" };
  if (widget.id === "campaign_roi") return { value: ratioLabel(stats.campaignRoi), meta: `${money(stats.campaignInvestment)} invertido`, body: dashboardBuilderBars(stats.topCampaigns, "revenue"), tone: "chart" };
  if (widget.id === "source_mix") return { value: "Top fuentes", meta: "Revenue por origen", body: dashboardBuilderBars(stats.sourceRows, "revenue"), tone: "chart" };
  if (widget.id === "leads") return { value: stats.totalLeads, meta: `${stats.redemptionRate}% redime`, body: "Volumen de materia prima comercial capturada.", tone: "neutral" };
  if (widget.id === "tickets") return { value: stats.totalQrGenerated, meta: `${stats.activeQr} activos`, body: "Tickets emitidos para activación, postventa o beneficio.", tone: "neutral" };
  if (widget.id === "redemptions") return { value: stats.totalQrRedeemed, meta: `${stats.redemptionRate}% tasa de redención`, body: "Uso real de beneficios y tickets.", tone: "neutral" };
  if (widget.id === "redemption_rate") return { value: `${stats.redemptionRate}%`, meta: `${stats.totalQrRedeemed} de ${stats.totalQrGenerated} tickets`, body: "Indicador rápido de activación real.", tone: "neutral" };
  if (widget.id === "roi_table") return { value: "Top 5", meta: "Canales y campañas por revenue", body: dashboardBuilderRoiTable(stats), tone: "table" };
  if (widget.id === "sales_table") return { value: `${stats.recentSales.length} filas`, meta: "Ventas recientes", body: dashboardBuilderSalesTable(stats), tone: "table" };
  if (widget.id === "leads_table") return { value: `${stats.recentLeads.length} filas`, meta: "Leads recientes", body: dashboardBuilderLeadsTable(stats), tone: "table" };
  if (widget.id === "redemptions_table") return { value: `${stats.recentRedemptions.length} filas`, meta: "Redenciones recientes", body: dashboardBuilderRedemptionsTable(stats), tone: "table" };
  if (widget.id === "branch_table") return { value: `${stats.branchPerformance.length} puntos`, meta: "Sucursales", body: dashboardBuilderBranchTable(stats), tone: "table" };
  return { value: "-", meta: widget.description, body: "", tone: "neutral" };
}

function openDashboardBuilderRoute(route = "dashboard") {
  if (route === "agenda") {
    setContactCenterTab("agenda");
    setView("leads");
    return;
  }
  if (route === "sales") {
    setView("sales");
    return;
  }
  if (route === "leads") {
    setContactCenterTab("directory");
    setView("leads");
    return;
  }
  setView(route || "dashboard");
}

function renderDashboardBuilder() {
  if (!dashboardBuilderShell || !dashboardWidgetGrid || !dashboardWidgetLibrary) return;
  ensureRevenueCenterUxStyles();
  if (revenueWorkspace) {
    revenueWorkspace.hidden = true;
    revenueWorkspace.classList.add("hidden");
  }
  state.dashboardBuilderProfile = getDashboardProfile();
  try {
    state.dashboardBuilderExpanded = window.localStorage.getItem(DASHBOARD_BUILDER_EXPANDED_KEY) === "1";
  } catch {
    state.dashboardBuilderExpanded = Boolean(state.dashboardBuilderExpanded);
  }
  const dashboardSection = document.querySelector('.view-section[data-view="dashboard"]');
  dashboardSection?.classList.toggle("dashboard-builder-mode", !state.dashboardBuilderExpanded);
  dashboardSection?.classList.toggle("dashboard-advanced-active", state.dashboardBuilderExpanded);
  dashboardAdvancedToggleButton?.classList.toggle("active", state.dashboardBuilderExpanded);
  if (dashboardAdvancedToggleButton) {
    dashboardAdvancedToggleButton.innerHTML = `
      <span class="material-symbols-outlined" aria-hidden="true">${state.dashboardBuilderExpanded ? "dashboard_customize" : "analytics"}</span>
      ${state.dashboardBuilderExpanded ? "Ocultar dashboard avanzado" : "Ver dashboard avanzado"}
    `;
  }
  const profile = DASHBOARD_BUILDER_PROFILES[state.dashboardBuilderProfile] || DASHBOARD_BUILDER_PROFILES.marketing;
  const layout = getDashboardBuilderLayout(state.dashboardBuilderProfile);
  const stats = getDashboardBuilderStats();
  if (dashboardProfileLabel) dashboardProfileLabel.textContent = profile.label;
  if (dashboardProfileTitle) dashboardProfileTitle.textContent = profile.title;
  if (dashboardProfileDescription) dashboardProfileDescription.textContent = profile.description;
  dashboardProfileTabs?.querySelectorAll("[data-dashboard-profile]").forEach((button) => {
    button.classList.toggle("active", button.dataset.dashboardProfile === state.dashboardBuilderProfile);
  });
  dashboardWidgetLibrary.innerHTML = DASHBOARD_WIDGET_CATALOG.map((widget) => {
    const active = layout.includes(widget.id);
    return `
      <button class="dashboard-library-item ${active ? "is-active" : ""}" type="button" data-dashboard-add-widget="${escapeHtml(widget.id)}" aria-pressed="${active ? "true" : "false"}">
        <span class="material-symbols-outlined" aria-hidden="true">${escapeHtml(widget.icon)}</span>
        <span class="dashboard-library-copy">
          <small class="dashboard-library-category">${escapeHtml(widget.category)}</small>
          <strong>${escapeHtml(widget.title)}</strong>
          <small>${escapeHtml(widget.description)}</small>
        </span>
        <span class="dashboard-library-action"><span class="material-symbols-outlined" aria-hidden="true">${active ? "check" : "add"}</span>${active ? "En tablero" : "Agregar"}</span>
      </button>
    `;
  }).join("");
  dashboardWidgetGrid.innerHTML = layout.map((id, index) => {
    const widget = DASHBOARD_WIDGET_CATALOG.find((item) => item.id === id);
    if (!widget) return "";
    const rendered = renderDashboardWidget(widget, stats);
    return `
      <article class="dashboard-widget-card ${escapeHtml(rendered.tone || "")}" draggable="true" data-dashboard-widget="${escapeHtml(widget.id)}">
        <div class="dashboard-widget-top">
          <span class="dashboard-widget-icon material-symbols-outlined" aria-hidden="true">${escapeHtml(widget.icon)}</span>
          <div><span class="mono-label">${escapeHtml(widget.category)}</span><h4>${escapeHtml(widget.title)}</h4></div>
          <button class="icon-button" type="button" data-dashboard-remove-widget="${escapeHtml(widget.id)}" title="Quitar bloque"><span class="material-symbols-outlined" aria-hidden="true">close</span></button>
        </div>
        <strong class="dashboard-widget-value">${escapeHtml(rendered.value ?? "-")}</strong>
        <span class="dashboard-widget-meta">${escapeHtml(rendered.meta || widget.description)}</span>
        <div class="dashboard-widget-body">${rendered.body || ""}</div>
        <div class="dashboard-widget-actions">
          <button class="ghost-button" type="button" data-dashboard-export-widget="${escapeHtml(widget.id)}">
            <span class="material-symbols-outlined" aria-hidden="true">download</span>
            CSV
          </button>
          <button class="icon-button" type="button" data-dashboard-move-widget="${escapeHtml(widget.id)}" data-direction="-1" ${index === 0 ? "disabled" : ""} title="Mover a la izquierda"><span class="material-symbols-outlined" aria-hidden="true">chevron_left</span></button>
          <button class="icon-button" type="button" data-dashboard-move-widget="${escapeHtml(widget.id)}" data-direction="1" ${index === layout.length - 1 ? "disabled" : ""} title="Mover a la derecha"><span class="material-symbols-outlined" aria-hidden="true">chevron_right</span></button>
        </div>
      </article>
    `;
  }).join("") || `
    <article class="dashboard-builder-empty">
      <span class="material-symbols-outlined" aria-hidden="true">dashboard_customize</span>
      <strong>Tu tablero personalizado está vacío.</strong>
      <p>Agrega bloques desde la biblioteca para construir una vista liviana y accionable.</p>
    </article>
  `;
}

function addDashboardWidget(widgetId) {
  const profile = getDashboardProfile();
  const layout = getDashboardBuilderLayout(profile);
  if (!DASHBOARD_WIDGET_CATALOG.some((widget) => widget.id === widgetId) || layout.includes(widgetId)) return;
  setDashboardBuilderLayout(profile, [...layout, widgetId]);
  renderDashboardBuilder();
}

function removeDashboardWidget(widgetId) {
  const profile = getDashboardProfile();
  setDashboardBuilderLayout(profile, getDashboardBuilderLayout(profile).filter((id) => id !== widgetId));
  renderDashboardBuilder();
}

function moveDashboardWidget(widgetId, direction) {
  const profile = getDashboardProfile();
  const layout = getDashboardBuilderLayout(profile);
  const index = layout.indexOf(widgetId);
  const nextIndex = index + Number(direction || 0);
  if (index < 0 || nextIndex < 0 || nextIndex >= layout.length) return;
  const next = [...layout];
  [next[index], next[nextIndex]] = [next[nextIndex], next[index]];
  setDashboardBuilderLayout(profile, next);
  renderDashboardBuilder();
}

function reorderDashboardWidget(sourceId, targetId) {
  if (!sourceId || !targetId || sourceId === targetId) return;
  const profile = getDashboardProfile();
  const layout = getDashboardBuilderLayout(profile);
  const sourceIndex = layout.indexOf(sourceId);
  const targetIndex = layout.indexOf(targetId);
  if (sourceIndex < 0 || targetIndex < 0) return;
  const next = [...layout];
  const [item] = next.splice(sourceIndex, 1);
  next.splice(targetIndex, 0, item);
  setDashboardBuilderLayout(profile, next);
  renderDashboardBuilder();
}

function toggleDashboardAdvancedView() {
  state.dashboardBuilderExpanded = !state.dashboardBuilderExpanded;
  try {
    window.localStorage.setItem(DASHBOARD_BUILDER_EXPANDED_KEY, state.dashboardBuilderExpanded ? "1" : "0");
  } catch {
    // Ignore storage failures.
  }
  if (state.dashboardBuilderExpanded) {
    renderDashboard();
    return;
  }
  renderDashboardBuilder();
}

function renderDashboard() {
  renderDashboardBuilder();
  if (revenueWorkspace) {
    revenueWorkspace.hidden = true;
    revenueWorkspace.classList.add("hidden");
  }
  if (!state.dashboardBuilderExpanded) return;
  renderCommandCenter();
  const summary = state.summary || {};
  const dashboard = state.dashboard || {};
  const recentRedemptions = withFilters(
    dashboard.recent_redemptions || [],
    ["player_name", "reward_name", "validator"],
    ["redeemed_at"]
  );
  const recentPlayers = withFilters(
    dashboard.recent_players || [],
    ["name", "email", "phone", "document_id"],
    ["created_at"]
  );
  const branchPerformance = filterRows(dashboard.branch_performance || [], ["branch_name", "address"]);
  const paymentMethods = filterRows(dashboard.payment_methods || [], ["payment_method"]);
  const acquisitionSources = filterRows(dashboard.acquisition_sources || [], ["acquisition_source", "acquisition_channel"]);
  const campaignPerformance = filterRows(dashboard.campaign_performance || [], ["campaign_name"]);
  const originPerformance = filterRows(dashboard.origin_performance || [], ["origin_type"]);
  const rewardPerformance = filterRows(dashboard.rewards || [], ["name"]);
  const qrStatus = dashboard.qr_status || [];
  const topHour = [...(dashboard.time_stats?.redemptions_by_hour || [])].sort((a, b) => toNumber(b.count) - toNumber(a.count))[0];
  const topBranch = [...branchPerformance].sort((a, b) => toNumber(b.revenue) - toNumber(a.revenue))[0];
  const observedSalesCount = toNumber(summary.observed_sales_count || summary.direct_sales_count);
  const observedRevenue = toNumber(summary.observed_revenue || summary.attributed_revenue);
  const avgTicket = observedSalesCount ? observedRevenue / observedSalesCount : 0;
  const topAcquisitionSource = [...acquisitionSources].sort((a, b) => toNumber(b.revenue) - toNumber(a.revenue))[0];
  const roiLabel = ratioLabel(summary.observed_roi ?? summary.estimated_roi);
  const strategicClaimRate = dashboard.derived?.strategic_claim_rate || summary.strategic_claim_rate || 0;
  const strategicRedemptionRate = dashboard.derived?.strategic_redemption_rate || summary.strategic_redemption_rate || 0;
  const postSaleRedemptionRate = dashboard.derived?.post_sale_redemption_rate || summary.post_sale_redemption_rate || 0;
  const items = [
    ["Listas para lanzar", summary.ready_for_client_setup, `${summary.scheduled_campaigns || 0} programadas`, "", "Campañas que ya estan estructuradas y pendientes de configuración final o fecha de arranque."],
    ["Campañas activas", summary.active_campaigns, `${state.campaigns.length || 0} registradas`, "", "Campañas actualmente en ejecución y generando interacciones medibles."],
    ["Leads capturados", summary.total_leads, `${summary.redemption_rate || 0}% termina redimiendo`, "", "Personas identificadas que dejaron datos válidos en formularios, juegos o landings."],
    ["Tickets generados", summary.total_qr_generated, `${dashboard.summary?.active_qr || 0} siguen activos`, "", "Beneficios emitidos. Ayuda a medir activación real después del lead."],
    ["Tickets redimidos", summary.total_qr_redeemed, `${summary.redemption_rate || 0}% del total emitido`, "", "Personas que si llegaron a tienda o punto de redención y usaron el incentivo."],
    ["ticket postventa", summary.post_sale_generated || 0, `${postSaleRedemptionRate}% redimido`, "", "Ticket creados desde una venta real para incentivar recompra o postventa."],
    ["Paquetes de tickets", summary.strategic_batches || 0, `${summary.strategic_generated || 0} códigos estratégicos`, "", "Lotes de tickets precreados para etiquetas, empaques, volantes o fidelización."],
    ["tickets estratégicos", summary.strategic_generated || 0, `${strategicClaimRate}% activado`, "", "Tickets no nacidos de juego o formulario público, sino de estrategias internas del negocio."],
    ["Claims estratégicos", summary.strategic_claimed_or_active || 0, `${strategicRedemptionRate}% redimido`, "", "Clientes que escanearon un ticket precreado, dejaron datos y activaron el beneficio."],
    ["Ventas reales", observedSalesCount, `${money(observedRevenue)} registrado`, "", "Compras reales registradas por caja, ticket postventa o captura manual del medio de llegada."],
    ["Revenue observado", money(observedRevenue), `${money(avgTicket)} ticket promedio`, "", "Dinero real asociado a clientes capturados por los distintos medios de llegada."],
    ["Referidos", summary.referral_sales_count || 0, `${summary.referral_points_awarded || 0} puntos entregados`, "", "Ventas que llegaron por recomendación y quedaron registradas."],
    ["Inversión total", money(summary.total_investment), `${money(summary.cost_per_lead)} por lead`, "", "Suma total invertida en pauta, creativos y activación para este periodo de analisis."],
    ["Costo por lead", money(summary.cost_per_lead), `${money(summary.cost_per_observed_customer || summary.cost_per_acquired_customer)} por venta`, "", "Cuanto costo captar cada lead, antes de saber si compro o no."],
    ["Costo por venta", money(summary.cost_per_observed_customer || summary.cost_per_acquired_customer), `vs. ticket medio ${money(avgTicket)}`, "", "Cuanto costo traer una venta real observada. Debe compararse contra ticket promedio y margen."],
    ["ROI estimado", roiLabel, "Retorno sobre ventas reales", "highlight", "Relacion entre ventas observadas e inversión. Un valor mayor a 1x ya recupera la inversión; por encima de eso empieza a devolver ganancia comercial."],
  ];

  businessKpiGrid.innerHTML = items.map(([label, value, meta, tone, help]) => `
    <article class="kpi-card ${tone}" title="${escapeHtml(help || "")}">
      <span class="mono-label">${escapeHtml(label)}</span>
      <strong>${escapeHtml(value ?? 0)}</strong>
      <div class="kpi-meta">${escapeHtml(meta || "")}</div>
    </article>
  `).join("");

  dashboardNarrativeTitle.textContent = topAcquisitionSource
    ? `${acquisitionSourceLabel(topAcquisitionSource.acquisition_source)} lidera la llegada comercial.`
    : topBranch?.branch_name
      ? `${topBranch.branch_name} lidera la operación del periodo.`
    : "Esperando datos del negocio.";
  dashboardNarrativeText.textContent = topAcquisitionSource
    ? `${acquisitionSourceLabel(topAcquisitionSource.acquisition_source)}${topAcquisitionSource.acquisition_channel ? ` / ${topAcquisitionSource.acquisition_channel}` : ""} trae ${toNumber(topAcquisitionSource.count)} ventas reales y ${money(topAcquisitionSource.revenue)}. El portal combina esta captura con tickets para medir ventas, no solo likes o comentarios.`
    : topBranch?.branch_name
      ? `La sucursal ${topBranch.branch_name} concentra ${money(topBranch.revenue)} en revenue atribuido y ${topBranch.redemptions} redenciones. Ademas, el negocio ya suma ${summary.post_sale_generated || 0} ticket postventa y ${summary.strategic_generated || 0} tickets estratégicos fuera del flujo público.`
    : "Cuando haya actividad, aquí verás el principal movimiento del periodo sin tener que interpretar todas las tablas.";
  dashboardFunnelHelp.textContent = `Hoy el embudo combina ${summary.total_leads || 0} leads publicos con ${summary.strategic_claimed_or_active || 0} activaciones estrategicas; de ahí salen ${summary.total_qr_generated || 0} tickets emitidos y ${observedSalesCount} ventas reales observadas.`;
  dashboardHealthText.textContent = roiLabel === "-"
    ? "Aún no hay ventas suficientes para evaluar ROI, CPL y CAC con criterio comercial."
    : `El ROI actual es ${roiLabel}, el costo por venta esta en ${money(summary.cost_per_observed_customer || summary.cost_per_acquired_customer)} y el ticket promedio ronda ${money(avgTicket)}. En tickets estratégicos, postventa redime ${postSaleRedemptionRate}% y los claims convierten ${strategicRedemptionRate}% a redención.`;
  cacTrendNote.innerHTML = avgTicket
    ? `<span>Benchmark visual</span><strong>CAC sano por debajo de ${escapeHtml(money(avgTicket))}</strong><small>Compáralo con ticket promedio, ROI y margen por campaña.</small>`
    : "<span>Benchmark visual</span><strong>Compara CAC contra ticket promedio</strong><small>Úsalo junto al ROI de cada campaña.</small>";

  recentRedemptionsTable.innerHTML = recentRedemptions.map((item) => `
    <tr>
      <td>${escapeHtml(item.player_name || "-")}</td>
      <td>${escapeHtml(item.reward_name || "-")}</td>
      <td>${escapeHtml(formatDate(item.redeemed_at))}</td>
      <td>${escapeHtml(item.validator || "-")}</td>
    </tr>
  `).join("") || '<tr><td colspan="4">Sin redenciones.</td></tr>';

  recentLeadsTable.innerHTML = recentPlayers.map((item) => `
    <tr>
      <td>${escapeHtml(item.name || "-")}</td>
      <td>${escapeHtml(item.email || "-")}</td>
      <td>${escapeHtml(item.phone || "-")}</td>
      <td>${escapeHtml(formatDate(item.created_at))}</td>
    </tr>
  `).join("") || '<tr><td colspan="4">Sin leads.</td></tr>';

  drawDualLineChart(
    businessTrendChart,
    dashboard.time_stats?.leads_by_day || [],
    dashboard.time_stats?.redemptions_by_day || [],
    "count",
    ["Leads", "Redenciones"],
    [NEON_CHART.cyan, NEON_CHART.magenta]
  );

  drawSimpleLineChart(
    cacTrendChart,
    filterRows(state.campaigns, ["name", "type", "objective", "status"]).map((campaign) => ({
      label: campaign.name,
      value: campaign.cost_per_lead === null ? 0 : toNumber(campaign.cost_per_lead),
    })),
    NEON_CHART.yellow,
    "Costo por lead"
  );

  drawTripleLineChart(
    hourlyOperationsChart,
    dashboard.time_stats?.qr_by_hour || [],
    (dashboard.time_stats?.claims_by_hour || []).some((row) => toNumber(row.count) > 0)
      ? dashboard.time_stats?.claims_by_hour || []
      : dashboard.time_stats?.validations_by_hour || [],
    dashboard.time_stats?.redemptions_by_hour || [],
    "count",
    (dashboard.time_stats?.claims_by_hour || []).some((row) => toNumber(row.count) > 0)
      ? ["Tickets", "Claims", "Redenciones"]
      : ["Tickets", "Validaciones", "Redenciones"],
    [NEON_CHART.cyan, NEON_CHART.yellow, NEON_CHART.magenta],
    (row) => `${String(row.hour).padStart(2, "0")}:00`
  );

  drawGroupedBars(
    weekdayPerformanceChart,
    (dashboard.time_stats?.qr_by_weekday || []).map((row, index) => ({
      label: row.label || ["Lun", "Mar", "Mie", "Jue", "Vie", "Sab", "Dom"][index],
      qr: toNumber(row.count),
      redemptions: toNumber(dashboard.time_stats?.redemptions_by_weekday?.[index]?.count),
    })),
    [
      { key: "qr", color: NEON_CHART.cyan, label: "Tickets generados" },
      { key: "redemptions", color: NEON_CHART.green, label: "Redenciones" },
    ]
  );

  drawDonutChart(
    qrStatusChart,
    qrStatus.map((row) => ({ label: row.status, value: toNumber(row.count) })),
    [NEON_CHART.cyan, NEON_CHART.green, NEON_CHART.yellow, NEON_CHART.magenta]
  );

  drawHorizontalBars(
    campaignPerformanceChart,
    (originPerformance.length ? originPerformance : campaignPerformance).map((row) => ({
      label: row.origin_type || row.campaign_name,
      value: toNumber(row.qr_generated),
      valueLabel: `${toNumber(row.qr_generated)} tickets`,
      meta: row.origin_type
        ? `${toNumber(row.claims)} claims | ${toNumber(row.redemptions)} redenciones`
        : `${toNumber(row.redemptions)} redenciones`,
    })),
    NEON_CHART.cyan
  );

  drawHorizontalBars(
    rewardMixChart,
    rewardPerformance.map((row) => ({
      label: row.name,
      value: toNumber(row.redeemed),
      valueLabel: `${toNumber(row.redeemed)} redenciones`,
      meta: `${toNumber(row.generated)} tickets`,
    })),
    NEON_CHART.green
  );

  drawHorizontalBars(
    paymentMethodChart,
    (acquisitionSources.length ? acquisitionSources : paymentMethods).map((row) => ({
      label: acquisitionSources.length
        ? `${acquisitionSourceLabel(row.acquisition_source)}${row.acquisition_channel && row.acquisition_channel !== "Sin canal especifico" ? ` / ${row.acquisition_channel}` : ""}`
        : row.payment_method,
      value: toNumber(row.revenue),
      valueLabel: money(row.revenue),
      meta: `${toNumber(row.count)} ventas${toNumber(row.referral_points_awarded) ? ` | ${toNumber(row.referral_points_awarded)} pts referidos` : ""}`,
    })),
    NEON_CHART.magenta
  );

  geoBranchBoard.innerHTML = branchPerformance.slice(0, 6).map((row) => `
    <article class="geo-branch-card">
      <span class="mono-label">Sucursal</span>
      <strong>${escapeHtml(row.branch_name || "Sin sucursal")}</strong>
      <p>${escapeHtml(row.address || "Sin dirección")}</p>
      <div class="geo-metric"><span>Redenciones</span><span>${escapeHtml(row.redemptions)}</span></div>
      <div class="geo-metric"><span>Ventas</span><span>${escapeHtml(row.sales)}</span></div>
      <div class="geo-metric"><span>Revenue</span><span>${escapeHtml(money(row.revenue))}</span></div>
    </article>
  `).join("") || '<article class="geo-branch-card"><strong>Sin datos</strong><p>No hay actividad por sucursal todavia.</p></article>';

  branchPerformanceTable.innerHTML = branchPerformance.map((row) => `
    <tr>
      <td>${escapeHtml(row.branch_name || "Sin sucursal")}</td>
      <td>${escapeHtml(row.address || "-")}</td>
      <td>${escapeHtml(row.redemptions)}</td>
      <td>${escapeHtml(row.sales)}</td>
      <td>${escapeHtml(money(row.revenue))}</td>
    </tr>
  `).join("") || '<tr><td colspan="5">Sin actividad por sucursal.</td></tr>';

  dashboardInsightTitle.textContent = topHour?.count
    ? `El pico de redenciones ocurre a las ${String(topHour.hour).padStart(2, "0")}:00. ${topAcquisitionSource ? `${acquisitionSourceLabel(topAcquisitionSource.acquisition_source)} lidera ventas reales con ${money(topAcquisitionSource.revenue)}.` : `${topBranch?.branch_name || "La sucursal principal"} lidera el revenue del periodo.`} Los tickets estratégicos ya aportan ${summary.strategic_claimed_or_active || 0} activaciones al embudo.`
    : "Aún no hay suficiente actividad para construir un insight horario.";
}

