    volante: "Volante",
    evento: "Evento",
    feria: "Feria",
    influencer: "Influencer",
    whatsapp: "WhatsApp",
    "redes-sociales": "Redes sociales",
    pauta: "Pauta",
    alianza: "Alianza",
    referido: "Referido",
    mostrador: "Mostrador",
    "punto-de-venta": "Punto de venta",
    STORE_WALK_IN: "Vitrina / llegada directa",
    FRIEND_REFERRAL: "Referido",
    FAIR_EVENT: "Feria o evento",
    INTERNET_SEARCH: "Internet / buscador",
