function salesCustomerIdentity(row = {}) {
  return normalizeInventoryLookup(
    cleanCustomerValue(row.document_id || row.customer_document_id)
    || cleanCustomerValue(row.phone || row.customer_phone)
    || cleanCustomerValue(row.email || row.customer_email)
    || cleanCustomerValue(row.name || row.player_name)
    || cleanCustomerValue(row.id)
  );
}

function cleanCustomerValue(value) {
  const text = String(value ?? "").trim();
  if (!text || ["-", "—", "n/a", "na", "null", "undefined", "sin dato", "sin datos"].includes(text.toLowerCase())) return "";
  return text;
}

function firstCustomerValue(...values) {
  return values.map(cleanCustomerValue).find(Boolean) || "";
}

function customerMoneyValue(value) {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  const raw = String(value ?? "").trim();
  if (!raw || raw === "-") return 0;
  const digits = raw.replace(/[^\d-]/g, "");
  return Number(digits || 0);
}

function latestDateValue(first, second) {
  const firstTime = first ? new Date(first).getTime() : 0;
  const secondTime = second ? new Date(second).getTime() : 0;
  if (!Number.isFinite(firstTime) || secondTime > firstTime) return second || first || "";
  return first || second || "";
}

function salesCustomerRows() {
  const rows = [
    ...(state.leadCrmRows || []).map((item) => ({
      id: item.id,
      name: cleanCustomerValue(item.name),
      document_id: cleanCustomerValue(item.document_id),
      phone: cleanCustomerValue(item.phone),
      email: cleanCustomerValue(item.email),
      campaign_id: item.campaign_id,
      campaign_name: item.campaign_name,
      purchase_count: Number(item.purchase_count || 0),
      total_spent: customerMoneyValue(item.total_spent),
      product_or_service: firstCustomerValue(item.top_product, item.product_or_service),
      branch_name: cleanCustomerValue(item.branch_name),
      event_date: item.last_purchase_at || item.last_interaction_at || item.created_at || "",
      is_affiliate: Boolean(item.is_affiliate),
      affiliate_id: item.affiliate_id || null,
      affiliate_name: firstCustomerValue(item.affiliate_name, item.affiliate_code),
      referral_points_awarded: customerMoneyValue(item.referral_points_awarded || item.points_total),
      source: Number(item.purchase_count || 0) > 0 ? "Cliente" : "Lead capturado",
    })),
    ...(state.contactFeed || []).map((item) => ({
      id: item.id,
      name: cleanCustomerValue(item.name),
      document_id: cleanCustomerValue(item.document_id),
      phone: cleanCustomerValue(item.phone),
      email: cleanCustomerValue(item.email),
      campaign_id: item.campaign_id,
      campaign_name: item.campaign_name,
      purchase_count: customerMoneyValue(item.sale_amount) > 0 ? 1 : 0,
      total_spent: customerMoneyValue(item.sale_amount),
      payment_method: firstCustomerValue(item.payment_method, item.payment, item.sale_payment_method),
      product_or_service: firstCustomerValue(item.product_or_service, item.product_name, item.reward_name, item.attribution_subject),
      branch_name: firstCustomerValue(item.branch_name, item.store_branch, item.location),
      event_date: item.sale_created_at || item.redeemed_at || item.created_at || "",
      is_affiliate: Boolean(item.is_affiliate),
      affiliate_id: item.affiliate_id || null,
      affiliate_name: cleanCustomerValue(item.affiliate_name),
      referral_points_awarded: customerMoneyValue(item.referral_points_awarded),
      source: item.attribution_source || "Lead",
    })),
    ...(state.selectedSales || []).map((item) => ({
      id: item.player_id || item.id,
      name: cleanCustomerValue(item.player_name),
      document_id: cleanCustomerValue(item.document_id),
      phone: cleanCustomerValue(item.phone),
      email: cleanCustomerValue(item.email),
      campaign_id: item.campaign_id,
      campaign_name: item.campaign_name,
      purchase_count: 1,
      total_spent: customerMoneyValue(item.sale_amount),
      payment_method: cleanCustomerValue(item.payment_method),
      product_or_service: firstCustomerValue(item.product_or_service, item.product_name),
      branch_name: cleanCustomerValue(item.branch_name),
      event_date: item.created_at || "",
      is_affiliate: Boolean(item.referred_affiliate_id),
      affiliate_id: item.referred_affiliate_id || null,
      affiliate_name: cleanCustomerValue(item.affiliate_name),
      referral_points_awarded: customerMoneyValue(item.referral_points_awarded),
      source: "Cliente",
    })),
    ...(state.affiliates || []).map((item) => ({
      id: item.id,
      name: cleanCustomerValue(item.full_name),
      document_id: cleanCustomerValue(item.document_id),
      phone: cleanCustomerValue(item.phone),
      email: cleanCustomerValue(item.email),
      campaign_id: null,
      campaign_name: "",
      purchase_count: Number(item.purchase_count || item.sales_count || 0),
      total_spent: customerMoneyValue(item.total_spent || item.sales_total),
      product_or_service: firstCustomerValue(item.top_product, item.product_or_service, item.notes),
      branch_name: firstCustomerValue(item.branch_name, item.store_branch),
      event_date: item.last_purchase_at || item.last_activity_at || item.created_at || "",
      is_affiliate: true,
      affiliate_id: item.id,
      affiliate_name: firstCustomerValue(item.full_name, item.name),
      referral_points_awarded: customerMoneyValue(item.points_total || item.ledger_points),
      source: "Afiliado",
    })),
  ];
  const byKey = new Map();
  rows.forEach((row) => {
    const key = salesCustomerIdentity(row);
    if (!key || !(row.name || row.document_id || row.phone || row.email)) return;
    const existing = byKey.get(key);
    if (!existing) {
      byKey.set(key, row);
      return;
    }
    byKey.set(key, {
      ...existing,
      ...row,
      name: firstCustomerValue(existing.name, row.name),
      document_id: firstCustomerValue(existing.document_id, row.document_id),
      phone: firstCustomerValue(existing.phone, row.phone),
      email: firstCustomerValue(existing.email, row.email),
      campaign_id: firstCustomerValue(existing.campaign_id, row.campaign_id),
      campaign_name: firstCustomerValue(existing.campaign_name, row.campaign_name),
      purchase_count: Math.max(Number(existing.purchase_count || 0), Number(row.purchase_count || 0)),
      total_spent: Math.max(Number(existing.total_spent || 0), Number(row.total_spent || 0)),
      payment_method: firstCustomerValue(existing.payment_method, row.payment_method),
      product_or_service: firstCustomerValue(existing.product_or_service, row.product_or_service),
      branch_name: firstCustomerValue(existing.branch_name, row.branch_name),
      event_date: latestDateValue(existing.event_date, row.event_date),
      is_affiliate: Boolean(existing.is_affiliate || row.is_affiliate),
      affiliate_id: firstCustomerValue(existing.affiliate_id, row.affiliate_id),
      affiliate_name: firstCustomerValue(existing.affiliate_name, row.affiliate_name),
      referral_points_awarded: Math.max(Number(existing.referral_points_awarded || 0), Number(row.referral_points_awarded || 0)),
      source: existing.source === "Cliente" || row.source === "Cliente" ? "Cliente" : (existing.source === "Afiliado" || row.source !== "Afiliado" ? existing.source : row.source),
    });
  });
  return Array.from(byKey.values());
}

function salesCustomerLookupValue(customer = {}) {
  const refs = [
    customer.phone ? `Teléfono: ${customer.phone}` : "",
    customer.document_id ? `Cédula: ${customer.document_id}` : "",
    Number(customer.total_spent || 0) > 0 ? `Valor: ${money(customer.total_spent || 0)}` : "",
    customer.payment_method ? `Pago: ${customer.payment_method}` : "",
    customer.source ? `Origen: ${acquisitionSourceLabel(customer.source)}` : "",
    customer.product_or_service ? `Producto: ${customer.product_or_service}` : "",
    customer.branch_name ? `Sucursal: ${customer.branch_name}` : "",
    customer.event_date ? `Fecha: ${formatDate(customer.event_date)}` : "",
    Number(customer.referral_points_awarded || 0) > 0 ? `Puntos: ${Number(customer.referral_points_awarded || 0).toLocaleString("es-CO")}` : "",
    customer.email ? `Email: ${customer.email}` : "",
  ].filter(Boolean).join(" · ");
  return refs ? `${customer.name || "Cliente"} · ${refs}` : (customer.name || "");
}

function salesCustomerKey(customer = {}) {
  return salesCustomerIdentity(customer);
}

function salesCustomerSearchText(customer = {}) {
  return [
    salesCustomerLookupValue(customer),
    customer.name,
    customer.document_id,
    customer.phone,
    customer.email,
    customer.campaign_name,
    customer.product_or_service,
    customer.branch_name,
    customer.event_date,
    customer.event_date ? formatDate(customer.event_date) : "",
    customer.referral_points_awarded,
    customer.source,
  ].map(normalizeInventoryLookup).filter(Boolean).join(" ");
}

function filteredSalesCustomerRows(filter = customerAcquisitionCustomerLookupInput?.value || "") {
  const needle = normalizeInventoryLookup(filter);
  const rows = salesCustomerRows();
  if (!needle) return rows;
  return rows.filter((customer) => salesCustomerSearchText(customer).includes(needle));
}

function salesCustomerSelectLabel(customer = {}) {
  const flags = [
    customer.campaign_name || "",
  ].filter(Boolean).join(" · ");
  const customerLine = salesCustomerLookupValue(customer);
  return flags ? `${customerLine} · ${flags}` : customerLine;
}

function setSalesCustomerStatus(title, detail = "", tone = "neutral", icon = "person_add") {
  if (!customerAcquisitionCustomerStatus) return;
  customerAcquisitionCustomerStatus.classList.remove("is-success", "is-warning", "is-error");
  if (tone === "success") customerAcquisitionCustomerStatus.classList.add("is-success");
  if (tone === "warning") customerAcquisitionCustomerStatus.classList.add("is-warning");
  if (tone === "error") customerAcquisitionCustomerStatus.classList.add("is-error");
  customerAcquisitionCustomerStatus.innerHTML = `
    <span class="material-symbols-outlined" aria-hidden="true">${escapeHtml(icon)}</span>
    <div>
      <strong>${escapeHtml(title || "Cliente nuevo / manual")}</strong>
      <small>${escapeHtml(detail || "Completa los datos del cliente si no viene de la base de contactos.")}</small>
    </div>
  `;
}

function renderSalesCustomerOptions() {
  const customers = salesCustomerRows();
  if (!customerAcquisitionCustomerSelect) return;
  const current = customerAcquisitionCustomerSelect.value;
  const filtered = filteredSalesCustomerRows();
  const isLoadingCustomers = !state.contactFeedLoaded || !state.leadCrmLoaded;
  const emptyLabel = isLoadingCustomers
    ? "Cargando clientes..."
    : (customers.length ? "Sin coincidencias para el filtro" : "Sin clientes registrados");
  customerAcquisitionCustomerSelect.innerHTML = [
    '<option value="">Cliente nuevo / manual</option>',
    ...(filtered.length
      ? filtered.map((customer) => `<option value="${escapeHtml(salesCustomerKey(customer))}">${escapeHtml(salesCustomerSelectLabel(customer))}</option>`)
      : [`<option value="" disabled>${escapeHtml(emptyLabel)}</option>`]),
  ].join("");
  if (current && filtered.some((customer) => salesCustomerKey(customer) === current)) {
    customerAcquisitionCustomerSelect.value = current;
  } else if (current) {
    customerAcquisitionCustomerSelect.value = "";
  }
}

function findSalesCustomerByKey(key) {
  const normalizedKey = normalizeInventoryLookup(key);
  if (!normalizedKey) return null;
  return salesCustomerRows().find((customer) => salesCustomerKey(customer) === normalizedKey) || null;
}

function findUniquePartialSalesCustomer(value) {
  const needle = normalizeInventoryLookup(value);
  if (!needle) return null;
  const matches = filteredSalesCustomerRows(needle);
  return matches.length === 1 ? matches[0] : null;
}

function syncSalesCustomerSelect(customer = {}) {
  if (!customerAcquisitionCustomerSelect || !customer) return;
  const key = salesCustomerKey(customer);
  renderSalesCustomerOptions();
  if (key) customerAcquisitionCustomerSelect.value = key;
}

function applySalesCustomer(customerOrValue) {
  const customer = typeof customerOrValue === "object" && customerOrValue
    ? customerOrValue
    : findSalesCustomer(customerOrValue);
  if (!customer) return false;
  if (customerAcquisitionCustomerLookupInput) customerAcquisitionCustomerLookupInput.value = salesCustomerLookupValue(customer);
  syncSalesCustomerSelect(customer);
  if (customerAcquisitionNameInput) customerAcquisitionNameInput.value = customer.name || "";
  if (customerAcquisitionDocumentInput) customerAcquisitionDocumentInput.value = customer.document_id || "";
  if (customerAcquisitionPhoneInput) customerAcquisitionPhoneInput.value = customer.phone || "";
  if (customerAcquisitionEmailInput) customerAcquisitionEmailInput.value = customer.email || "";
  if (customerAcquisitionCampaignInput && customer.campaign_id) {
    customerAcquisitionCampaignInput.value = customer.campaign_id;
  }
  if (customerAcquisitionAffiliateInput) customerAcquisitionAffiliateInput.value = "";
  setSalesCustomerStatus("Cliente seleccionado", "Datos cargados en el formulario para registrar la venta.", "success", "check_circle");
  setInlineMessage(customerAcquisitionMessage, "Cliente seleccionado. Revisa campaña, canal, producto y valor antes de guardar.", "info");
  return true;
}

function renderSalesCustomerMatchesHint() {
  if (!customerAcquisitionMessage) return;
  const search = customerAcquisitionCustomerLookupInput?.value || "";
  if (!search.trim()) {
    if (!customerAcquisitionCustomerSelect?.value) {
      setSalesCustomerStatus("Cliente nuevo / manual", "Completa los datos del cliente si no viene de la base de contactos.", "neutral", "person_add");
    }
    return;
  }
  const matches = filteredSalesCustomerRows(search);
  if (matches.length > 1) {
    setSalesCustomerStatus(`${matches.length} coincidencias encontradas`, "Selecciona el contacto correcto en Coincidencia en base.", "warning", "manage_search");
    setInlineMessage(customerAcquisitionMessage, `${matches.length} clientes coinciden. Selecciona el correcto en el desplegable "Cliente".`, "info");
  } else if (!matches.length) {
    setSalesCustomerStatus("Cliente nuevo / manual", "No hay coincidencias en la base. Puedes registrar los datos manualmente.", "warning", "person_add");
    setInlineMessage(customerAcquisitionMessage, "No hay cliente existente con esa busqueda. Puedes registrarlo como cliente nuevo/manual.", "info");
  } else {
    setSalesCustomerStatus("Coincidencia lista", "Puedes confirmar el cliente o seguir escribiendo para acotar la busqueda.", "success", "person_search");
  }
}

function handleSalesCustomerSearchInput() {
  renderSalesCustomerOptions();
  renderSalesCustomerMatchesHint();
}

function handleSalesCustomerSearchCommit() {
  const value = customerAcquisitionCustomerLookupInput?.value || "";
  const exact = findSalesCustomer(value);
  const unique = exact || findUniquePartialSalesCustomer(value);
  if (unique) {
    applySalesCustomer(unique);
    return;
  }
  renderSalesCustomerOptions();
  renderSalesCustomerMatchesHint();
}

function handleSalesCustomerSelectChange() {
  const customer = findSalesCustomerByKey(customerAcquisitionCustomerSelect?.value || "");
  if (!customer) {
    const autoSelectedId = customerAcquisitionAffiliateInput?.dataset.autoSelectedAffiliateId || "";
    if (autoSelectedId && customerAcquisitionAffiliateInput?.value === autoSelectedId) {
      customerAcquisitionAffiliateInput.value = "";
      customerAcquisitionAffiliateInput.dataset.autoSelectedAffiliateId = "";
    }
    setSalesCustomerStatus("Cliente nuevo / manual", "Completa los datos del cliente si no viene de la base de contactos.", "neutral", "person_add");
    return;
  }
  applySalesCustomer(customer);
}

function resolveCustomerBeforeSaleSubmit() {
  const lookup = String(customerAcquisitionCustomerLookupInput?.value || "").trim();
  const selectedKey = customerAcquisitionCustomerSelect?.value || "";
  if (selectedKey) {
    return Boolean(applySalesCustomer(findSalesCustomerByKey(selectedKey)));
  }
  if (!lookup) return true;
  const exact = findSalesCustomer(lookup);
  if (exact) return Boolean(applySalesCustomer(exact));
  const matches = filteredSalesCustomerRows(lookup);
  if (matches.length === 1) return Boolean(applySalesCustomer(matches[0]));
  if (matches.length > 1) {
    setInlineMessage(customerAcquisitionMessage, `Hay ${matches.length} clientes que coinciden con "${lookup}". Selecciona el cliente correcto o borra la busqueda para registrar uno nuevo.`, "error");
    customerAcquisitionCustomerSelect?.focus();
    return false;
  }
  return true;
}

function hasCustomerIdentityForSale() {
  return [
    customerAcquisitionNameInput?.value,
    customerAcquisitionDocumentInput?.value,
    customerAcquisitionPhoneInput?.value,
    customerAcquisitionEmailInput?.value,
  ].some((value) => String(value || "").trim());
}

function findSalesCustomer(value) {
  const needle = normalizeInventoryLookup(value);
  if (!needle) return null;
  return salesCustomerRows().find((customer) => {
    const candidates = [
      salesCustomerLookupValue(customer),
      customer.name,
      customer.document_id,
      customer.phone,
      customer.email,
    ].map(normalizeInventoryLookup);
    return candidates.includes(needle);
  }) || null;
}

function findAffiliateByCustomerFields(customer = {}) {
  const directId = normalizeInventoryLookup(customer.affiliate_id);
  const documentId = normalizeInventoryLookup(customer.document_id || customer.customer_document_id);
  const phone = normalizeInventoryLookup(customer.phone || customer.customer_phone);
  const email = normalizeInventoryLookup(customer.email || customer.customer_email);
  if (!directId && !documentId && !phone && !email) return null;
  return (state.affiliates || []).find((affiliate) => {
    if (affiliate.status === "INACTIVE" || affiliate.status === "DELETED") return false;
    if (directId && normalizeInventoryLookup(affiliate.id) === directId) return true;
    if (documentId && normalizeInventoryLookup(affiliate.document_id) === documentId) return true;
    if (phone && normalizeInventoryLookup(affiliate.phone) === phone) return true;
    if (email && normalizeInventoryLookup(affiliate.email) === email) return true;
    return false;
  }) || null;
}

function syncCustomerAffiliateSelection(customer = {}) {
  if (!customerAcquisitionAffiliateInput) return null;
  const autoSelectedId = customerAcquisitionAffiliateInput.dataset.autoSelectedAffiliateId || "";
  if (customerAcquisitionAffiliateInput.value && customerAcquisitionAffiliateInput.value !== autoSelectedId) return null;
  const affiliate = findAffiliateByCustomerFields(customer);
  if (!affiliate) {
    if (autoSelectedId && customerAcquisitionAffiliateInput.value === autoSelectedId) {
      customerAcquisitionAffiliateInput.value = "";
      customerAcquisitionAffiliateInput.dataset.autoSelectedAffiliateId = "";
    }
    return null;
  }
  customerAcquisitionAffiliateInput.value = affiliate.id;
  customerAcquisitionAffiliateInput.dataset.autoSelectedAffiliateId = affiliate.id;
  return affiliate;
}

function applySalesCustomerToForm(value) {
  return applySalesCustomer(value);
}

function defaultCustomerSaleItem() {
  return { name: "", quantity: 1, unit_price: 0, inventory_product_id: null, sku: null, barcode: null, is_open_product: false };
}

function ensureCustomerSaleItems() {
  if (!Array.isArray(state.customerSaleItems) || !state.customerSaleItems.length) {
    state.customerSaleItems = [defaultCustomerSaleItem()];
  }
  state.customerSaleItems = state.customerSaleItems.map((item) => ({
    ...defaultCustomerSaleItem(),
    ...item,
    quantity: Math.max(1, Number(item.quantity || 1)),
    unit_price: Math.max(0, Number(item.unit_price || 0)),
  }));
}

function customerSaleLineTotal(item = {}) {
  return Math.max(1, Number(item.quantity || 1)) * Math.max(0, Number(item.unit_price || 0));
}

function customerSaleTotal() {
  ensureCustomerSaleItems();
  return state.customerSaleItems.reduce((sum, item) => sum + customerSaleLineTotal(item), 0);
}

function commerceFeedStep(status, title, copy, actionLabel = "", action = "") {
  const icon = status === "done" ? "check_circle" : status === "active" ? "radio_button_checked" : "radio_button_unchecked";
  return `
    <article class="commerce-feed-step is-${escapeHtml(status || "pending")}">
      <span class="material-symbols-outlined" aria-hidden="true">${escapeHtml(icon)}</span>
      <div>
        <strong>${escapeHtml(title || "")}</strong>
        <p>${escapeHtml(copy || "")}</p>
      </div>
      ${actionLabel && action ? `<button class="ghost-button compact" type="button" data-commerce-feed-action="${escapeHtml(action)}">${escapeHtml(actionLabel)}</button>` : ""}
    </article>
  `;
}

function bindCommerceFeedActions(container) {
  container?.querySelectorAll("[data-commerce-feed-action]").forEach((button) => {
    button.addEventListener("click", () => {
      const action = button.dataset.commerceFeedAction || "";
      if (action === "sales-add-product") {
        customerSaleAddItemButton?.click();
        return;
      }
      if (action === "sales-focus-customer") {
        customerAcquisitionCustomerLookupInput?.focus();
        return;
      }
      if (action === "sales-save") {
        customerAcquisitionForm?.querySelector("button[type='submit']")?.focus();
        return;
      }
      if (action === "affiliate-add-product") {
        affiliatePurchaseAddItemButton?.click();
        return;
      }
      if (action === "affiliate-focus-search") {
        affiliateFinderInput?.focus();
        return;
      }
      if (action === "affiliate-save") {
        affiliateAddPointsButton?.focus();
        return;
      }
      if (action === "inventory") {
        setView("inventory");
        return;
      }
      if (action === "sales") {
        setView("sales");
      }
    });
  });
}

function saleOpenProductCount(products = []) {
  return products.filter((product) => product.name && !product.inventory_product_id).length;
}

function renderCustomerSaleOperationFeed() {
  if (!customerSaleOperationFeed) return;
  const products = customerSaleProductsPayload();
  const total = customerSaleTotal();
  const openCount = saleOpenProductCount(products);
  const hasCustomer = hasCustomerIdentityForSale();
  const hasAttribution = Boolean(customerAcquisitionSourceInput?.value || customerAcquisitionChannelInput?.value?.trim() || customerAcquisitionCampaignInput?.value);
  const ready = hasCustomer && products.length && total > 0;
  customerSaleOperationFeed.innerHTML = `
    <div class="commerce-feed-head compact">
      <span class="mono-label">Estado</span>
      <strong>${ready ? "Venta lista para registrar" : "Completa cliente y productos"}</strong>
      <small>${products.length ? `${products.length} producto${products.length === 1 ? "" : "s"} · ${money(total)}` : "Sin productos con precio"}</small>
    </div>
    <div class="sales-entry-checks">
      <span class="${hasCustomer ? "is-ok" : ""}">Cliente</span>
      <span class="${products.length ? "is-ok" : ""}">Productos</span>
      <span class="${hasAttribution ? "is-ok" : ""}">Atribución</span>
      ${openCount ? `<span class="is-warning">${openCount} nuevo${openCount === 1 ? "" : "s"}</span>` : ""}
    </div>
  `;
}

function syncCustomerSaleTotal() {
  const total = customerSaleTotal();
  if (customerAcquisitionAmountInput) customerAcquisitionAmountInput.value = total ? String(total) : "";
  if (customerSaleTotalPreview) customerSaleTotalPreview.textContent = money(total);
  if (salesCreateTotalPill) {
    salesCreateTotalPill.textContent = total ? money(total) : "Sin total";
    salesCreateTotalPill.classList.toggle("has-total", total > 0);
  }
  renderCustomerSaleOperationFeed();
  return total;
}

function openSalesCreatePanel(options = {}) {
  if (!salesCreatePanel) return;
  salesCreatePanel.classList.add("is-open");
  document.body.classList.add("has-sales-entry-modal");
  mountSalesCreateModal();
  salesCreateTrigger?.setAttribute("aria-expanded", "true");
  if (options.focus !== false) {
    window.requestAnimationFrame(() => customerAcquisitionCustomerLookupInput?.focus());
  }
}

function closeSalesCreatePanel(options = {}) {
  if (!salesCreatePanel) return;
  salesCreatePanel.classList.remove("is-open");
  document.body.classList.remove("has-sales-entry-modal");
  unmountSalesCreateModal();
  salesCreateTrigger?.setAttribute("aria-expanded", "false");
  if (options.scroll) {
    salesCreatePanel.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }
}

function ensureSalesCreateAnchor(element, id) {
  if (!element?.parentElement) return null;
  let anchor = document.getElementById(id);
  if (!anchor) {
    anchor = document.createElement("span");
    anchor.id = id;
    anchor.hidden = true;
    element.parentElement.insertBefore(anchor, element);
  }
  return anchor;
}

function salesCreateModalOverlay() {
  let overlay = document.getElementById("salesEntryModalOverlay");
  if (overlay) return overlay;
  overlay = document.createElement("section");
  overlay.id = "salesEntryModalOverlay";
  overlay.className = "sales-entry-modal-overlay hidden";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-labelledby", "salesEntryModalTitle");
  overlay.innerHTML = `
    <div class="sales-entry-modal-backdrop" data-sales-modal-close></div>
    <article class="sales-entry-modal-card" role="document">
      <header class="sales-entry-modal-head">
        <div>
          <span class="mono-label">Registro de venta</span>
          <h3 id="salesEntryModalTitle">Registrar venta completa</h3>
          <p>Ingresa cliente, productos, campaña, canal, sede y notas en una sola ventana.</p>
        </div>
        <button class="ghost-button compact" type="button" data-sales-modal-close>Cerrar</button>
      </header>
      <div class="sales-entry-modal-body" data-sales-entry-modal-body></div>
    </article>
  `;
  overlay.addEventListener("click", (event) => {
    if (event.target?.closest?.("[data-sales-modal-close]")) closeSalesCreatePanel();
  });
  document.body.appendChild(overlay);
  return overlay;
}

function mountSalesCreateModal() {
  if (!salesCreatePanel || !customerAcquisitionForm) return;
  const overlay = salesCreateModalOverlay();
  const modalBody = overlay.querySelector("[data-sales-entry-modal-body]");
  const explainer = salesCreatePanel.querySelector(".chart-explainer");
  ensureSalesCreateAnchor(explainer, "salesCreateExplainerAnchor");
  ensureSalesCreateAnchor(customerAcquisitionForm, "salesCreateFormAnchor");
  if (explainer && modalBody && explainer.parentElement !== modalBody) modalBody.appendChild(explainer);
  if (modalBody && customerAcquisitionForm.parentElement !== modalBody) modalBody.appendChild(customerAcquisitionForm);
  overlay.classList.remove("hidden");
  overlay.hidden = false;
  salesCreatePanel.style.visibility = "hidden";
}

function restoreSalesCreateElement(element, anchorId) {
  const anchor = document.getElementById(anchorId);
  if (!element || !anchor?.parentElement || element.parentElement === anchor.parentElement) return;
  anchor.parentElement.insertBefore(element, anchor.nextSibling);
}

function unmountSalesCreateModal() {
  const overlay = document.getElementById("salesEntryModalOverlay");
  const explainer = overlay?.querySelector(".chart-explainer") || salesCreatePanel?.querySelector(".chart-explainer");
  restoreSalesCreateElement(explainer, "salesCreateExplainerAnchor");
  restoreSalesCreateElement(customerAcquisitionForm, "salesCreateFormAnchor");
  if (overlay) {
    overlay.classList.add("hidden");
    overlay.hidden = true;
  }
  if (salesCreatePanel) salesCreatePanel.style.visibility = "";
}

function customerSaleProductsPayload() {
  ensureCustomerSaleItems();
  return state.customerSaleItems
    .map((item) => {
      const name = String(item.name || "").trim();
      const quantity = Math.max(1, Number(item.quantity || 1));
      const unitPrice = Math.max(0, Number(item.unit_price || 0));
      if (!name || unitPrice <= 0) return null;
      const product = item.inventory_product_id ? (state.inventoryProducts || []).find((candidate) => String(candidate.id) === String(item.inventory_product_id)) : findInventoryProduct(name);
      const payload = product ? productSalePayload(product, quantity, unitPrice) : {
        inventory_product_id: null,
        name,
        sku: item.sku || null,
        barcode: item.barcode || null,
        quantity,
        unit_price: unitPrice,
        line_total: quantity * unitPrice,
      };
      return payload;
    })
    .filter(Boolean);
}

function customerSaleProductSummary(products = customerSaleProductsPayload()) {
  if (!products.length) return "";
  if (products.length === 1) return products[0].name;
  return `${products.length} productos`;
}

function updateCustomerSaleItem(index, field, value, options = {}) {
  ensureCustomerSaleItems();
  const item = state.customerSaleItems[index];
  if (!item) return;
  if (field === "product_select") {
    const product = findInventoryProduct(value);
    if (product) {
      item.inventory_product_id = product.id;
      item.name = product.name;
      item.is_open_product = false;
      item.sku = product.sku || null;
      item.barcode = product.barcode || null;
      if (!Number(item.unit_price || 0)) item.unit_price = Number(product.unit_price || 0);
      if (customerAcquisitionCurrencyInput && product.currency) customerAcquisitionCurrencyInput.value = product.currency;
    } else {
      item.inventory_product_id = null;
      item.sku = null;
      item.barcode = null;
      item.is_open_product = value === OPEN_PRODUCT_VALUE;
      if (value !== OPEN_PRODUCT_VALUE) item.name = "";
    }
  }
  if (field === "name") {
    item.name = value;
    item.is_open_product = true;
    const product = options.matchProduct ? findInventoryProduct(value) : null;
    if (product) {
      item.inventory_product_id = product.id;
      item.name = product.name;
      item.is_open_product = false;
      item.sku = product.sku || null;
      item.barcode = product.barcode || null;
      if (!Number(item.unit_price || 0)) item.unit_price = Number(product.unit_price || 0);
      if (customerAcquisitionCurrencyInput && product.currency) customerAcquisitionCurrencyInput.value = product.currency;
    } else if (options.matchProduct) {
      item.inventory_product_id = null;
      item.sku = null;
      item.barcode = null;
      item.is_open_product = true;
    }
  }
  if (field === "quantity") item.quantity = Math.max(1, Number(value || 1));
  if (field === "unit_price") item.unit_price = Math.max(0, Number(value || 0));
  syncCustomerSaleTotal();
}

function renderCustomerSaleItems() {
  if (!customerSaleItemsContainer) return;
  ensureCustomerSaleItems();
  customerSaleItemsContainer.innerHTML = state.customerSaleItems.map((item, index) => {
    const isOpenProduct = !item.inventory_product_id && (item.is_open_product || item.name);
    const productLabel = item.inventory_product_id ? "Producto registrado" : isOpenProduct ? "Se creará en Productos" : "Producto";
    const selectedProductValue = item.inventory_product_id ? `inventory:${item.inventory_product_id}` : (isOpenProduct ? OPEN_PRODUCT_VALUE : "");
    return `
      <div class="sales-item-row" data-sale-item-index="${index}">
        <label class="sales-item-product">
          <span>Producto</span>
          <select data-sale-item-field="product_select" data-product-select>${inventoryProductSelectOptions(selectedProductValue, { placeholder: "Seleccionar producto" })}</select>
          <input class="open-product-input ${selectedProductValue === OPEN_PRODUCT_VALUE ? "" : "hidden"}" type="text" value="${escapeHtml(item.inventory_product_id ? "" : item.name || "")}" placeholder="Producto abierto o servicio" data-sale-item-field="name" data-open-product-input ${selectedProductValue === OPEN_PRODUCT_VALUE ? "" : "disabled"}>
          ${selectedProductValue === OPEN_PRODUCT_VALUE ? '<small>Al guardar la venta, este producto quedará creado automáticamente en Productos.</small>' : ""}
        </label>
        <label class="sales-item-quantity">
          <span>Cant.</span>
          <input type="number" min="1" step="1" value="${escapeHtml(item.quantity || 1)}" data-sale-item-field="quantity">
        </label>
        <label class="sales-item-price">
          <span>Precio unitario</span>
          <input type="number" min="0" step="0.01" value="${escapeHtml(item.unit_price || 0)}" data-sale-item-field="unit_price">
        </label>
        <div class="sales-item-total">
          <span>${escapeHtml(productLabel)}</span>
          <strong>${escapeHtml(money(customerSaleLineTotal(item)))}</strong>
        </div>
        <button class="ghost-button danger-button compact" type="button" data-sale-item-remove="${index}">Quitar producto</button>
      </div>
    `;
  }).join("");
  customerSaleItemsContainer.querySelectorAll("[data-sale-item-field]").forEach((input) => {
    input.addEventListener("input", () => {
      const row = input.closest("[data-sale-item-index]");
      updateCustomerSaleItem(Number(row?.dataset.saleItemIndex || 0), input.dataset.saleItemField, input.value);
    });
    input.addEventListener("change", () => {
      const row = input.closest("[data-sale-item-index]");
      updateCustomerSaleItem(Number(row?.dataset.saleItemIndex || 0), input.dataset.saleItemField, input.value, { matchProduct: input.dataset.saleItemField === "name" });
      renderCustomerSaleItems();
    });
  });
  customerSaleItemsContainer.querySelectorAll("[data-sale-item-remove]").forEach((button) => {
    button.disabled = state.customerSaleItems.length <= 1;
    button.addEventListener("click", () => {
      state.customerSaleItems.splice(Number(button.dataset.saleItemRemove || 0), 1);
      renderCustomerSaleItems();
    });
  });
  syncCustomerSaleTotal();
}

function saleSourceLabel(source) {
  if (source === "CONTACT_CENTER") return "Contacto convertido";
  if (source === "REDEMPTION") return "Redención";
  return source || "-";
}

function saleMetadata(item = {}) {
  if (!item.metadata) return {};
  if (typeof item.metadata === "object") return item.metadata;
  try {
    return JSON.parse(item.metadata);
  } catch {
    return {};
  }
}

function saleProductsForDisplay(item = {}) {
  const metadata = saleMetadata(item);
  return Array.isArray(metadata.products) ? metadata.products : [];
}

function saleProductSummary(item = {}) {
  const products = saleProductsForDisplay(item);
  if (!products.length) return escapeHtml(item.product_or_service || "-");
  const summary = products.map((product) => {
    const quantity = Number(product.quantity || 1);
    const lineTotal = Number(product.line_total || (Number(product.unit_price || 0) * quantity));
    return `${escapeHtml(product.name || "Producto")} <span class="table-secondary">x${quantity} · ${escapeHtml(money(lineTotal))}</span>`;
  }).join("<br>");
  const title = cleanCustomerValue(item.product_or_service);
  const firstProductName = cleanCustomerValue(products[0]?.name);
  const duplicatesSingleProduct = products.length === 1 && normalizeInventoryLookup(title) === normalizeInventoryLookup(firstProductName);
  const titleLooksLikeProductsList = products.length > 1 && products.every((product) => normalizeInventoryLookup(title).includes(normalizeInventoryLookup(`${product.name || ""} x${Number(product.quantity || 1)}`)));
  if (!title || duplicatesSingleProduct || titleLooksLikeProductsList) return summary;
  return `<strong>${escapeHtml(title || `${products.length} productos`)}</strong><br>${summary}`;
}

function saleProductPlainText(item = {}) {
  const products = saleProductsForDisplay(item);
  const productNames = products.map((product) => [
    product.name,
    product.category,
    product.sku,
  ].filter(Boolean).join(" ")).filter(Boolean);
  return [
    item.product_or_service,
    item.product_name,
    item.top_product,
    ...productNames,
  ].map((value) => String(value || "").trim()).filter(Boolean).join(" · ") || "Sin producto";
}

function saleCustomerText(item = {}) {
  return [
    item.player_name,
    item.customer_name,
    item.document_id,
    item.customer_document_id,
    item.phone,
    item.customer_phone,
    item.customer_email,
  ].map((value) => String(value || "").trim()).filter(Boolean).join(" · ") || "Cliente sin nombre";
}

function saleCampaignText(item = {}) {
  return String(item.campaign_name || state.selectedCampaign?.name || "Sin campaña").trim() || "Sin campaña";
}

function saleBranchText(item = {}) {
  return String(item.branch_name || "Sin sede").trim() || "Sin sede";
}

function saleChannelText(item = {}) {
  return String(item.acquisition_channel || item.channel || "Sin canal").trim() || "Sin canal";
}

function saleDetailKey(item = {}, index = 0) {
  return String(
    item.id
    || item.sale_id
    || item.customer_acquisition_sale_id
    || item.redemption_id
    || `${item.created_at || ""}::${item.player_name || item.customer_name || ""}::${item.sale_amount || 0}::${index}`,
  );
}

function saleByDetailKey(key = "", rows = state.salesDetailRows || state.selectedSales || []) {
  return (rows || []).find((item, index) => saleDetailKey(item, index) === key) || null;
}

function saleDetailValue(value) {
  if (value === null || value === undefined || value === "") return "-";
  if (Array.isArray(value)) return value.length ? value.map((item) => saleDetailValue(item)).join(" · ") : "-";
  if (typeof value === "object") {
    try {
      return JSON.stringify(value, null, 2);
    } catch {
      return String(value);
    }
  }
  return String(value);
}

function saleDetailField(label = "", value = "") {
  return `<article><span>${escapeHtml(label)}</span><strong>${escapeHtml(saleDetailValue(value))}</strong></article>`;
}

function saleDetailProductsMarkup(item = {}) {
  const products = saleProductsForDisplay(item);
  if (!products.length) {
    return `<article class="sales-detail-product-row"><strong>${escapeHtml(item.product_or_service || "Sin producto")}</strong><small>Producto registrado en la venta</small><b>${escapeHtml(money(item.sale_amount || 0))}</b></article>`;
  }
  return products.map((product) => {
    const quantity = Number(product.quantity || 1);
    const unitPrice = Number(product.unit_price || 0);
    const lineTotal = Number(product.line_total || (unitPrice * quantity));
    return `
      <article class="sales-detail-product-row">
        <strong>${escapeHtml(product.name || "Producto")}</strong>
        <small>${escapeHtml([product.category, product.sku].filter(Boolean).join(" · ") || `Cantidad ${quantity} · Unitario ${money(unitPrice)}`)}</small>
        <b>${escapeHtml(money(lineTotal))}</b>
      </article>
    `;
  }).join("");
}

function saleDetailAllDataRows(item = {}) {
  const metadata = saleMetadata(item);
  const ignored = new Set(["metadata"]);
  const rows = Object.entries(item || {})
    .filter(([key]) => !ignored.has(key))
    .map(([key, value]) => `<tr><th>${escapeHtml(key)}</th><td><pre>${escapeHtml(saleDetailValue(value))}</pre></td></tr>`);
  Object.entries(metadata || {}).forEach(([key, value]) => {
    rows.push(`<tr><th>${escapeHtml(`metadata.${key}`)}</th><td><pre>${escapeHtml(saleDetailValue(value))}</pre></td></tr>`);
  });
  return rows.join("") || '<tr><td colspan="2">Sin datos adicionales.</td></tr>';
}

function ensureSalesDetailModal() {
  let modal = document.getElementById("salesDetailModal");
  if (modal) return modal;
  modal = document.createElement("div");
  modal.id = "salesDetailModal";
  modal.className = "sales-detail-modal hidden";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-labelledby", "salesDetailTitle");
  modal.innerHTML = `
    <div class="sales-detail-backdrop" data-sales-detail-close></div>
    <section class="sales-detail-card" role="document">
      <button class="icon-button sales-detail-close" type="button" data-sales-detail-close aria-label="Cerrar detalle de venta">
        <span class="material-symbols-outlined" aria-hidden="true">close</span>
      </button>
      <div id="salesDetailContent"></div>
    </section>
  `;
  modal.addEventListener("click", (event) => {
    if (event.target.closest("[data-sales-detail-close]")) closeSalesDetailModal();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !modal.classList.contains("hidden")) closeSalesDetailModal();
  });
  document.body.appendChild(modal);
  return modal;
}

function closeSalesDetailModal() {
  const modal = document.getElementById("salesDetailModal");
  modal?.classList.add("hidden");
  document.body.classList.remove("has-sales-detail-modal");
}

function openSalesDetailModal(key = "") {
  const item = saleByDetailKey(key);
  if (!item) return;
  const modal = ensureSalesDetailModal();
  const content = modal.querySelector("#salesDetailContent");
  const amount = money(item.sale_amount || 0);
  const products = saleProductsForDisplay(item);
  content.innerHTML = `
    <header class="sales-detail-head">
      <span class="mono-label">Detalle de venta</span>
      <h3 id="salesDetailTitle">${escapeHtml(item.player_name || item.customer_name || "Venta atribuida")}</h3>
      <p>${escapeHtml(formatDate(item.created_at))} · ${escapeHtml(amount)} · ${escapeHtml(saleCampaignText(item))}</p>
    </header>
    <section class="sales-detail-hero">
      ${saleDetailField("Valor", amount)}
      ${saleDetailField("Fecha", formatDate(item.created_at))}
      ${saleDetailField("Campaña", saleCampaignText(item))}
      ${saleDetailField("Canal", saleChannelText(item))}
      ${saleDetailField("Medio", saleSourceLabel(item.sale_source))}
      ${saleDetailField("Sede", saleBranchText(item))}
    </section>
    <section class="sales-detail-section">
      <h4>Cliente</h4>
      <div class="sales-detail-grid">
        ${saleDetailField("Nombre", item.player_name || item.customer_name)}
        ${saleDetailField("Documento", item.document_id || item.customer_document_id)}
        ${saleDetailField("Teléfono", item.phone || item.customer_phone)}
        ${saleDetailField("Correo", item.customer_email || item.email)}
      </div>
    </section>
    <section class="sales-detail-section">
      <h4>Productos comprados</h4>
      <div class="sales-detail-products">
        ${saleDetailProductsMarkup(item)}
      </div>
      <small>${products.length ? `${products.length.toLocaleString("es-CO")} producto(s) en la venta.` : "Sin desglose de productos en metadata."}</small>
    </section>
    <section class="sales-detail-section">
      <h4>Atribución y operación</h4>
      <div class="sales-detail-grid">
        ${saleDetailField("Pago", item.payment_method)}
        ${saleDetailField("Moneda", item.currency)}
        ${saleDetailField("Ticket / QR", item.qr_code_id || item.qr_code)}
        ${saleDetailField("Redención", item.redemption_id)}
        ${saleDetailField("Afiliado", item.affiliate_name || item.affiliate_id)}
        ${saleDetailField("Notas", item.notes || saleMetadata(item).notes)}
      </div>
    </section>
    <details class="sales-detail-raw">
      <summary>Ver todos los datos técnicos de la venta</summary>
      <div class="table-wrap">
        <table>
          <tbody>${saleDetailAllDataRows(item)}</tbody>
        </table>
      </div>
    </details>
  `;
  modal.classList.remove("hidden");
  document.body.classList.add("has-sales-detail-modal");
  modal.querySelector(".sales-detail-close")?.focus();
}

function bindSalesTableRows(rows = []) {
  if (!campaignSalesTable) return;
  campaignSalesTable.querySelectorAll("[data-sales-detail]").forEach((row) => {
    const open = () => openSalesDetailModal(row.dataset.salesDetail || "");
    row.addEventListener("click", (event) => {
      if (event.target.closest("button, a, input, select, textarea")) return;
      open();
    });
    row.addEventListener("keydown", (event) => {
      if (!["Enter", " "].includes(event.key)) return;
      event.preventDefault();
      open();
    });
  });
}

function saleDateKey(item = {}) {
  return item.created_at ? dateInputValue(item.created_at) : "";
}

function salesFilterValue(value = "") {
  return String(value || "").trim().toLowerCase();
}

function syncSalesAnalysisFiltersFromInputs() {
  state.salesAnalysisFilters = {
    search: salesAnalysisSearchInput?.value || "",
    customer: salesAnalysisCustomerInput?.value || "",
    product: salesAnalysisProductInput?.value || "",
    date_from: salesAnalysisDateFromInput?.value || "",
    date_to: salesAnalysisDateToInput?.value || "",
    channel: salesAnalysisChannelInput?.value || "",
    campaign: salesAnalysisCampaignInput?.value || "",
    branch: salesAnalysisBranchInput?.value || "",
    group_by: salesAnalysisGroupInput?.value || "customer",
  };
}

function saleMatchesAnalysisFilters(item = {}, filters = state.salesAnalysisFilters || {}) {
  const searchBlob = salesFilterValue([
    saleCustomerText(item),
    saleProductPlainText(item),
    saleCampaignText(item),
    saleChannelText(item),
    saleBranchText(item),
    saleSourceLabel(item.sale_source),
    item.payment_method,
    item.notes,
  ].join(" "));
  const customerBlob = salesFilterValue(saleCustomerText(item));
  const productBlob = salesFilterValue(saleProductPlainText(item));
  const dateKey = saleDateKey(item);
  if (filters.search && !searchBlob.includes(salesFilterValue(filters.search))) return false;
  if (filters.customer && !customerBlob.includes(salesFilterValue(filters.customer))) return false;
  if (filters.product && !productBlob.includes(salesFilterValue(filters.product))) return false;
  if (filters.date_from && (!dateKey || dateKey < filters.date_from)) return false;
  if (filters.date_to && (!dateKey || dateKey > filters.date_to)) return false;
  if (filters.channel && saleChannelText(item) !== filters.channel) return false;
  if (filters.campaign && saleCampaignText(item) !== filters.campaign) return false;
  if (filters.branch && saleBranchText(item) !== filters.branch) return false;
  return true;
}

function filteredSalesForAnalysis(rows = state.selectedSales || []) {
  const baseRows = filterRows(rows, ["player_name", "document_id", "phone", "payment_method", "product_or_service", "branch_name", "acquisition_channel", "campaign_name"]);
  return baseRows.filter((item) => saleMatchesAnalysisFilters(item));
}

function salesOptionMarkup(values = [], selected = "", emptyLabel = "Todos") {
  const options = Array.from(new Set(values.map((value) => String(value || "").trim()).filter(Boolean)))
    .sort((a, b) => a.localeCompare(b, "es"));
  return [
    `<option value="">${escapeHtml(emptyLabel)}</option>`,
    ...options.map((value) => `<option value="${escapeHtml(value)}" ${String(selected) === value ? "selected" : ""}>${escapeHtml(value)}</option>`),
  ].join("");
}

function renderSalesAnalysisControls(rows = state.selectedSales || []) {
  const filters = state.salesAnalysisFilters || {};
  if (salesAnalysisSearchInput && salesAnalysisSearchInput.value !== filters.search) salesAnalysisSearchInput.value = filters.search || "";
  if (salesAnalysisCustomerInput && salesAnalysisCustomerInput.value !== filters.customer) salesAnalysisCustomerInput.value = filters.customer || "";
  if (salesAnalysisProductInput && salesAnalysisProductInput.value !== filters.product) salesAnalysisProductInput.value = filters.product || "";
  if (salesAnalysisDateFromInput && salesAnalysisDateFromInput.value !== filters.date_from) salesAnalysisDateFromInput.value = filters.date_from || "";
  if (salesAnalysisDateToInput && salesAnalysisDateToInput.value !== filters.date_to) salesAnalysisDateToInput.value = filters.date_to || "";
  if (salesAnalysisGroupInput) salesAnalysisGroupInput.value = filters.group_by || "customer";
  if (salesAnalysisChannelInput) salesAnalysisChannelInput.innerHTML = salesOptionMarkup(rows.map(saleChannelText), filters.channel, "Todos");
  if (salesAnalysisCampaignInput) salesAnalysisCampaignInput.innerHTML = salesOptionMarkup(rows.map(saleCampaignText), filters.campaign, "Todas");
  if (salesAnalysisBranchInput) salesAnalysisBranchInput.innerHTML = salesOptionMarkup(rows.map(saleBranchText), filters.branch, "Todas");
}

function salesGroupLabel(item = {}, groupBy = "customer") {
  const products = saleProductsForDisplay(item);
  if (groupBy === "product") return products[0]?.name || cleanCustomerValue(item.product_or_service) || "Sin producto";
  if (groupBy === "date") return saleDateKey(item) ? formatDateShort(item.created_at) : "Sin fecha";
  if (groupBy === "channel") return saleChannelText(item);
  if (groupBy === "campaign") return saleCampaignText(item);
  if (groupBy === "branch") return saleBranchText(item);
  if (groupBy === "source") return saleSourceLabel(item.sale_source);
  return item.player_name || item.customer_name || "Cliente sin nombre";
}

function salesGroupMeta(item = {}, groupBy = "customer") {
  if (groupBy === "customer") return [item.document_id, item.phone, item.customer_email].filter(Boolean).join(" · ") || "Sin datos básicos";
  if (groupBy === "product") return [saleCampaignText(item), saleChannelText(item)].filter(Boolean).join(" · ");
  if (groupBy === "date") return "Revenue por fecha";
  if (groupBy === "channel") return "Canal de llegada";
  if (groupBy === "campaign") return "Campaña atribuida";
  if (groupBy === "branch") return "Sede o consignación";
  return "Medio de llegada";
}

function groupedSalesAnalysis(rows = [], groupBy = "customer") {
  const groups = new Map();
  rows.forEach((item) => {
    const label = salesGroupLabel(item, groupBy);
    const key = salesFilterValue(label);
    if (!groups.has(key)) {
      groups.set(key, {
        label,
        meta: salesGroupMeta(item, groupBy),
        sales: 0,
        revenue: 0,
        latest: item.created_at || "",
      });
    }
    const group = groups.get(key);
    group.sales += 1;
    group.revenue += toNumber(item.sale_amount);
    if (item.created_at && (!group.latest || new Date(item.created_at) > new Date(group.latest))) group.latest = item.created_at;
  });
  return Array.from(groups.values()).sort((a, b) => b.revenue - a.revenue || b.sales - a.sales).slice(0, 8);
}

function renderSalesAnalysisGrid(rows = [], allRows = state.selectedSales || []) {
  if (!salesAnalysisGrid) return;
  const filters = state.salesAnalysisFilters || {};
  const totalRevenue = rows.reduce((sum, item) => sum + toNumber(item.sale_amount), 0);
  const allRevenue = allRows.reduce((sum, item) => sum + toNumber(item.sale_amount), 0);
  const grouped = groupedSalesAnalysis(rows, filters.group_by || "customer");
  const coverage = allRevenue ? Math.round((totalRevenue / allRevenue) * 1000) / 10 : 0;
  salesAnalysisGrid.innerHTML = `
    <article class="sales-analysis-summary-card">
      <span class="mono-label">Resultado filtrado</span>
      <strong>${money(totalRevenue)}</strong>
      <small>${rows.length.toLocaleString("es-CO")} venta(s) · ${coverage}% del revenue visible</small>
    </article>
    <article class="sales-analysis-summary-card">
      <span class="mono-label">Ticket promedio</span>
      <strong>${money(rows.length ? totalRevenue / rows.length : 0)}</strong>
      <small>Promedio del filtro activo</small>
    </article>
    <article class="sales-analysis-summary-card">
      <span class="mono-label">Agrupación</span>
      <strong>${escapeHtml({
        customer: "Clientes",
        product: "Productos",
        date: "Fechas",
        channel: "Canales",
        campaign: "Campañas",
        branch: "Sedes",
        source: "Medios",
      }[filters.group_by || "customer"] || "Clientes")}</strong>
      <small>${grouped.length.toLocaleString("es-CO")} grupo(s) encontrados</small>
    </article>
    <section class="sales-analysis-breakdown">
      ${grouped.length ? grouped.map((group, index) => `
        <article class="sales-analysis-breakdown-row">
          <span>${String(index + 1).padStart(2, "0")}</span>
          <div>
            <strong>${escapeHtml(group.label)}</strong>
            <small>${escapeHtml(group.meta || "Sin detalle")} · última ${escapeHtml(formatDateShort(group.latest))}</small>
          </div>
          <em>${group.sales.toLocaleString("es-CO")} venta(s)</em>
          <b>${escapeHtml(money(group.revenue))}</b>
        </article>
      `).join("") : '<div class="empty-state compact">No hay ventas para los filtros actuales.</div>'}
    </section>
  `;
}

