function currentActivationType() {
  return activationTypeInput?.value || "TRIVIA";
}

function allowedInteractiveActivationTypes() {
  const allowed = currentPlan().limits?.allowed_interactive_activation_types;
  return Array.isArray(allowed) ? allowed : null;
}

function isActivationTypeAllowedByPlan(type = "") {
  if (planTierIndex(currentPlan().code) >= 0 && !planMeetsTier(requiredPlanForActivationType(type))) return false;
  const allowed = allowedInteractiveActivationTypes();
  if (!allowed) return true;
  return allowed.includes(interactiveTypeForLegacyType(type));
}

function suggestedPlanForActivationType(type = "") {
  return isActivationTypeAllowedByPlan(type) ? currentPlan().code : requiredPlanForActivationType(type);
}

function syncActivationTypeAccess() {
  activationTypePicker?.querySelectorAll("[data-activation-type]").forEach((button) => {
    const requiredCode = requiredPlanForActivationType(button.dataset.activationType);
    applyFeatureTierBadge(button, requiredCode, { short: true });
    const locked = !isActivationTypeAllowedByPlan(button.dataset.activationType);
    button.classList.toggle("plan-locked", locked);
    button.setAttribute("aria-disabled", locked ? "true" : "false");
    if (locked) {
      const requiredPlan = publicSubscriptionPlan(requiredCode);
      button.title = `Tu plan actual no incluye este tipo de activación. Requiere ${requiredPlan.name || requiredCode}.`;
    } else {
      button.removeAttribute("title");
    }
  });
}

function setActivationType(type) {
  const nextType = type || "TRIVIA";
  if (!isActivationTypeAllowedByPlan(nextType)) {
    showFeatureUpgradeInterstitial("qr_batch_generator", {
      suggestedPlanCode: suggestedPlanForActivationType(nextType),
      title: "Activación bloqueada por plan",
      message: `${activationTypeLabel(nextType)} requiere ${publicSubscriptionPlan(suggestedPlanForActivationType(nextType)).name || "un plan superior"}.`,
    });
    return;
  }
  if (activationTypeInput) activationTypeInput.value = nextType;
  activationTypePicker?.querySelectorAll("[data-activation-type]").forEach((button) => {
    const active = button.dataset.activationType === nextType;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  syncActivationTypeAccess();
  document.querySelectorAll("[data-activation-config]").forEach((panel) => {
    const configs = String(panel.dataset.activationConfig || "").split(/\s+/).filter(Boolean);
    const active = configs.includes(nextType);
    panel.classList.toggle("hidden", !active);
    panel.classList.toggle("active", active);
  });
  renderMinigameSpecificConfig(nextType);
  updateGamingActivationCatalog();
  window.setTimeout(() => {
    updateGamingBuilderProgress();
    updateGamingActivationWizard();
  }, 0);
  if (triviaBenefitLabelInput) {
    const zoneBasedBenefit = nextType === "SCRATCH_DIGITAL";
    triviaBenefitLabelInput.required = !zoneBasedBenefit;
    triviaBenefitLabelInput.placeholder = zoneBasedBenefit
      ? "Opcional: se usaran los beneficios de cada zona"
      : "Beneficio desbloqueado por participar";
  }
  if (nextType === "TRIVIA") {
    if (triviaQuestionCountInput) {
      triviaQuestionCountInput.disabled = false;
      triviaQuestionCountInput.required = true;
    }
    updateTriviaQuestionVisibility();
  } else {
    if (triviaQuestionCountInput) {
      triviaQuestionCountInput.required = false;
      triviaQuestionCountInput.disabled = true;
    }
    triviaQuestionBuilder?.querySelectorAll("input, select").forEach((field) => {
      field.required = false;
    });
  }
  updateActivationQuestionCountControls();
  if (triviaBuilderHint) {
    triviaBuilderHint.textContent = nextType === "TRIVIA"
      ? triviaBuilderHint.textContent
      : `${activationTypeLabel(nextType)} activa. El participante recibe QR al completar la dinámica.`;
  }
  if (triviaLauncherMessage && nextType !== "TRIVIA") {
    setInlineMessage(triviaLauncherMessage, `${activationTypeLabel(nextType)} seleccionado. Configura los campos y lanza la landing cuando este lista.`, "info");
  } else if (triviaLauncherMessage) {
    setInlineMessage(triviaLauncherMessage, "Trivia seleccionada. Completa las preguntas y define el beneficio antes de lanzar.", "info");
  }
}

function collectTriviaQuestions() {
  const count = Math.max(1, Math.min(5, Number(triviaQuestionCountInput?.value || 1)));
  return Array.from(triviaQuestionBuilder?.querySelectorAll("[data-trivia-question]") || [])
    .filter((card) => Number(card.dataset.triviaQuestion || 0) <= count)
    .map((card) => ({
      question: card.querySelector('[data-trivia-field="question"]')?.value.trim() || "",
      options: {
        A: card.querySelector('[data-trivia-option="A"]')?.value.trim() || "",
        B: card.querySelector('[data-trivia-option="B"]')?.value.trim() || "",
        C: card.querySelector('[data-trivia-option="C"]')?.value.trim() || "",
        D: card.querySelector('[data-trivia-option="D"]')?.value.trim() || "",
      },
      correct_answer: card.querySelector('[data-trivia-field="correct"]')?.value || "A",
    }));
}

function splitOptionList(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, 8);
}

const ACTIVATION_FORM_CHOICE_TYPES = new Set(["SINGLE_CHOICE", "MULTIPLE_CHOICE", "CHECKBOXES", "SELECT", "LEVEL"]);
const ACTIVATION_FORM_TYPES = [
  ["TEXT", "Texto corto"],
  ["TEXTAREA", "Texto largo"],
  ["SINGLE_CHOICE", "Opcion unica"],
  ["MULTIPLE_CHOICE", "Seleccion multiple"],
  ["CHECKBOXES", "Checks"],
  ["SELECT", "Lista desplegable"],
  ["RATING", "Calificacion 1 a 5"],
  ["SCALE", "Escala 1 a 10"],
  ["LEVEL", "Nivel bajo/medio/alto"],
  ["YES_NO", "Si / No"],
  ["NUMBER", "Numero"],
  ["DATE", "Fecha"],
  ["EMAIL", "Correo"],
  ["PHONE", "Telefono"],
];
const ACTIVATION_FORM_RMS_FIELDS = [
  ["interest", "Interes / producto"],
  ["intent", "Intencion de compra"],
  ["priority", "Prioridad"],
  ["budget", "Presupuesto"],
  ["purchase_window", "Momento de compra"],
  ["preferred_channel", "Canal preferido"],
  ["category", "Categoria / segmento"],
  ["level", "Nivel"],
  ["rating", "Calificacion"],
  ["notes", "Nota para clasificacion RMS"],
  ["custom", "Dato adicional"],
];

function activationFormFieldKey(value, fallback) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 48) || fallback;
}

function activationFormOptionMarkup(items = [], selectedValue = "") {
  return items.map(([value, label]) => `<option value="${escapeHtml(value)}" ${String(value) === String(selectedValue) ? "selected" : ""}>${escapeHtml(label)}</option>`).join("");
}

function activationFormFieldRows() {
  return Array.from(activationFormBuilder?.querySelectorAll("[data-activation-form-field]") || []);
}

function activationFormRowMarkup(index = 1, field = {}) {
  const type = field.type || "TEXT";
  const rmsField = field.rms_field || "custom";
  const label = field.label || "";
  const options = Array.isArray(field.options) ? field.options.join(", ") : (field.options || "");
  return `
    <article class="activation-form-field-row" data-activation-form-field="${index}">
      <div class="activation-form-row-head">
        <span>Pregunta ${index}</span>
        <button class="ghost-button compact danger-button" type="button" data-activation-form-remove>Quitar</button>
      </div>
      <label class="activation-form-question-label"><span>Pregunta / dato a capturar</span><input data-activation-form-label type="text" maxlength="180" value="${escapeHtml(label)}" placeholder="Ej: Que producto te interesa?"></label>
      <label><span>Tipo de control</span>
        <select data-activation-form-type>${activationFormOptionMarkup(ACTIVATION_FORM_TYPES, type)}</select>
      </label>
      <label><span>Opciones / niveles</span><input data-activation-form-options type="text" value="${escapeHtml(options)}" placeholder="Opcion A, Opcion B, Opcion C"></label>
      <label><span>Uso RMS</span>
        <select data-activation-form-rms>${activationFormOptionMarkup(ACTIVATION_FORM_RMS_FIELDS, rmsField)}</select>
      </label>
      <label class="activation-form-help-field"><span>Ayuda / contexto</span><input data-activation-form-help type="text" maxlength="220" value="${escapeHtml(field.help_text || "")}" placeholder="Texto de ayuda opcional para el lead"></label>
      <label class="activation-form-required"><input data-activation-form-required type="checkbox" ${field.required ? "checked" : ""}><span>Obligatoria</span></label>
    </article>
  `;
}

function enhanceActivationFormRows() {
  const rows = activationFormFieldRows();
  rows.forEach((row, index) => {
    const position = index + 1;
    row.dataset.activationFormField = String(position);
    row.classList.add("is-enhanced");
    if (!row.querySelector(".activation-form-row-head")) {
      const head = document.createElement("div");
      head.className = "activation-form-row-head";
      head.innerHTML = `<span>Pregunta ${position}</span><button class="ghost-button compact danger-button" type="button" data-activation-form-remove>Quitar</button>`;
      row.insertBefore(head, row.firstElementChild);
    } else {
      const title = row.querySelector(".activation-form-row-head span");
      if (title) title.textContent = `Pregunta ${position}`;
    }
    if (!row.querySelector("[data-activation-form-help]")) {
      const helpLabel = document.createElement("label");
      helpLabel.className = "activation-form-help-field";
      helpLabel.innerHTML = '<span>Ayuda / contexto</span><input data-activation-form-help type="text" maxlength="220" placeholder="Texto de ayuda opcional para el lead">';
      const required = row.querySelector(".activation-form-required");
      row.insertBefore(helpLabel, required || null);
    }
    row.querySelector("[data-activation-form-label]")?.closest("label")?.classList.add("activation-form-question-label");
    row.querySelector("[data-activation-form-type]")?.closest("label")?.classList.add("activation-form-type-field");
    row.querySelector("[data-activation-form-options]")?.closest("label")?.classList.add("activation-form-options-field");
    row.querySelector("[data-activation-form-rms]")?.closest("label")?.classList.add("activation-form-rms-field");
    row.querySelector("[data-activation-form-help]")?.closest("label")?.classList.add("activation-form-help-field");
  });
}

function updateActivationFormBuilderCount() {
  if (!activationFormFieldCount) return;
  const rows = activationFormFieldRows();
  const activeRows = rows.filter((row) => row.querySelector("[data-activation-form-label]")?.value.trim());
  const publishedFields = activationCustomFieldsForProductIntent(collectActivationCustomFields(), activationProductIntentConfig());
  activationFormFieldCount.textContent = `${publishedFields.length.toLocaleString("es-CO")} publicada(s) · ${activeRows.length.toLocaleString("es-CO")} diseñada(s)`;
}

function addActivationFormQuestion(seed = {}) {
  if (!activationFormBuilder) return;
  const nextIndex = activationFormFieldRows().length + 1;
  activationFormBuilder.insertAdjacentHTML("beforeend", activationFormRowMarkup(nextIndex, seed));
  enhanceActivationFormRows();
  syncActivationFormBuilder();
  const row = activationFormFieldRows().at(-1);
  row?.scrollIntoView({ behavior: "smooth", block: "center" });
  row?.querySelector("[data-activation-form-label]")?.focus();
}

function collectActivationCustomFields() {
  return Array.from(activationFormBuilder?.querySelectorAll("[data-activation-form-field]") || [])
    .map((row, index) => {
      const label = row.querySelector("[data-activation-form-label]")?.value.trim() || "";
      if (!label) return null;
      const type = row.querySelector("[data-activation-form-type]")?.value || "TEXT";
      const options = splitOptionList(row.querySelector("[data-activation-form-options]")?.value);
      const helpText = row.querySelector("[data-activation-form-help]")?.value.trim() || "";
      return {
        id: `activation_form_${index + 1}`,
        key: activationFormFieldKey(label, `field_${index + 1}`),
        label,
        type,
        options: ACTIVATION_FORM_CHOICE_TYPES.has(type) ? options : [],
        help_text: helpText || null,
        required: Boolean(row.querySelector("[data-activation-form-required]")?.checked),
        rms_field: row.querySelector("[data-activation-form-rms]")?.value || "custom",
        order_index: index,
        source: "activation_form_builder",
      };
    })
    .filter(Boolean);
}

function activationProductOptionList() {
  return activeInventoryProducts()
    .map((product) => ({
      product_id: product.id || null,
      value: product.name || inventoryProductLabel(product),
      label: inventoryProductLabel(product),
      sku: product.sku || null,
      category: product.category || product.product_category || null,
    }))
    .filter((option) => option.value)
    .slice(0, 80);
}

function activationProductIntentConfig() {
  const mode = String(activationProductIntentModeInput?.value || "OPEN_LEAD_CHOICE");
  const safeMode = ["OPEN_LEAD_CHOICE", "PROMOTED_PRODUCT", "NO_PRODUCT"].includes(mode) ? mode : "OPEN_LEAD_CHOICE";
  const selectedProduct = safeMode === "PROMOTED_PRODUCT" ? findInventoryProduct(activationProductIntentInput?.value) : null;
  const rawProductName = safeMode === "PROMOTED_PRODUCT" ? productInputRawValue(activationProductIntentInput) : "";
  return {
    mode: safeMode,
    required: safeMode !== "NO_PRODUCT",
    product_id: selectedProduct?.id || null,
    product_name: rawProductName || selectedProduct?.name || null,
    options: activationProductOptionList(),
    rms_field: "interest",
  };
}

function activationProductInterestField(config = activationProductIntentConfig()) {
  const hasOptions = Array.isArray(config.options) && config.options.length;
  return {
    id: "activation_product_interest",
    key: "product_interest",
    label: "Que producto o servicio te interesa?",
    type: hasOptions ? "SELECT" : "TEXT",
    options: hasOptions ? config.options.map((option) => ({ label: option.label, value: option.value })) : [],
    help_text: hasOptions
      ? "Elige el producto o servicio que quieres conocer para que el negocio clasifique tu solicitud."
      : "Escribe el producto, servicio o categoria que quieres conocer.",
    required: true,
    rms_field: "interest",
    order_index: -1,
    source: "activation_product_interest",
  };
}

function isProductInterestField(field = {}) {
  const text = `${field.key || ""} ${field.label || ""}`.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  return field.rms_field === "interest" && /(producto|servicio|categoria|interes|interest)/.test(text);
}

function activationCustomFieldsForProductIntent(fields = [], config = activationProductIntentConfig()) {
  const cleanFields = fields.map((field, index) => ({ ...field, order_index: index }));
  if (config.mode === "NO_PRODUCT") return cleanFields;
  if (config.mode === "PROMOTED_PRODUCT") {
    return cleanFields.filter((field) => !isProductInterestField(field));
  }
  const productField = activationProductInterestField(config);
  const interestIndex = cleanFields.findIndex(isProductInterestField);
  if (interestIndex >= 0) {
    const existing = cleanFields[interestIndex];
    cleanFields[interestIndex] = {
      ...existing,
      ...productField,
      id: existing.id || productField.id,
      key: existing.key || productField.key,
      label: existing.label || productField.label,
      help_text: existing.help_text || productField.help_text,
      required: true,
      order_index: existing.order_index,
    };
    return cleanFields;
  }
  return [productField, ...cleanFields.map((field, index) => ({ ...field, order_index: index + 1 }))];
}

function validateActivationCustomFields() {
  const fields = activationCustomFieldsForProductIntent(collectActivationCustomFields(), activationProductIntentConfig());
  const invalidChoice = fields.find((field) => ACTIVATION_FORM_CHOICE_TYPES.has(field.type) && field.options.length < 2);
  if (invalidChoice) {
    setInlineMessage(triviaLauncherMessage, `Agrega al menos dos opciones para "${invalidChoice.label}" en el formulario RMS.`, "error");
    const row = Array.from(activationFormBuilder?.querySelectorAll("[data-activation-form-field]") || [])
      .find((item) => item.querySelector("[data-activation-form-label]")?.value.trim() === invalidChoice.label);
    row?.querySelector("[data-activation-form-options]")?.focus();
    return null;
  }
  return fields;
}

function validateActivationProductIntent() {
  const config = activationProductIntentConfig();
  if (config.mode !== "PROMOTED_PRODUCT" || config.product_name) return config;
  setInlineMessage(triviaLauncherMessage, "Selecciona o escribe el producto promocionado por esta activación.", "error");
  activationProductIntentInput?.focus();
  return null;
}

function updateActivationProductIntentMode() {
  const config = activationProductIntentConfig();
  if (activationProductIntentPanel) {
    activationProductIntentPanel.dataset.productIntentMode = config.mode;
  }
  const needsFixedProduct = config.mode === "PROMOTED_PRODUCT";
  if (activationProductIntentInput) {
    activationProductIntentInput.disabled = !needsFixedProduct;
    activationProductIntentInput.required = needsFixedProduct;
  }
  if (activationProductIntentOpenInput) {
    activationProductIntentOpenInput.disabled = !needsFixedProduct || activationProductIntentInput?.value !== OPEN_PRODUCT_VALUE;
    activationProductIntentOpenInput.required = needsFixedProduct && activationProductIntentInput?.value === OPEN_PRODUCT_VALUE;
  }
  if (!activationProductIntentHelp) return;
  const optionCount = config.options.length;
  const messages = {
    OPEN_LEAD_CHOICE: optionCount
      ? `La prelanding agregará una pregunta obligatoria con ${optionCount.toLocaleString("es-CO")} producto(s) activos del inventario.`
      : "La prelanding agregará una pregunta obligatoria de texto porque todavía no hay productos activos en inventario.",
    PROMOTED_PRODUCT: config.product_name
      ? `El lead no elegirá producto: RMS recibirá "${config.product_name}" como interés asociado.`
      : "Selecciona el producto que esta activación promociona; el lead no tendrá que elegirlo.",
    NO_PRODUCT: "No se agregará pregunta de producto ni producto fijo para esta activación.",
  };
  activationProductIntentHelp.textContent = messages[config.mode] || messages.OPEN_LEAD_CHOICE;
}

function syncActivationFormBuilder() {
  enhanceActivationFormRows();
  const productConfig = activationProductIntentConfig();
  activationFormBuilder?.querySelectorAll("[data-activation-form-field]").forEach((row) => {
    const type = row.querySelector("[data-activation-form-type]")?.value || "TEXT";
    const label = row.querySelector("[data-activation-form-label]")?.value.trim() || "";
    const rmsField = row.querySelector("[data-activation-form-rms]")?.value || "custom";
    const optionsInput = row.querySelector("[data-activation-form-options]");
    const needsOptions = ACTIVATION_FORM_CHOICE_TYPES.has(type);
    optionsInput?.closest("label")?.classList.toggle("is-muted-field", !needsOptions);
    if (type === "LEVEL" && optionsInput && !optionsInput.value.trim()) {
      optionsInput.value = "Bajo, Medio, Alto";
    }
    row.classList.toggle("is-empty-question", !row.querySelector("[data-activation-form-label]")?.value.trim());
    row.classList.toggle("is-fixed-product-skipped", productConfig.mode === "PROMOTED_PRODUCT" && isProductInterestField({ label, rms_field: rmsField }));
  });
  updateActivationFormBuilderCount();
}

function collectSurveyQuestions() {
  const count = getActivationQuestionCount("SURVEY", 1);
  return Array.from(document.querySelectorAll("[data-survey-question]"))
    .filter((card) => Number(card.dataset.surveyQuestion || 0) <= count)
    .map((card, index) => {
      const question = card.querySelector('[data-survey-field="question"]')?.value.trim() || "";
      const type = card.querySelector('[data-survey-field="type"]')?.value || "SINGLE_CHOICE";
      const options = splitOptionList(card.querySelector('[data-survey-field="options"]')?.value);
      return {
        id: `s${index + 1}`,
        question,
        type,
        options,
        required: true,
      };
    })
    .filter((item) => item.question);
}

function updateSurveyQuestionEditors() {
  const count = getActivationQuestionCount("SURVEY", 1);
  document.querySelectorAll("[data-survey-question]").forEach((card) => {
    const index = Number(card.dataset.surveyQuestion || 0);
    const active = index <= count;
    const type = card.querySelector('[data-survey-field="type"]')?.value || "SINGLE_CHOICE";
    const optionsField = card.querySelector(".survey-options-field");
    card.classList.toggle("hidden", !active);
    card.querySelectorAll("input, select, textarea").forEach((field) => {
      field.disabled = !active;
    });
    optionsField?.classList.toggle("hidden", !["SINGLE_CHOICE", "MULTIPLE_CHOICE"].includes(type));
  });
}

function getActivationQuestionCount(type, fallback = 1) {
  const input = document.querySelector(`[data-question-count-for="${type}"]`);
  if (!input) return fallback;
  const min = Number(input.min || 1);
  const max = Number(input.max || 5);
  const value = Math.max(min, Math.min(max, Number(input.value || fallback)));
  input.value = String(value);
  return value;
}

function updateActivationQuestionCountControls() {
  const openQuestionCount = getActivationQuestionCount("OPEN_QUESTION", 1);
  document.querySelectorAll("[data-open-question]").forEach((input) => {
    const active = Number(input.dataset.openQuestion || 0) <= openQuestionCount;
    const row = input.closest("label") || input;
    row.classList.toggle("hidden", !active);
    input.disabled = !active;
  });
  updateSurveyQuestionEditors();
  document.querySelectorAll("[data-flat-form]").forEach((panel) => {
    const type = panel.dataset.flatForm;
    const questions = Array.from(panel.querySelectorAll("[data-flat-question]"));
    const count = getActivationQuestionCount(type, questions.length || 1);
    questions.forEach((input, index) => {
      const active = index < count;
      const row = input.closest("label") || input;
      row.classList.toggle("hidden", !active);
      input.disabled = !active;
    });
  });
}

function collectOpenQuestions() {
  const count = getActivationQuestionCount("OPEN_QUESTION", 1);
  return Array.from(document.querySelectorAll("[data-open-question]"))
    .filter((input) => Number(input.dataset.openQuestion || 0) <= count && !input.disabled)
    .map((input, index) => ({
      id: `open_question_${index + 1}`,
      question_text: input.value.trim(),
      question_type: "OPEN",
      options: [],
      required: true,
      scoring_rules: null,
    }))
    .filter((question) => question.question_text);
}

function collectRevealCards() {
  const productScope = benefitProductScope(triviaBenefitProductModeInput, triviaBenefitProductInput);
  const fulfillment = benefitFulfillmentFromInputs(triviaBenefitFulfillmentModeInput, triviaEcommerceCodeInput, triviaEcommerceUrlInput, triviaEcommerceInstructionsInput);
  return Array.from(document.querySelectorAll("[data-reveal-card]"))
    .map((input) => ({
      label: input.dataset.revealCard || "Card",
      benefit_label: input.value.trim(),
      benefit_type: triviaBenefitTypeInput?.value || "CUSTOM",
      benefit_value: withBenefitFulfillment(withBenefitProductScope(parseJsonObject(triviaBenefitValueInput?.value || "{}"), productScope), fulfillment),
    }))
    .filter((item) => item.benefit_label);
}

function collectThermometerDiscounts() {
  return splitOptionList(thermometerDiscountsInput?.value)
    .map((value) => Number(value))
    .filter((value) => Number.isInteger(value) && value > 0 && value <= 100);
}

function collectFlatChoiceOptions(type) {
  const productScope = benefitProductScope(triviaBenefitProductModeInput, triviaBenefitProductInput);
  const fulfillment = benefitFulfillmentFromInputs(triviaBenefitFulfillmentModeInput, triviaEcommerceCodeInput, triviaEcommerceUrlInput, triviaEcommerceInstructionsInput);
  return Array.from(document.querySelectorAll(`[data-flat-choice="${type}"] [data-flat-option]`))
    .map((input) => {
      const key = input.dataset.flatOption || input.value.trim();
      const imageDataUrl = type === "PRODUCT_VOTE"
        ? (input.dataset.imageDataUrl || productVoteImages[key] || "")
        : "";
      return {
        value: key,
        label: input.value.trim(),
        image_data_url: imageDataUrl || null,
        reward_type: triviaBenefitTypeInput.value,
        reward_label: type === "SCRATCH_DIGITAL" ? input.value.trim() : triviaBenefitLabelInput.value.trim(),
        reward_value: type === "SCRATCH_DIGITAL"
          ? withBenefitFulfillment(withBenefitProductScope({ ...parseJsonObject(triviaBenefitValueInput.value), label: input.value.trim(), scratch_slot: key }, productScope), fulfillment)
          : withBenefitFulfillment(withBenefitProductScope(parseJsonObject(triviaBenefitValueInput.value), productScope), fulfillment),
      };
    })
    .filter((item) => item.label);
}

function collectRouletteBenefits() {
  const productScope = benefitProductScope(triviaBenefitProductModeInput, triviaBenefitProductInput);
  const fulfillment = benefitFulfillmentFromInputs(triviaBenefitFulfillmentModeInput, triviaEcommerceCodeInput, triviaEcommerceUrlInput, triviaEcommerceInstructionsInput);
  return Array.from(document.querySelectorAll("[data-roulette-benefit]"))
    .map((input, index) => {
      const label = input.value.trim();
      const value = `ROULETTE_${index + 1}`;
      return {
        value,
        label,
        reward_type: triviaBenefitTypeInput.value,
        reward_label: label,
        reward_value: withBenefitFulfillment(withBenefitProductScope(parseJsonObject(triviaBenefitValueInput.value), productScope), fulfillment),
      };
    })
    .filter((item) => item.label);
}

function syncProductVoteImagePreview(key, dataUrl = "") {
  const preview = document.querySelector(`[data-product-vote-preview="${key}"]`);
  if (!preview) return;
  preview.src = dataUrl || "";
  preview.classList.toggle("hidden", !dataUrl);
}

async function handleProductVoteImageFile(key, file) {
  if (!key || !file) return;
  try {
    if (!/^image\/(png|jpe?g|webp)$/i.test(file.type || "")) {
      throw new Error("Usa una imagen PNG, JPG o WebP.");
    }
    const dataUrl = await normalizeAffiliatePhotoDataUrl(file, {
      maxWidth: 720,
      maxHeight: 540,
      quality: 0.78,
      mimeType: "image/webp",
    });
    if (!dataUrl) throw new Error("No se pudo procesar la imagen.");
    productVoteImages[key] = dataUrl;
    const optionInput = document.querySelector(`[data-flat-choice="PRODUCT_VOTE"] [data-flat-option="${key}"]`);
    if (optionInput) optionInput.dataset.imageDataUrl = dataUrl;
    syncProductVoteImagePreview(key, dataUrl);
    showFeedback("Imagen de opción cargada.", "success", { title: "Votación de producto" });
  } catch (error) {
    showFeedback(error.message || "No se pudo cargar la imagen.", "error");
  } finally {
    const fileInput = document.querySelector(`[data-flat-option-image="${key}"]`);
    if (fileInput) fileInput.value = "";
  }
}

function collectFlatFormQuestions(type) {
  const count = getActivationQuestionCount(type, 5);
  return Array.from(document.querySelectorAll(`[data-flat-form="${type}"] [data-flat-question]`))
    .filter((input, index) => index < count && !input.disabled)
    .map((input, index) => ({
      id: input.dataset.flatQuestion || `q${index + 1}`,
      question_text: input.value.trim(),
      question_type: input.dataset.flatQuestionType || "OPEN",
      options: defaultOptionsForFlatQuestion(input.dataset.flatQuestion || "", input.dataset.flatQuestionType || "OPEN"),
      required: true,
      order_index: index,
    }))
    .filter((question) => question.question_text);
}

function defaultOptionsForFlatQuestion(key, type) {
  if (!["SINGLE_CHOICE", "PRODUCT_CATEGORY"].includes(type)) return [];
  const presets = {
    recipient: ["Pareja", "Familiar", "Amigo", "Cliente"],
    occasion: ["Cumpleanos", "Aniversario", "Agradecimiento", "Sorpresa"],
    budget: ["Bajo", "Medio", "Premium"],
    style: ["Clasico", "Moderno", "Artesanal", "Lujo"],
    urgency: ["Hoy", "Esta semana", "Este mes"],
    purchase_window: ["Lanzamiento", "Esta semana", "Este mes"],
  };
  return presets[key] || ["Opción A", "Opción B", "Opción C"];
}

function isFlatChoiceActivation(type) {
  return ["PRODUCT_VOTE", "STYLE_SELECTOR", "SCRATCH_DIGITAL", "TAP_REVEAL"].includes(type);
}

function isFlatFormActivation(type) {
  return ["GIFT_CURATOR", "NEED_DIAGNOSTIC", "WAITLIST", "REWARD_RESERVATION"].includes(type);
}

function isFixedPremiumActivation(type) {
  return ["SEALED_LETTER", "PRIVATE_INVITATION"].includes(type);
}

function isMinigameActivation(type) {
  return ["SPACE_SHOOTER", "BREAKOUT", "SNAKE", "CATCH_PRIZE", "MEMORY_PAIRS", "FAST_TAP", "MINI_MAZE", "WHACK_A_MOLE", "DODGE_RUNNER", "BALLOON_POP", "ROULETTE_SPIN", "TOUCH_CATCH", "TRUE_FALSE", "ORDER_OPTIONS", "CONNECTORS", "BATTLESHIP_COORDS"].includes(type);
}

