function agendaChecklistItems(value) {
  if (Array.isArray(value)) {
    return value
      .map((item) => ({
        label: String(item?.label || "").trim(),
        done: Boolean(item?.done),
      }))
      .filter((item) => item.label);
  }
  return String(value || "")
    .split(/[\r\n,]+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(0, 20)
    .map((label) => ({ label, done: false }));
}

function agendaChecklistText(value) {
  return agendaChecklistItems(value).map((item) => item.label).join("\n");
}

function agendaChecklistSummary(item = {}) {
  const checklist = agendaChecklistItems(item.checklist);
  const done = checklist.filter((entry) => entry.done).length;
  return { checklist, done, total: checklist.length };
}

function agendaPriorityLabel(priority = "MEDIUM") {
  return {
    LOW: "Baja",
    MEDIUM: "Media",
    HIGH: "Alta",
    URGENT: "Urgente",
  }[String(priority || "MEDIUM").toUpperCase()] || "Media";
}

function agendaScopeLabel(value = "CONTACT") {
  return {
    GENERAL: "Sin alcance",
    CONTACT: "Contacto",
    CAMPAIGN: "Campaña",
    MARKETING: "Marketing",
    ACTIVATION_STRATEGY: "Estrategia de activación",
    BULK_ACTIVATION: "Activación en masa",
  }[String(value || "").toUpperCase()] || "Sin alcance";
}

function agendaSourceTypeForScope(scope = "CONTACT", leadSourceType = "PLAYER") {
  const value = String(scope || "GENERAL").toUpperCase();
  if (value === "CONTACT") return String(leadSourceType || "PLAYER").toUpperCase();
  return value;
}

function isOperationalAgendaSource(value = "") {
  return ["GENERAL", "CAMPAIGN", "MARKETING", "ACTIVATION_STRATEGY", "BULK_ACTIVATION"].includes(String(value || "").toUpperCase());
}

function agendaMetadata(item = {}) {
  return item.metadata && typeof item.metadata === "object" ? item.metadata : {};
}

function agendaCampaignById(campaignId = "") {
  return (state.campaigns || []).find((campaign) => String(campaign.id) === String(campaignId)) || null;
}

function selectedAgendaCampaign(campaignId = "") {
  campaignId = campaignId || leadAgendaCampaignInput?.value || "";
  return agendaCampaignById(campaignId);
}

function agendaCampaignOptionsMarkup(selectedValue = "") {
  return '<option value="">Sin campaña</option>' + (state.campaigns || [])
    .map((campaign) => `<option value="${escapeHtml(campaign.id)}" ${String(selectedValue) === String(campaign.id) ? "selected" : ""}>${escapeHtml(campaign.name || campaign.slug || campaign.id)}</option>`)
    .join("");
}

function agendaCampaignIdForItem(item = {}) {
  const metadata = agendaMetadata(item);
  if (metadata.campaign_id) return metadata.campaign_id;
  if (isOperationalAgendaSource(item.source_type)) return item.source_id || "";
  return "";
}

function agendaScopeForItem(item = {}) {
  const metadata = agendaMetadata(item);
  if (metadata.agenda_scope) return String(metadata.agenda_scope).toUpperCase();
  const sourceType = String(item.source_type || "").toUpperCase();
  return isOperationalAgendaSource(sourceType) ? sourceType : "CONTACT";
}

function selectedAgendaCampaignFromData(data = null) {
  const campaignId = data ? String(data.get("campaign_id") || "") : leadAgendaCampaignInput?.value || "";
  return (state.campaigns || []).find((campaign) => String(campaign.id) === String(campaignId)) || null;
}

function renderLeadAgendaCampaignOptions() {
  if (!leadAgendaCampaignInput) return;
  const selected = leadAgendaCampaignInput.value || state.selectedCampaignId || "";
  leadAgendaCampaignInput.innerHTML = agendaCampaignOptionsMarkup(selected);
  if (selected && Array.from(leadAgendaCampaignInput.options).some((option) => option.value === selected)) {
    leadAgendaCampaignInput.value = selected;
  }
}

function agendaMeetingModeLabel(value = "") {
  return {
    VIRTUAL: "Virtual",
    IN_PERSON: "Presencial",
  }[String(value || "").toUpperCase()] || "";
}

function agendaMeetingPlatformLabel(value = "") {
  return {
    ZOOM: "Zoom",
    MEET: "Google Meet",
    TEAMS: "Microsoft Teams",
    WHATSAPP: "WhatsApp",
    OTHER: "Otra plataforma",
  }[String(value || "").toUpperCase()] || "";
}

function agendaMeetingPayloadFromFields(data = null) {
  const read = (name, fallback = "") => {
    if (data) return String(data.get(name) || fallback).trim();
    const input = {
      agenda_activity_type: leadAgendaActivityTypeInput,
      meeting_mode: leadAgendaMeetingModeInput,
      meeting_platform: leadAgendaMeetingPlatformInput,
      meeting_url: leadAgendaMeetingUrlInput,
      meeting_address: leadAgendaMeetingAddressInput,
    }[name];
    return String(input?.value || fallback).trim();
  };
  const activityType = read("agenda_activity_type", "TASK").toUpperCase();
  const mode = read("meeting_mode").toUpperCase();
  const platform = read("meeting_platform").toUpperCase();
  const url = read("meeting_url");
  const address = read("meeting_address");
  const isMeeting = activityType === "MEETING" || Boolean(mode || platform || url || address);
  return {
    agenda_activity_type: isMeeting ? "MEETING" : "TASK",
    meeting_mode: isMeeting ? mode : "",
    meeting_platform: isMeeting ? platform : "",
    meeting_url: isMeeting ? url : "",
    meeting_address: isMeeting ? address : "",
  };
}

function agendaOperationalPayloadFromFields(data = null) {
  const scope = String(data ? data.get("agenda_scope") || "GENERAL" : leadAgendaScopeInput?.value || "GENERAL").toUpperCase();
  const campaign = scope === "GENERAL" ? null : selectedAgendaCampaignFromData(data);
  return {
    ...agendaMeetingPayloadFromFields(data),
    agenda_scope: scope,
    agenda_scope_label: agendaScopeLabel(scope),
    campaign_id: campaign?.id || "",
    campaign_name: campaign?.name || "",
  };
}

function agendaMeetingSummary(item = {}) {
  const metadata = agendaMetadata(item);
  if (metadata.agenda_activity_type !== "MEETING" && !metadata.meeting_mode && !metadata.meeting_url && !metadata.meeting_address) return "";
  const parts = [
    "Reunión",
    agendaMeetingModeLabel(metadata.meeting_mode),
    agendaMeetingPlatformLabel(metadata.meeting_platform),
    metadata.meeting_mode === "VIRTUAL" ? metadata.meeting_url : metadata.meeting_address,
  ].filter(Boolean);
  return parts.join(" · ");
}

function agendaSentenceText(value = "") {
  return String(value || "").trim().replace(/[.!?]+$/g, "");
}

function agendaMeetingWhatsAppMessage(item = {}) {
  const metadata = agendaMetadata(item);
  const greeting = item.lead_name ? `Hola ${item.lead_name}` : "Hola";
  const business = activationBusinessName();
  const date = agendaSentenceText(formatDate(item.reminder_at));
  const mode = agendaMeetingModeLabel(metadata.meeting_mode);
  const platform = agendaMeetingPlatformLabel(metadata.meeting_platform);
  const meetingDetails = [
    platform || "",
    metadata.meeting_url ? `Enlace: ${metadata.meeting_url}` : "",
    metadata.meeting_address ? `Dirección: ${metadata.meeting_address}` : "",
  ].filter(Boolean);
  return [
    `${greeting}, te contactamos de ${business} para recordarte nuestra reunión programada para ${date}.`,
    mode ? `Modalidad: ${mode}.` : "",
    meetingDetails.length ? `Detalle: ${meetingDetails.join(" · ")}.` : "",
    item.next_action ? `Tema: ${item.next_action}.` : "",
  ].filter(Boolean).join("\n");
}

function agendaMeetingWhatsAppUrl(item = {}) {
  const phone = whatsappPhoneFromInput(item.lead_phone || "");
  const message = agendaMeetingWhatsAppMessage(item);
  return phone
    ? `https://wa.me/${encodeURIComponent(phone)}?text=${encodeURIComponent(message)}`
    : `https://wa.me/?text=${encodeURIComponent(message)}`;
}

function applyAgendaTemplate(templateKey = "") {
  const template = AGENDA_TEMPLATES[templateKey];
  if (!template) return;
  if (leadAgendaActionInput) leadAgendaActionInput.value = template.action;
  if (leadAgendaNoteInput) leadAgendaNoteInput.value = template.note;
  if (leadAgendaPriorityInput) leadAgendaPriorityInput.value = template.priority;
  if (leadAgendaScopeInput) leadAgendaScopeInput.value = template.scope || "CONTACT";
  if (leadAgendaActivityTypeInput) leadAgendaActivityTypeInput.value = template.activity_type || "TASK";
  if (leadAgendaMeetingModeInput) leadAgendaMeetingModeInput.value = template.meeting_mode || "";
  if (leadAgendaMeetingPlatformInput) leadAgendaMeetingPlatformInput.value = template.meeting_platform || "";
  if (leadAgendaMeetingUrlInput) leadAgendaMeetingUrlInput.value = "";
  if (leadAgendaMeetingAddressInput) leadAgendaMeetingAddressInput.value = "";
  if (leadAgendaProgressInput) leadAgendaProgressInput.value = "0";
  if (leadAgendaChecklistInput) leadAgendaChecklistInput.value = template.checklist.join("\n");
}

function agendaLeadOptionValue(lead = {}) {
  return `${String(lead.source_type || "PLAYER").toUpperCase()}::${lead.id || lead.lead_id || ""}`;
}

function parseAgendaLeadValue(value = "") {
  const [sourceType, ...idParts] = String(value || "").split("::");
  return {
    source_type: sourceType || "PLAYER",
    id: idParts.join("::"),
  };
}

function leadAgendaContactRows(extraRows = []) {
  const seen = new Set();
  return [
    ...(Array.isArray(extraRows) ? extraRows : []),
    ...(state.leadAgendaContacts || []),
    ...(state.leadCrmRows || []),
  ].filter((item) => item?.id || item?.lead_id).filter((item) => {
    const key = agendaLeadOptionValue(item);
    if (!key || key.endsWith("::") || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function agendaLeadLabel(item = {}) {
  return [
    item.name || item.full_name || item.lead_name || "Contacto sin nombre",
    item.phone || item.email || item.document_id || "",
    item.source_type || "",
  ].filter(Boolean).join(" - ");
}

function agendaLeadFromItem(item = {}) {
  const sourceType = String(item.source_type || "PLAYER").toUpperCase();
  const leadId = item.source_id || item.lead_id || "";
  if (!leadId || isOperationalAgendaSource(sourceType)) return null;
  return {
    id: leadId,
    lead_id: item.lead_id || null,
    source_type: sourceType,
    name: item.lead_name || "Contacto sin nombre",
    phone: item.lead_phone || "",
    email: item.lead_email || "",
    document_id: item.lead_document_id || "",
  };
}

function agendaLeadOptionsMarkup(selectedValue = "", extraRows = []) {
  if (!state.leadAgendaContactsLoaded && !state.leadAgendaContactsLoading && session?.user?.business_id) {
    loadLeadAgendaContacts().then(() => {
      renderLeadAgenda();
      if (state.selectedLeadRef) renderLeadDetailAgenda();
    }).catch(() => {});
  }
  const rows = leadAgendaContactRows(extraRows);
  const placeholder = `<option value="" ${!selectedValue ? "selected" : ""}>Elegir contacto</option>`;
  return placeholder + rows.map((item) => {
    const value = agendaLeadOptionValue(item);
    return `<option value="${escapeHtml(value)}" ${String(value) === String(selectedValue) ? "selected" : ""}>${escapeHtml(agendaLeadLabel(item))}</option>`;
  }).join("") + (rows.length ? "" : `<option value="" disabled>${state.leadAgendaContactsLoading ? "Cargando contactos..." : "Sin contactos cargados"}</option>`);
}

function renderLeadAgendaLeadOptions() {
  if (!leadAgendaLeadInput) return;
  if (!state.leadAgendaContactsLoaded && !state.leadAgendaContactsLoading && session?.user?.business_id) {
    loadLeadAgendaContacts().then(renderLeadAgenda).catch(() => {});
  }
  const selectedValue = state.selectedLeadRef?.id
    ? `${String(state.selectedLeadRef.source_type || "PLAYER").toUpperCase()}::${state.selectedLeadRef.id}`
    : leadAgendaLeadInput.value;
  leadAgendaLeadInput.innerHTML = agendaLeadOptionsMarkup(selectedValue);
  if (selectedValue && Array.from(leadAgendaLeadInput.options).some((option) => option.value === selectedValue)) {
    leadAgendaLeadInput.value = selectedValue;
  }
}

