function branchesViewSection() {
  return document.querySelector('.view-section[data-view="branches"]');
}

function openBranchFormModal() {
  ensureBranchesUxStyles();
  if (branchFormPanel?.parentElement !== document.body) document.body.appendChild(branchFormPanel);
  branchesViewSection()?.classList.add("branch-modal-open");
  branchFormPanel?.classList.add("is-branch-modal-open");
}

function closeBranchFormModal() {
  branchFormPanel?.classList.remove("is-branch-modal-open");
  branchesViewSection()?.classList.remove("branch-modal-open");
}

function branchRowKey(row = {}) {
  return row.id ? `id:${row.id}` : `name:${row.branch || "Sin sucursal"}`;
}

function branchRowByKey(key = "") {
  return branchActivityRows().find((row) => branchRowKey(row) === key) || null;
}

function branchSalesForRow(row = {}) {
  const branchName = String(row.branch || "").trim();
  return (state.selectedSales || []).filter((item) => String(item.branch_name || "Sin sucursal").trim() === branchName);
}

function branchRedemptionsForRow(row = {}) {
  const branchName = String(row.branch || "").trim();
  return (state.selectedRedemptions || []).filter((item) => String(item.branch_name || "Sin sucursal").trim() === branchName);
}

function branchDetailTable(headers = [], rows = [], empty = "Sin datos para esta sede.") {
  if (!rows.length) return `<div class="branch-detail-box"><strong>${escapeHtml(empty)}</strong><span>Cuando registres ventas o redenciones con esta sede aparecerán aquí.</span></div>`;
  return `
    <div class="branch-detail-table-wrap">
      <table>
        <thead><tr>${headers.map((header) => `<th>${escapeHtml(header)}</th>`).join("")}</tr></thead>
        <tbody>${rows.join("")}</tbody>
      </table>
    </div>
  `;
}

function openBranchDetailModal(key = "") {
  const row = branchRowByKey(key);
  if (!row || !branchDetailModal) return;
  const sales = branchSalesForRow(row);
  const redemptions = branchRedemptionsForRow(row);
  const avgTicket = row.sales ? row.revenue / row.sales : 0;
  if (branchDetailTitle) branchDetailTitle.textContent = row.branch || "Sede";
  if (branchDetailSummary) {
    branchDetailSummary.textContent = `${branchTypeLabel(row.branch_type)} · ${row.address || "Sin ubicación"} · ${row.is_active === false ? "Inactiva" : "Activa"}`;
  }
  if (branchDetailBody) {
    branchDetailBody.innerHTML = `
      <div class="branch-detail-grid">
        <div class="branch-detail-box"><span>Revenue generado</span><strong>${escapeHtml(money(row.revenue || 0))}</strong></div>
        <div class="branch-detail-box"><span>Ventas registradas</span><strong>${escapeHtml(String(row.sales || 0))}</strong></div>
        <div class="branch-detail-box"><span>Redenciones</span><strong>${escapeHtml(String(row.redemptions || 0))}</strong></div>
        <div class="branch-detail-box"><span>Ticket promedio</span><strong>${escapeHtml(row.sales ? money(avgTicket) : "-")}</strong></div>
        <div class="branch-detail-box"><span>Responsable</span><strong>${escapeHtml([row.contact_name, row.contact_phone].filter(Boolean).join(" · ") || "-")}</strong></div>
        <div class="branch-detail-box"><span>Notas</span><strong>${escapeHtml(row.notes || "-")}</strong></div>
      </div>
      ${row.id ? `
        <div class="branch-detail-actions">
          <button class="ghost-button" type="button" data-branch-detail-edit="${escapeHtml(row.id)}">Editar sede</button>
          <button class="ghost-button ${row.is_active ? "danger" : ""}" type="button" data-branch-detail-toggle="${escapeHtml(row.id)}" data-branch-next-active="${row.is_active ? "false" : "true"}">${row.is_active ? "Desactivar sede" : "Reactivar sede"}</button>
        </div>
      ` : ""}
      <h4>Ventas atribuidas a esta sede</h4>
      ${branchDetailTable(["Cliente", "Valor", "Producto", "Pago", "Canal", "Fecha"], sales.slice(0, 80).map((item) => `
        <tr>
          <td><strong>${escapeHtml(item.player_name || "-")}</strong><span class="table-secondary">${escapeHtml(item.phone || item.document_id || "")}</span></td>
          <td>${escapeHtml(money(item.sale_amount || 0))}</td>
          <td>${escapeHtml(item.product_or_service || saleProductSummary(item).replace(/<[^>]*>/g, "") || "-")}</td>
          <td>${escapeHtml(item.payment_method || "-")}</td>
          <td>${escapeHtml(item.acquisition_channel || item.sale_source || "-")}</td>
          <td>${escapeHtml(formatDate(item.created_at))}</td>
        </tr>
      `), "Sin ventas registradas en esta sede.")}
      <h4>Redenciones asociadas</h4>
      ${branchDetailTable(["Cliente", "Beneficio", "Validador", "Estado", "Fecha"], redemptions.slice(0, 80).map((item) => `
        <tr>
          <td><strong>${escapeHtml(item.player_name || "-")}</strong><span class="table-secondary">${escapeHtml(item.phone || item.document_id || "")}</span></td>
          <td>${escapeHtml(item.reward_name || item.benefit_label || "-")}</td>
          <td>${escapeHtml(item.validator_name || "-")}</td>
          <td>${escapeHtml(item.status || item.qr_status || "-")}</td>
          <td>${escapeHtml(formatDate(item.redeemed_at || item.created_at))}</td>
        </tr>
      `), "Sin redenciones registradas en esta sede.")}
    `;
    branchDetailBody.querySelector("[data-branch-detail-edit]")?.addEventListener("click", () => {
      closeBranchDetailModal();
      editBranch(row.id);
    });
    branchDetailBody.querySelector("[data-branch-detail-toggle]")?.addEventListener("click", () => {
      closeBranchDetailModal();
      toggleBranchActive(row.id, row.is_active !== true);
    });
  }
  branchDetailModal.classList.remove("hidden");
  branchDetailModal.removeAttribute("aria-hidden");
}

function closeBranchDetailModal() {
  if (!branchDetailModal) return;
  branchDetailModal.classList.add("hidden");
  branchDetailModal.setAttribute("aria-hidden", "true");
}

function renderCustomerAcquisitionBranchOptions() {
  if (!customerAcquisitionBranchInput) return;
  if (!state.businessBranchesLoaded && !state.businessBranchesLoading && session?.user?.business_id) {
    loadBusinessBranches().then(renderCustomerAcquisitionBranchOptions).catch(() => {});
  }
  const selected = customerAcquisitionBranchInput.value || "";
  const rows = (state.businessBranches || []).filter((branch) => branch.is_active !== false);
  customerAcquisitionBranchInput.innerHTML = [
    `<option value="">${state.businessBranchesLoading ? "Cargando branches..." : "Sin sede asignada"}</option>`,
    ...rows.map((branch) => {
      const metadata = branchMetadata(branch);
      const type = branchTypeLabel(metadata.branch_type);
      return `<option value="${escapeHtml(branch.id)}" ${String(selected) === String(branch.id) ? "selected" : ""}>${escapeHtml(`${branch.name} · ${type}`)}</option>`;
    }),
  ].join("");
  if (selected && rows.some((branch) => String(branch.id) === String(selected))) {
    customerAcquisitionBranchInput.value = selected;
  }
}

function branchById(branchId = "") {
  return (state.businessBranches || []).find((branch) => String(branch.id) === String(branchId)) || null;
}

function resetBranchForm() {
  state.branchEditingId = null;
  branchCreateForm?.reset();
  if (branchSubmitButton) branchSubmitButton.textContent = "Agregar sede";
  branchCancelEditButton?.classList.add("hidden");
  setInlineMessage(branchCreateMessage, "", "info");
}

function editBranch(branchId = "") {
  const branch = branchById(branchId);
  if (!branch) return;
  const metadata = branchMetadata(branch);
  state.branchEditingId = branch.id;
  if (branchTypeInput) branchTypeInput.value = metadata.branch_type || "BRANCH";
  if (branchNameInput) branchNameInput.value = branch.name || "";
  if (branchAddressInput) branchAddressInput.value = branch.address || "";
  if (branchContactInput) branchContactInput.value = metadata.contact_name || "";
  if (branchPhoneInput) branchPhoneInput.value = metadata.contact_phone || "";
  if (branchNotesInput) branchNotesInput.value = metadata.notes || "";
  if (branchSubmitButton) branchSubmitButton.textContent = "Guardar sede";
  branchCancelEditButton?.classList.remove("hidden");
  setInlineMessage(branchCreateMessage, "Editando sede existente.", "info");
  openBranchFormModal();
  branchNameInput?.focus();
}

async function loadBusinessBranches(options = {}) {
  if (!session?.user?.business_id) {
    state.businessBranches = [];
    state.businessBranchesLoaded = true;
    state.businessBranchesLoading = false;
    return [];
  }
  if (state.businessBranchesLoaded && !options.force) return state.businessBranches;
  if (state.businessBranchesLoading) return state.businessBranches;
  state.businessBranchesLoading = true;
  const scopeKey = businessScopeKey();
  try {
    const data = await apiSafe("/api/business/branches", { headers: authHeaders() }, { branches: [] });
    if (!isCurrentBusinessScope(scopeKey)) return state.businessBranches;
    state.businessBranches = Array.isArray(data.branches) ? data.branches : [];
    state.businessBranchesLoaded = true;
    return state.businessBranches;
  } finally {
    if (isCurrentBusinessScope(scopeKey)) state.businessBranchesLoading = false;
  }
}

function branchActivityRows() {
  const summary = new Map();
  withFilters(
    state.selectedRedemptions || [],
    ["branch_name", "player_name", "reward_name", "validator_name"],
    ["redeemed_at"]
  ).forEach((item) => {
    const key = item.branch_name || "Sin sucursal";
    if (!summary.has(key)) summary.set(key, { branch: key, redemptions: 0, sales: 0, revenue: 0 });
    summary.get(key).redemptions += 1;
  });

  withFilters(
    state.selectedSales || [],
    ["branch_name", "player_name", "product_or_service"],
    ["created_at"]
  ).forEach((item) => {
    const key = item.branch_name || "Sin sucursal";
    if (!summary.has(key)) summary.set(key, { branch: key, redemptions: 0, sales: 0, revenue: 0 });
    summary.get(key).sales += 1;
    summary.get(key).revenue += toNumber(item.sale_amount);
  });

  (state.businessBranches || []).forEach((branch) => {
    const key = branch.name || "Sin sucursal";
    const metadata = branchMetadata(branch);
    const current = summary.get(key) || { branch: key, redemptions: 0, sales: 0, revenue: 0 };
    summary.set(key, {
      ...current,
      id: branch.id,
      slug: branch.slug,
      address: branch.address || "",
      is_active: branch.is_active !== false,
      branch_type: metadata.branch_type || "BRANCH",
      contact_name: metadata.contact_name || "",
      contact_phone: metadata.contact_phone || "",
      notes: metadata.notes || "",
    });
  });

  return Array.from(summary.values()).sort((a, b) => b.revenue - a.revenue || String(a.branch).localeCompare(String(b.branch)));
}

function renderBranchesView() {
  ensureBranchesUxStyles();
  if (!state.businessBranchesLoaded && !state.businessBranchesLoading && session?.user?.business_id) {
    loadBusinessBranches().then(renderBranchesView).catch((error) => showFeedback(error.message, "error"));
  }
  const allRows = branchActivityRows();
  const branchSearch = String(branchSearchInput?.value || "").trim().toLowerCase();
  const rows = allRows.filter((row) => !branchSearch || [
    row.branch,
    row.address,
    row.contact_name,
    row.contact_phone,
    row.branch_type,
  ].join(" ").toLowerCase().includes(branchSearch));
  const totalRevenue = rows.reduce((sum, row) => sum + row.revenue, 0);
  const topBranch = rows[0]?.branch || "Sin datos";
  const activeBranches = (state.businessBranches || []).filter((branch) => branch.is_active !== false).length;
  const consignmentCount = (state.businessBranches || []).filter((branch) => String(branchMetadata(branch).branch_type || "").toUpperCase() === "CONSIGNMENT").length;
  branchKpiGrid.innerHTML = [
    ["Sedes activas", activeBranches || rows.length, `${consignmentCount} consignación`],
    ["Redenciones", rows.reduce((sum, row) => sum + row.redemptions, 0), `${rows.length ? Math.round(rows.reduce((sum, row) => sum + row.redemptions, 0) / rows.length) : 0} promedio/sucursal`],
    ["Ingresos", money(totalRevenue), `${rows.reduce((sum, row) => sum + row.sales, 0)} ventas · líder ${topBranch}`],
  ].map(([label, value, meta]) => `
    <article class="kpi-card">
      <span class="mono-label">${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
      <div class="kpi-meta">${escapeHtml(meta)}</div>
    </article>
  `).join("");
  if (branchListCount) branchListCount.textContent = `${rows.length} de ${allRows.length} sede${allRows.length === 1 ? "" : "s"}`;

  branchTable.innerHTML = rows.map((row) => `
    <tr data-branch-detail-row="${escapeHtml(branchRowKey(row))}">
      <td>
        <span class="branch-simple-cell">
          <strong>${escapeHtml(row.branch)}</strong>
          <small>${escapeHtml([branchTypeLabel(row.branch_type), row.address].filter(Boolean).join(" · ") || "Haz clic para ver resultados")}</small>
        </span>
      </td>
      <td>${escapeHtml([row.contact_name, row.contact_phone].filter(Boolean).join(" · ") || "-")}</td>
      <td><span class="branch-performance"><strong>${escapeHtml(money(row.revenue))}</strong><small>${escapeHtml(`${row.sales} ventas · ${row.redemptions} redenciones`)}</small></span></td>
      <td><span class="status-chip ${row.id && row.is_active !== false ? "ok" : "pending"}">${escapeHtml(row.id ? (row.is_active ? "Activo" : "Inactivo") : "Actividad sin sede")}</span></td>
      <td>
        <span class="branch-row-actions">
          <button class="ghost-button compact" type="button" data-branch-detail="${escapeHtml(branchRowKey(row))}">Abrir</button>
        </span>
      </td>
    </tr>
  `).join("") || `<tr><td colspan="5">${state.businessBranchesLoading ? "Cargando sedes..." : "No encontramos sedes con esa búsqueda."}</td></tr>`;
  branchTable.querySelectorAll("[data-branch-detail-row]").forEach((row) => {
    row.addEventListener("click", (event) => {
      if (event.target.closest("button, a, input, select, textarea")) return;
      openBranchDetailModal(row.dataset.branchDetailRow || "");
    });
  });
  branchTable.querySelectorAll("[data-branch-detail]").forEach((button) => {
    button.addEventListener("click", () => openBranchDetailModal(button.dataset.branchDetail || ""));
  });
  branchTable.querySelectorAll("[data-branch-edit]").forEach((button) => {
    button.addEventListener("click", () => editBranch(button.dataset.branchEdit));
  });
  branchTable.querySelectorAll("[data-branch-toggle]").forEach((button) => {
    button.addEventListener("click", () => toggleBranchActive(button.dataset.branchToggle, button.dataset.branchNextActive === "true"));
  });
}

async function submitBranchCreate(event) {
  event.preventDefault();
  const name = String(branchNameInput?.value || "").trim();
  if (!name) {
    setInlineMessage(branchCreateMessage, "Escribe el nombre de la sede.", "error");
    return;
  }
  const editingId = state.branchEditingId;
  const editingBranch = editingId ? branchById(editingId) : null;
  const payload = {
    branch_type: branchTypeInput?.value || "BRANCH",
    name,
    address: branchAddressInput?.value.trim() || null,
    contact_name: branchContactInput?.value.trim() || null,
    contact_phone: branchPhoneInput?.value.trim() || null,
    notes: branchNotesInput?.value.trim() || null,
    is_active: editingBranch ? editingBranch.is_active !== false : true,
  };
  try {
    setInlineMessage(branchCreateMessage, editingId ? "Guardando sede..." : "Creando sede...", "info");
    const data = await api(editingId ? `/api/business/branches/${encodeURIComponent(editingId)}` : "/api/business/branches", {
      method: editingId ? "PATCH" : "POST",
      headers: authHeaders(),
      body: JSON.stringify(payload),
    });
    if (data?.branch) {
      state.businessBranches = [
        data.branch,
        ...(state.businessBranches || []).filter((branch) => String(branch.id) !== String(data.branch.id)),
      ];
      state.businessBranchesLoaded = true;
    } else {
      await loadBusinessBranches({ force: true });
    }
    resetBranchForm();
    closeBranchFormModal();
    setInlineMessage(branchCreateMessage, editingId ? "Sede actualizada." : "Sede agregada. Ya puedes usarla para medir ventas, redenciones o consignación.", "success");
    showFeedback(editingId ? "Sede actualizada correctamente." : "Sede agregada correctamente.", "success", { title: "Sedes" });
    renderBranchesView();
    renderCustomerAcquisitionBranchOptions();
  } catch (error) {
    setInlineMessage(branchCreateMessage, error.message || "No se pudo guardar la sede.", "error");
    showFeedback(error.message || "No se pudo guardar la sede.", "error", { title: "Sedes" });
  }
}

async function toggleBranchActive(branchId = "", nextActive = false) {
  const branch = branchById(branchId);
  if (!branch) return;
  if (!nextActive && !window.confirm(`¿Eliminar/desactivar "${branch.name}"? El historial de ventas y redenciones se conserva.`)) return;
  try {
    const data = await api(`/api/business/branches/${encodeURIComponent(branchId)}`, {
      method: nextActive ? "PATCH" : "DELETE",
      headers: authHeaders(),
      body: nextActive ? JSON.stringify({ is_active: true }) : undefined,
    });
    if (data?.branch) {
      state.businessBranches = (state.businessBranches || []).map((item) => (
        String(item.id) === String(data.branch.id) ? data.branch : item
      ));
    } else {
      await loadBusinessBranches({ force: true });
    }
    if (String(state.branchEditingId || "") === String(branchId) && !nextActive) resetBranchForm();
    showFeedback(nextActive ? "Sede reactivada." : "Sede eliminada de la operación activa.", "success", { title: "Sedes" });
    renderBranchesView();
    renderCustomerAcquisitionBranchOptions();
  } catch (error) {
    showFeedback(error.message || "No se pudo actualizar la sede.", "error", { title: "Sedes" });
  }
}

async function loadRmsMachineData(options = {}) {
  if (state.rmsMachineLoaded && !options.force) return state.rmsMachine;
  if (state.rmsMachineLoading && !options.force) return state.rmsMachine;
  state.rmsMachineLoading = true;
  if (!options.quiet) renderRmsMachineLoading();
  try {
    const params = new URLSearchParams();
    const stationPhase = options.stationPhase || (options.lite && state.rmsStationScreenOpen ? state.rmsStationPhase : "");
    if (stationPhase) {
      params.set("phase", stationPhase);
      params.set("rms_phase", stationPhase);
      params.set("lite", "1");
      params.set("limit", "36");
      params.set("section_limit", "0");
    } else {
      params.set("limit", "72");
      params.set("section_limit", "8");
    }
    const search = state.rmsMachineFilters?.search || state.filter || "";
    if (search) params.set("search", search);
    if (state.rmsMachineFilters?.priority) params.set("priority", state.rmsMachineFilters.priority);
    const data = await api(`/api/business/rms-machine?${params.toString()}`, {
      headers: authHeaders(),
    });
    if (stationPhase && (!state.rmsStationScreenOpen || state.rmsStationPhase !== stationPhase)) {
      return data;
    }
    state.rmsMachine = data;
    state.rmsMachineScope = data?.scope || (stationPhase ? { mode: "station", phase: stationPhase, lite: true } : { mode: "machine", phase: "", lite: false });
    rebuildRmsOpportunityIndex(data?.opportunities || []);
    state.rmsMachineLoaded = true;
    renderRmsMachineFilterOptions(rmsFactoryStages(data));
    return data;
  } finally {
    state.rmsMachineLoading = false;
  }
}

function renderRmsMachineLoading() {
  renderRmsMachineFilterOptions(rmsFactoryStages());
  renderRmsStageBoard(rmsFactoryStages(), [], true);
  renderRmsBulkToolbar();
  if (rmsDailyQueue) {
    rmsDailyQueue.innerHTML = `
      <article class="rms-loading-card">
        <span class="busy-spinner" aria-hidden="true"></span>
        <div>
          <strong>Cargando cola RMS</strong>
          <p>Priorizando oportunidades por etapa, riesgo y revenue potencial.</p>
        </div>
      </article>
    `;
  }
}

