function renderRmsTutorial() {
  if (!rmsTutorialSteps || !rmsTutorialPanel) return;
  const total = RMS_TUTORIAL_STEPS.length;
  const index = Math.min(Math.max(Number(state.rmsTutorialStep || 0), 0), total - 1);
  const step = RMS_TUTORIAL_STEPS[index] || RMS_TUTORIAL_STEPS[0];
  const progress = total ? ((index + 1) / total) * 100 : 0;
  state.rmsTutorialStep = index;

  if (rmsTutorialProgressLabel) rmsTutorialProgressLabel.textContent = `Paso ${index + 1} de ${total}`;
  if (rmsTutorialProgressBar) rmsTutorialProgressBar.style.width = `${progress}%`;

  rmsTutorialSteps.innerHTML = RMS_TUTORIAL_STEPS.map((item, itemIndex) => `
    <button class="rms-tutorial-step ${itemIndex === index ? "is-active" : ""}" type="button" data-rms-tutorial-step="${itemIndex}" aria-pressed="${itemIndex === index ? "true" : "false"}">
      <span class="rms-tutorial-step-number">${String(itemIndex + 1).padStart(2, "0")}</span>
      <strong>${escapeHtml(item.title)}</strong>
    </button>
  `).join("");

  rmsTutorialPanel.innerHTML = `
    <div class="rms-tutorial-stage-chip">
      <span>Estación guiada</span>
      <strong>${String(index + 1).padStart(2, "0")} / ${String(total).padStart(2, "0")}</strong>
    </div>
    <div class="rms-tutorial-panel-head">
      <span class="rms-tutorial-icon material-symbols-outlined" aria-hidden="true">${escapeHtml(step.icon)}</span>
      <div>
        <span class="mono-label">${escapeHtml(step.subtitle)}</span>
        <h4>${escapeHtml(step.title)}</h4>
        <p>${escapeHtml(step.operatorHint)}</p>
      </div>
    </div>
    <div class="rms-tutorial-flow">
      <article>
        <span>Qué entra</span>
        <strong>${escapeHtml(step.input)}</strong>
      </article>
      <i class="material-symbols-outlined" aria-hidden="true">arrow_forward</i>
      <article>
        <span>Qué haces</span>
        <strong>${escapeHtml(step.operation)}</strong>
      </article>
      <i class="material-symbols-outlined" aria-hidden="true">arrow_forward</i>
      <article>
        <span>Resultado</span>
        <strong>${escapeHtml(step.output)}</strong>
      </article>
    </div>
    <div class="rms-tutorial-actions">
      <button class="ghost-button" type="button" data-rms-tutorial-prev ${index === 0 ? "disabled" : ""}>Paso anterior</button>
      <button class="solid-button" type="button" data-rms-tutorial-action="${escapeHtml(step.action)}" data-rms-tutorial-phase="${escapeHtml(step.phase)}">${escapeHtml(step.actionLabel)}</button>
      <button class="ghost-button" type="button" data-rms-tutorial-next ${index >= total - 1 ? "disabled" : ""}>Siguiente paso</button>
    </div>
  `;

  rmsTutorialSteps.querySelectorAll("[data-rms-tutorial-step]").forEach((button) => {
    button.addEventListener("click", () => {
      state.rmsTutorialStep = Number(button.dataset.rmsTutorialStep || 0);
      renderRmsTutorial();
    });
  });
  rmsTutorialPanel.querySelector("[data-rms-tutorial-prev]")?.addEventListener("click", () => {
    state.rmsTutorialStep = Math.max(0, index - 1);
    renderRmsTutorial();
  });
  rmsTutorialPanel.querySelector("[data-rms-tutorial-next]")?.addEventListener("click", () => {
    state.rmsTutorialStep = Math.min(total - 1, index + 1);
    renderRmsTutorial();
  });
  bindRmsMachineActions(rmsTutorialPanel);
}

function handleRmsTutorialAction(action = "", phase = "") {
  if (action === "collector") {
    openRmsCollectorModal();
    showFeedback("Aquí ingresas o seleccionas leads para alimentar la Máquina RMS.", "info", { title: "Tutorial RMS" });
    return;
  }
  if (action === "missions") {
    setView("missions");
    showFeedback("Crea el gancho que reduce fuga: ticket, reward, misión o dinámica.", "info", { title: "Tutorial RMS" });
    return;
  }
  if (phase) {
    openRmsStation(phase);
    showFeedback("Esta es la estación real donde se ejecuta este paso del tutorial.", "info", { title: "Tutorial RMS" });
  }
}

function focusRmsTutorial() {
  setView("rms-machine");
  state.rmsStationScreenOpen = false;
  state.rmsStationPhase = "";
  state.rmsMachineFilters.phase = "";
  if (rmsMachinePhaseFilter) rmsMachinePhaseFilter.value = "";
  renderRmsMachineView();
  const tutorial = document.getElementById("rmsMachineTutorial");
  tutorial?.classList.add("is-open");
  tutorial?.scrollIntoView({ behavior: "smooth", block: "start" });
  showFeedback("Sigue el tutorial paso a paso para entender cómo la Máquina RMS fabrica ventas.", "info", { title: "Tutorial RMS" });
}

function renderRmsMachineView() {
  const data = state.rmsMachine || {};
  const stages = rmsFactoryStages(data);
  const allOpportunities = data.opportunities || [];
  const opportunities = rmsVisibleOpportunities(allOpportunities);
  const metrics = data.metrics || {};
  const totalOpportunities = Number(metrics.total_opportunities || allOpportunities.length || 0);
  const isEmpty = allOpportunities.length === 0 && totalOpportunities === 0;
  if (state.rmsStationScreenOpen) {
    renderRmsStationOnly();
    return;
  }
  if (rmsMachineGeneratedAt) {
    rmsMachineGeneratedAt.textContent = data.generated_at ? `Actualizado ${formatDate(data.generated_at)}` : "Sin cargar";
  }
  if (rmsMachineOpportunityCount) {
    const phase = state.rmsMachineFilters?.phase || "";
    rmsMachineOpportunityCount.textContent = phase
      ? `${opportunities.length.toLocaleString("es-CO")} en estación / ${totalOpportunities.toLocaleString("es-CO")} total`
      : `${totalOpportunities.toLocaleString("es-CO")} oportunidades`;
  }
  rmsEmptyStateGuide?.classList.toggle("hidden", !isEmpty);
  renderRmsCollectorActivation();
  renderRmsTutorial();
  renderRmsMachineKpis(metrics);
  renderRmsIntakeFunnel(data.funnel || []);
  renderRmsIndustrialFlow(data.process_flow || []);
  renderRmsAlerts(data.alerts || []);
  renderRmsDailyQueue(rmsDailySectionsFromOpportunities(opportunities));
  renderRmsMachineFilterOptions(stages);
  try {
    renderRmsStationWorkspace(stages, allOpportunities, isEmpty);
  } catch (error) {
    console.error("RMS station render failed", error);
    resetRmsStationMode();
    renderRmsStationWorkspace(stages, allOpportunities, isEmpty);
    showFeedback("La estación no pudo abrirse completa. Volvimos al mapa para que el portal no quede bloqueado.", "error", { title: "Estaciones" });
  }
  renderRmsStageBoard(stages, allOpportunities, isEmpty);
  renderRmsBulkToolbar();
  renderRmsEventLog(data.events || []);
  renderRmsLeadInspector();
}

function rmsStationLeanRowMarkup(item = {}, stage = {}, nextPhase = null) {
  const selected = state.rmsMachineSelectedIds.includes(item.id);
  const readiness = stage.key === "recoleccion" ? rmsCollectorReadiness(item) : { ready: true, label: item.priority_label || "Operable" };
  const origin = item.entry_summary || item.source_detail || item.campaign_name || item.channel || item.source_label || item.source_type || "Origen sin definir";
  const interest = item.product_interest || item.top_interest || item.interest || item.raw_recommended_action || "-";
  const contact = [item.phone, item.email].filter(Boolean).join(" · ") || "Sin contacto";
  const enteredAt = item.created_at || item.last_interaction_at || item.updated_at;
  let stationControl = `<td class="rms-lean-station-status ${escapeHtml(item.priority_class || "medium")}">${escapeHtml(item.priority_label || readiness.label || "Media")}</td>`;
  if (stage.key === "alimentacion") {
    stationControl = `<td class="rms-lean-station-quality">${rmsLeadQualitySelectMarkup(item)}</td>`;
  } else if (stage.key === "curaduria") {
    stationControl = `<td class="rms-lean-station-product">${rmsProductClassificationMarkup(item)}</td>`;
  }
  return `
    <tr data-rms-station-lead="${escapeHtml(item.id)}" data-rms-review-capture="${escapeHtml(item.id)}" class="${selected ? "is-selected" : ""}">
      <td>
        <label class="rms-lean-station-check">
          <input type="checkbox" data-rms-select="${escapeHtml(item.id)}" aria-label="Seleccionar ${escapeHtml(item.name || "lead")}" ${selected ? "checked" : ""}>
        </label>
      </td>
      <td>
        <strong>${escapeHtml(item.name || "Contacto")}</strong>
        <small>${escapeHtml(contact)}</small>
      </td>
      <td>
        <span>${escapeHtml(origin)}</span>
        <small>${escapeHtml(enteredAt ? formatDate(enteredAt) : "-")}</small>
      </td>
      <td>
        <span>${escapeHtml(interest)}</span>
        <small>${escapeHtml(item.stage_label || stage.label || "")}</small>
      </td>
      ${stationControl}
      <td>
        <button class="ghost-button compact" type="button" data-rms-review-capture="${escapeHtml(item.id)}">Detalle</button>
        <button class="ghost-button compact" type="button" data-rms-inspect="${escapeHtml(item.id)}">Operar</button>
      </td>
    </tr>
  `;
}

function renderRmsStationLeanOnly() {
  const data = state.rmsMachine || {};
  const stages = rmsFactoryStages(data);
  const allOpportunities = data.opportunities || [];
  const metrics = data.metrics || {};
  const totalOpportunities = Number(metrics.total_opportunities || allOpportunities.length || 0);
  const isEmpty = allOpportunities.length === 0 && totalOpportunities === 0;
  const phase = state.rmsStationPhase || state.rmsMachineFilters?.phase || stages[0]?.key || "recoleccion";
  const stageIndex = Math.max(0, stages.findIndex((item) => item.key === phase));
  const stage = stages[stageIndex] || stages[0] || { key: phase, label: "Estación RMS", operation: {} };
  const nextPhase = rmsStationNextPhase(stage, stages);
  const rows = rmsStationRows(phase, allOpportunities);
  const display = rmsStationDisplayRows(rows, phase);
  const renderedRows = display.visibleRows;
  const selectedRows = rmsStationSelectedRows(phase, rows);
  const eligibleRows = rmsStationOutputEligibleRows(phase, rows);
  const visual = rmsStationVisualMeta(phase);
  const stationControlLabel = phase === "curaduria" ? "Producto" : phase === "alimentacion" ? "Calidad" : "Estado";
  if (rmsMachineGeneratedAt) {
    rmsMachineGeneratedAt.textContent = data.generated_at ? `Actualizado ${formatDate(data.generated_at)}` : "Sin cargar";
  }
  if (rmsMachineOpportunityCount) {
    rmsMachineOpportunityCount.textContent = phase
      ? `${rows.length.toLocaleString("es-CO")} en estación / ${totalOpportunities.toLocaleString("es-CO")} total`
      : `${totalOpportunities.toLocaleString("es-CO")} oportunidades`;
  }
  renderRmsMachineFilterOptions(stages);
  if (!rmsStationWorkspace) return;
  const consoleShell = rmsStationWorkspace.closest(".rms-factory-console");
  consoleShell?.classList.add("is-station-mode");
  rmsStationWorkspace.classList.remove("hidden");
  rmsStationWorkspace.dataset.stationTheme = visual.tone || "default";
  rmsStationWorkspace.innerHTML = `
    <section class="rms-lean-station" aria-label="Estación RMS simple">
      <header class="rms-lean-station-head">
        <button class="ghost-button compact" type="button" data-rms-close-station>
          <span class="material-symbols-outlined" aria-hidden="true">arrow_back</span> Estaciones
        </button>
        <div class="rms-lean-station-title">
          <figure class="rms-lean-station-media">
            <img src="${escapeHtml(visual.image || "")}" alt="${escapeHtml(visual.imageAlt || stage.label || "Estacion RMS")}" decoding="async">
            <span class="rms-lean-station-symbol material-symbols-outlined" aria-hidden="true">${escapeHtml(visual.icon || "precision_manufacturing")}</span>
          </figure>
          <div>
            <span class="mono-label">Estación ${String(stageIndex + 1).padStart(2, "0")} · Qori v144 limpio</span>
            <h3>${escapeHtml(stage.label || "Estación RMS")}</h3>
            <p>${escapeHtml(stage.operation?.primaryAction || "Trabaja la lista sin cargar paneles pesados.")}</p>
          </div>
        </div>
        <div class="rms-lean-station-actions">
          ${phase === "recoleccion" ? `<button class="ghost-button compact" type="button" data-rms-open-collector><span class="material-symbols-outlined" aria-hidden="true">person_add</span> Nuevo lead</button>` : ""}
          <button class="ghost-button compact" type="button" data-rms-station-select-ready="${escapeHtml(phase)}" ${eligibleRows.length ? "" : "disabled"}><span class="material-symbols-outlined" aria-hidden="true">done_all</span> Listos</button>
          <button class="solid-button compact" type="button" data-rms-lean-send="${escapeHtml(phase)}" ${selectedRows.length && nextPhase ? "" : "disabled"}>${escapeHtml(nextPhase ? `Enviar a ${nextPhase.short_label || nextPhase.label}` : "Sin siguiente")} <span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span></button>
        </div>
      </header>
      <div class="rms-lean-station-tools">
        <label>
          <span class="material-symbols-outlined" aria-hidden="true">search</span>
          <input type="search" data-rms-station-search value="${escapeHtml(state.rmsStationSearch || "")}" placeholder="Buscar en esta estación">
        </label>
        <select data-rms-station-picker aria-label="Cambiar estación">
          ${stages.map((item, index) => `<option value="${escapeHtml(item.key)}" ${index === stageIndex ? "selected" : ""}>${String(index + 1).padStart(2, "0")} · ${escapeHtml(item.short_label || item.label || "Estación")}</option>`).join("")}
        </select>
        <span>${selectedRows.length.toLocaleString("es-CO")} seleccionados · ${eligibleRows.length.toLocaleString("es-CO")} listos · ${rows.length.toLocaleString("es-CO")} total</span>
      </div>
      <div class="rms-lean-station-table-wrap">
        <table class="rms-lean-station-table">
          <thead>
            <tr>
              <th class="rms-lean-selection-heading" aria-label="Seleccionar"></th>
              <th>Lead</th>
              <th>Origen</th>
              <th>Interés</th>
              <th>${escapeHtml(stationControlLabel)}</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            ${renderedRows.map((item) => rmsStationLeanRowMarkup(item, stage, nextPhase)).join("") || `<tr><td colspan="6">${escapeHtml(isEmpty ? "No hay leads todavía." : "No hay leads con este filtro.")}</td></tr>`}
          </tbody>
        </table>
      </div>
      <footer class="rms-lean-station-foot">
        <span>Mostrando ${renderedRows.length.toLocaleString("es-CO")} de ${display.matchingRows.length.toLocaleString("es-CO")}${display.hiddenCount ? ` · ${display.hiddenCount.toLocaleString("es-CO")} más sin dibujar` : ""}</span>
        ${display.hiddenCount ? `<button class="ghost-button compact" type="button" data-rms-station-show-more>Ver ${Math.min(RMS_STATION_RENDER_INCREMENT, display.hiddenCount).toLocaleString("es-CO")} más</button>` : ""}
      </footer>
    </section>
  `;
  bindRmsMachineActions(rmsStationWorkspace);
  rmsStationWorkspace.querySelectorAll("[data-rms-close-station]").forEach((button) => button.addEventListener("click", closeRmsStation));
  rmsStationWorkspace.querySelector("[data-rms-station-picker]")?.addEventListener("change", (event) => openRmsStation(event.target.value || "", { source: "picker" }));
  rmsStationWorkspace.querySelector("[data-rms-station-search]")?.addEventListener("input", (event) => {
    state.rmsStationSearch = event.target.value || "";
    state.rmsStationRenderLimit = RMS_STATION_RENDER_INITIAL_LIMIT;
    window.clearTimeout(state.rmsStationSearchRenderTimer);
    state.rmsStationSearchRenderTimer = window.setTimeout(() => renderRmsStationOnly(), 120);
  });
  rmsStationWorkspace.querySelector("[data-rms-station-show-more]")?.addEventListener("click", () => {
    state.rmsStationRenderLimit = Number(state.rmsStationRenderLimit || RMS_STATION_RENDER_INITIAL_LIMIT) + RMS_STATION_RENDER_INCREMENT;
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-station-select-ready]")?.addEventListener("click", () => {
    state.rmsMachineSelectedIds = eligibleRows.map((item) => item.id);
    renderRmsStationOnly();
  });
  rmsStationWorkspace.querySelector("[data-rms-lean-send]")?.addEventListener("click", async () => {
    if (!selectedRows.length || !nextPhase) return;
    if (rmsBulkPhaseInput) rmsBulkPhaseInput.value = nextPhase.key;
    await moveSelectedRmsPhase();
  });
  renderRmsBulkToolbar();
}

function renderRmsStationOnly() {
  try {
    renderRmsStationLeanOnly();
  } catch (error) {
    console.error("RMS station simple render failed", error);
    resetRmsStationMode();
    renderRmsMachineView();
    showFeedback("La estación falló y volvimos al mapa para no bloquear el portal.", "error", { title: "Estaciones" });
  }
}

function rmsVisibleOpportunities(rows = []) {
  const phase = state.rmsMachineFilters?.phase || "";
  return rows.filter((item) => !phase || item.stage === phase);
}

function renderRmsMachineFilterOptions(stages = []) {
  const options = ['<option value="">Todas las estaciones</option>'].concat((stages || []).map((stage) => (
    `<option value="${escapeHtml(stage.key)}">${escapeHtml(stage.label)}</option>`
  )));
  if (rmsMachinePhaseFilter) {
    const selected = state.rmsMachineFilters?.phase || "";
    rmsMachinePhaseFilter.innerHTML = options.join("");
    rmsMachinePhaseFilter.value = selected;
  }
  if (rmsBulkPhaseInput) {
    const selected = rmsBulkPhaseInput.value || "";
    rmsBulkPhaseInput.innerHTML = '<option value="">Mover a fase...</option>' + (stages || []).map((stage) => (
      `<option value="${escapeHtml(stage.key)}">${escapeHtml(stage.label)}</option>`
    )).join("");
    if (selected) rmsBulkPhaseInput.value = selected;
  }
}

function renderRmsMachineKpis(metrics = {}) {
  if (!rmsMachineKpis) return;
  const isEmpty = Number(metrics.total_opportunities || 0) === 0;
  const cards = isEmpty ? [
    ["Oportunidades", "Por alimentar", "Aquí aparecerán los clientes listos para procesar."],
    ["Atender ahora", "Sin cola", "Aquí estarán los clientes que requieren acción inmediata."],
    ["En riesgo", "Sin riesgo", "Aquí aparecerán clientes que se están enfriando o pueden perderse."],
    ["Revenue potencial", "Por proyectar", "Aquí se proyectará el valor de las oportunidades activas."],
  ] : [
    ["Oportunidades", metrics.total_opportunities || 0, "Base procesada"],
    ["Atender ahora", metrics.operate_now || 0, `${Number(metrics.high_priority || 0).toLocaleString("es-CO")} alta prioridad`],
    ["En riesgo", metrics.recover || 0, `${Number(metrics.high_risk || 0).toLocaleString("es-CO")} con riesgo de fuga`],
    ["Revenue potencial", money(metrics.total_revenue_potential || 0), `${Number(metrics.attention_to_revenue_rate || 0).toLocaleString("es-CO")}% Attention to Revenue`],
  ];
  rmsMachineKpis.innerHTML = cards.map(([label, value, meta]) => `
    <article class="rms-kpi-card">
      <span class="mono-label">${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
      <small>${escapeHtml(meta)}</small>
    </article>
  `).join("");
}

function renderRmsIntakeFunnel(funnel = []) {
  if (!rmsIntakeFunnel) return;
  rmsIntakeFunnel.innerHTML = (funnel || []).map((item, index) => `
    <article class="rms-funnel-step">
      <span>${String(index + 1).padStart(2, "0")}</span>
      <strong>${escapeHtml(item.value ?? 0)}</strong>
      <h4>${escapeHtml(item.label || "Etapa")}</h4>
      <p>${escapeHtml(item.meta || "")}</p>
    </article>
  `).join("") || '<div class="empty-state compact">Curaduría se llenará cuando entren oportunidades.</div>';
  bindRmsMachineActions(rmsIntakeFunnel);
}

function renderRmsIndustrialFlow(steps = []) {
  if (!rmsIndustrialFlow) return;
  rmsIndustrialFlow.innerHTML = (steps || []).map((step, index) => `
    <article class="rms-industrial-step" data-rms-industrial-phase="${escapeHtml(step.phase || "")}">
      <span>${String(index + 1).padStart(2, "0")}</span>
      <div>
        <strong>${escapeHtml(step.label || "Proceso")}</strong>
        <p>${escapeHtml(step.description || "")}</p>
      </div>
      <dl>
        <div><dt>Clientes</dt><dd>${Number(step.count || 0).toLocaleString("es-CO")}</dd></div>
        <div><dt>Riesgo</dt><dd>${Number(step.risk_count || 0).toLocaleString("es-CO")}</dd></div>
        <div><dt>Potencial</dt><dd>${escapeHtml(money(step.revenue_potential || 0))}</dd></div>
      </dl>
      <button class="ghost-button compact" type="button" data-rms-flow-phase="${escapeHtml(step.phase || "")}">
        ${escapeHtml(step.operation?.buttonLabel || "Ver estación")}
      </button>
    </article>
  `).join("") || '<div class="empty-state compact">La ruta industrial se activará cuando entren oportunidades RMS.</div>';
  rmsIndustrialFlow.querySelectorAll("[data-rms-flow-phase]").forEach((button) => {
    button.addEventListener("click", () => {
      openRmsStation(button.dataset.rmsFlowPhase || "", { source: "flow" });
    });
  });
}

function renderRmsAlerts(alerts = []) {
  if (!rmsMachineAlerts) return;
  rmsMachineAlerts.innerHTML = (alerts || []).map((alert) => `
    <article class="rms-alert-card">
      <span class="material-symbols-outlined" aria-hidden="true">warning</span>
      <div>
        <strong>${escapeHtml(alert.title || "Alerta RMS")}</strong>
        <p>${escapeHtml(alert.detail || "")}</p>
      </div>
      <button class="ghost-button" type="button" data-rms-alert-phase="${escapeHtml(alert.phase || "")}">${escapeHtml(alert.action || "Resolver")}</button>
    </article>
  `).join("");
  rmsMachineAlerts.querySelectorAll("[data-rms-alert-phase]").forEach((button) => {
    button.addEventListener("click", () => {
      openRmsStation(button.dataset.rmsAlertPhase || "", { source: "alert" });
    });
  });
}

function rmsDailySectionsFromOpportunities(opportunities = []) {
  const labels = {
    operate_now: "Operar ahora",
    close_revenue: "Ventas atribuidas",
    tickets_to_redeem: "Tickets por activar",
    rebuy: "Recompra y fidelización",
    referrals: "Referidos potenciales",
    recover: "Recuperar antes de perder",
  };
  return Object.keys(labels).map((key) => {
    const rows = opportunities.filter((item) => item.section === key);
    return {
      key,
      label: labels[key],
      total: rows.length,
      items: rows.slice(0, 4),
    };
  });
}

function renderRmsDailyQueue(sections = []) {
  if (!rmsDailyQueue) return;
  const hasItems = sections.some((section) => (section.items || []).length);
  if (!hasItems) {
    rmsDailyQueue.innerHTML = `
      <article class="rms-empty-queue-card">
        <div>
          <span class="mono-label">Mi Día RMS</span>
          <h3>No hay oportunidades todavía.</h3>
          <p>Primero necesitas una fuente de clientes. Activa captura para almacenar leads desde tienda, vitrina, evento, WhatsApp o contactos existentes.</p>
        </div>
        <button class="solid-button" type="button" data-rms-open-collector>Alimentar Máquina RMS</button>
      </article>
    `;
    bindRmsMachineActions(rmsDailyQueue);
    return;
  }
  rmsDailyQueue.innerHTML = sections.map((section) => `
    <article class="rms-queue-section" data-rms-section="${escapeHtml(section.key)}">
      <div class="rms-queue-head">
        <div>
          <span class="mono-label">${escapeHtml(sectionLabelMeta(section.key))}</span>
          <h3>${escapeHtml(section.label)}</h3>
        </div>
        <strong>${Number(section.total || section.items?.length || 0).toLocaleString("es-CO")}</strong>
      </div>
      <div class="rms-card-stack">
        ${(section.items || []).map(rmsOpportunityCardMarkup).join("") || '<div class="empty-state compact">Sin oportunidades en esta cola por ahora.</div>'}
        ${Number(section.total || 0) > (section.items || []).length ? `<div class="rms-queue-more">+${Number(section.total - section.items.length).toLocaleString("es-CO")} oportunidades más. Abre la estación correspondiente para operar el lote completo.</div>` : ""}
      </div>
    </article>
  `).join("") || '<div class="empty-state">Aun no hay oportunidades para procesar.</div>';
  bindRmsMachineActions(rmsDailyQueue);
}

function rmsStageEmptyMarkup(stage = {}) {
  const map = {
    recoleccion: ["Sin leads recolectados.", "Esta estacion almacena leads capturados. La operacion Embudo selecciona cuales son procesables.", "Ingresar lead", "collector"],
    alimentacion: ["Sin leads en Alimentar.", "Esta estacion almacena leads filtrados. La operacion Alimentar asigna calidad alta, media o baja.", "Cargar leads", "contacts-manual"],
    curaduria: ["Sin leads en Curados.", "Esta estacion almacena leads con calidad heredada y dato defendible antes de clasificar producto.", "Ver contactos", "contacts-manual"],
    clasificacion: ["Sin leads en Clasificar.", "Esta estacion asigna producto o servicio interno antes de Gamificar.", "Ver leads", "contacts-manual"],
    preprocesamiento: ["Sin leads en Gamificar.", "Esta estacion prepara ticket, beneficio o dinámica anti-fuga.", "Crear ticket", "reward-passes"],
    procesamiento: ["Sin leads en Evaluación.", "Esta estacion almacena oportunidades accionadas para revisar respuesta y siguiente paso.", "Ver leads", "contacts-manual"],
    control_anti_fuga: ["Sin riesgos de fuga.", "Esta estacion almacena oportunidades con posible atasco para corregir antes de perderlas.", "Ver leads", "contacts-manual"],
    accion_correctiva: ["Sin leads en Corregir.", "Esta estacion almacena oportunidades que necesitan negociación, condición o último beneficio.", "Ver leads", "contacts-manual"],
    cierre: ["Sin leads en Cerrar.", "Esta estacion almacena cierres para registrar la fuente real del revenue.", "Registrar venta", "sales"],
    revenue_generado: ["Sin Revenue.", "Esta estacion valida ventas atribuidas antes de pasar a Postventa.", "Ver ventas", "sales"],
    postventa: ["Sin Postventa.", "Esta estacion almacena clientes despues de comprar para garantia, encuesta, recompra o referido.", "Activar recompra", "reward-passes"],
    inteligencia: ["Sin Optimizar.", "Esta estacion almacena senales para entender que produjo revenue o fuga.", "Ver leads", "contacts-manual"],
  };
  const content = map[stage.key] || ["Sin clientes en esta etapa.", "Cuando entren oportunidades, esta estación mostrará acciones listas.", "Alimentar máquina", "collector"];
  return `
    <div class="rms-stage-empty-block">
      <strong>${escapeHtml(content[0])}</strong>
      <small>${escapeHtml(content[1])}</small>
      <button type="button" data-rms-empty-action="${escapeHtml(content[3])}">${escapeHtml(content[2])}</button>
    </div>
  `;
}

function rmsStationNextPhase(stage = {}, stages = []) {
  const operation = stage.operation || (state.rmsMachine?.operations || {})[stage.key] || {};
  return stages.find((candidate) => candidate.key === operation.nextPhase) || null;
}

function rmsStationRows(phase = "", opportunities = []) {
  const rows = (opportunities || []).filter((item) => item.stage === phase);
  if (phase !== "curaduria") return rows;
  return rows.slice().sort((a, b) => rmsLeadQualityRank(b) - rmsLeadQualityRank(a) || Number(b.priority_score || 0) - Number(a.priority_score || 0));
}

function rmsStationMaterialLabel(item = {}) {
  if (item.activation_name) return `Activacion: ${item.activation_name}`;
  if (item.campaign_name) return `Campana: ${item.campaign_name}`;
  if (item.source_label) return item.source_label;
  return {
    PLAYER: "Lead capturado",
    MANUAL: "Ingreso manual",
    BUYER: "Comprador",
    AFFILIATE: "Afiliado / referido",
  }[String(item.source_type || "").toUpperCase()] || "Lead";
}

const RMS_LEAD_QUALITY_OPTIONS = [
  { value: "HIGH", label: "Calidad alta", shortLabel: "Alta", priority: "HIGH", detail: "Alta probabilidad de conversión" },
  { value: "MEDIUM", label: "Calidad media", shortLabel: "Media", priority: "MEDIUM", detail: "Interes viable, requiere mas recursos" },
  { value: "LOW", label: "Calidad baja", shortLabel: "Baja", priority: "LOW", detail: "Dato débil o baja intención" },
];

function rmsLeadQualityOption(value = "") {
  const normalized = String(value || "").trim().toUpperCase();
  return RMS_LEAD_QUALITY_OPTIONS.find((item) => item.value === normalized) || null;
}

function rmsLeadQualityValue(item = {}) {
  const draftValue = state.rmsLeadQualityDraft?.[item.id];
  const storedValue = item.state_metadata?.lead_quality || item.state_metadata?.funnel_quality || item.lead_quality || "";
  return rmsLeadQualityOption(draftValue || storedValue)?.value || "";
}

function rmsLeadQualityLabel(item = {}) {
  const option = rmsLeadQualityOption(rmsLeadQualityValue(item));
  return option?.label || "Sin calidad";
}

function rmsLeadQualityRank(item = {}) {
  return { HIGH: 3, MEDIUM: 2, LOW: 1 }[rmsLeadQualityValue(item)] || 0;
}

function rmsLeadQualitySelectMarkup(item = {}) {
  const selectedValue = rmsLeadQualityValue(item);
  return `
    <label class="rms-lead-quality-field">
      <span>Probabilidad de conversión</span>
      <select data-rms-lead-quality="${escapeHtml(item.id)}" aria-label="Calidad del lead">
        <option value="">Seleccionar calidad</option>
        ${RMS_LEAD_QUALITY_OPTIONS.map((option) => `<option value="${escapeHtml(option.value)}" ${option.value === selectedValue ? "selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}
      </select>
    </label>
  `;
}

function rmsClassifiedProductDraft(item = {}) {
  return state.rmsProductClassificationDraft?.[item.id] || null;
}

function rmsClassifiedProductValue(item = {}) {
  const draft = rmsClassifiedProductDraft(item);
  if (draft?.product_select !== undefined) return draft.product_select;
  if (item.classified_product_id) return inventoryProductSelectValue({ id: item.classified_product_id });
  const matched = findInventoryProduct(item.classified_product_name || item.product_interest || "");
  return matched ? inventoryProductSelectValue(matched) : (item.classified_product_name || item.product_interest ? OPEN_PRODUCT_VALUE : "");
}

function rmsClassifiedProductName(item = {}) {
  const draft = rmsClassifiedProductDraft(item);
  if (draft?.open_product_name) return draft.open_product_name;
  const selected = rmsClassifiedProductValue(item);
  const product = findInventoryProduct(selected);
  return product?.name || item.classified_product_name || item.product_interest || "";
}

function rmsHasConfirmedProductClassification(item = {}) {
  const draft = rmsClassifiedProductDraft(item);
  if (draft?.product_select && draft.product_select !== OPEN_PRODUCT_VALUE) return true;
  if (draft?.open_product_name) return true;
  if (item.classified_product_id) return true;
  const source = String(item.classification_source || "").toLowerCase();
  if (item.classification_is_manual) return true;
  return [
    "auto_activation_product",
    "auto_inventory_match",
    "manual_curados",
    "manual_inventory",
    "manual_open_product",
    "station_output_inventory",
    "station_output_open_interest",
  ].includes(source);
}

function rmsClassificationSourceLabel(item = {}) {
  const source = String(item.classification_source || "").toLowerCase();
  if (item.classification_is_manual || source.includes("manual")) return "Clasificación manual";
  if (source === "auto_activation_product") return "Clasificación automática por activación";
  if (source === "auto_inventory_match") return "Clasificación automática por inventario";
  if (source === "interest_without_inventory_match") return "Interés detectado sin producto creado";
  return "Sin clasificación de producto";
}

function rmsProductClassificationMarkup(item = {}) {
  const selected = rmsClassifiedProductValue(item);
  const openValue = selected === OPEN_PRODUCT_VALUE ? rmsClassifiedProductName(item) : "";
  const confidence = Math.round(Number(item.classification_confidence || 0) * 100);
  return `
    <div class="rms-product-classifier" data-rms-product-classifier="${escapeHtml(item.id)}">
      <label>
        <span>Producto / servicio interno</span>
        <select data-rms-product-select="${escapeHtml(item.id)}" data-product-select data-placeholder="Sin producto clasificado" data-open-label="Crear o escribir producto nuevo">
          ${inventoryProductSelectOptions(selected, { placeholder: "Sin producto clasificado", openLabel: "Crear o escribir producto nuevo" })}
        </select>
      </label>
      <input class="open-product-input ${selected === OPEN_PRODUCT_VALUE ? "" : "hidden"}" data-rms-product-open="${escapeHtml(item.id)}" type="text" maxlength="180" value="${escapeHtml(openValue)}" placeholder="Nombre del producto o servicio nuevo">
      <div class="rms-product-classifier-meta">
        <span>${escapeHtml(rmsClassificationSourceLabel(item))}</span>
        ${confidence ? `<small>${confidence}% de coincidencia</small>` : "<small>Requiere edición interna</small>"}
      </div>
      <div class="rms-product-classifier-actions">
        <button class="ghost-button compact" type="button" data-rms-save-classification="${escapeHtml(item.id)}">Guardar</button>
        <button class="solid-button compact" type="button" data-rms-create-product-classification="${escapeHtml(item.id)}">Crear producto</button>
        <button class="ghost-button compact danger-button" type="button" data-rms-clear-classification="${escapeHtml(item.id)}">Limpiar</button>
      </div>
    </div>
  `;
}

function rmsCaptureDataChips(item = {}) {
  const summary = Array.isArray(item.capture_summary) ? item.capture_summary : [];
  if (!summary.length) return "";
  return `
    <div class="rms-capture-data-chips">
      ${summary.slice(0, 4).map((entry) => `
        <span title="${escapeHtml(entry.label)}">
          <strong>${escapeHtml(entry.label)}</strong>
          ${escapeHtml(entry.value)}
        </span>
      `).join("")}
    </div>
  `;
}

function rmsStationTopCounts(rows = [], getter = () => "", limit = 4) {
  const counts = new Map();
  rows.forEach((item) => {
    const label = String(getter(item) || "").trim();
    if (!label || label === "-") return;
    counts.set(label, (counts.get(label) || 0) + 1);
  });
  return Array.from(counts.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([label, count]) => ({ label, count }));
}

function rmsStationCountChips(items = []) {
  return items.length
    ? items.map((item) => `<span>${escapeHtml(item.label)} <strong>${Number(item.count || 0).toLocaleString("es-CO")}</strong></span>`).join("")
    : '<span>Sin clasificar <strong>0</strong></span>';
}

function rmsStationMaterialInventoryMarkup(rows = [], stage = {}, operation = {}) {
  const withContact = rows.filter((item) => item.phone || item.email).length;
  const withCampaign = rows.filter((item) => item.campaign_name || item.activation_name).length;
  const withTicket = rows.filter((item) => Number(item.active_tickets || 0) > 0).length;
  const highPriority = rows.filter((item) => Number(item.priority_score || 0) >= 70 || ["HIGH", "URGENT"].includes(String(item.care_priority || "").toUpperCase())).length;
  const productClassified = rows.filter((item) => item.classified_product_id || item.classified_product_name || findInventoryProduct(item.product_interest || "")).length;
  const materialTypes = rmsStationTopCounts(rows, rmsStationMaterialLabel);
  const channels = rmsStationTopCounts(rows, (item) => item.channel || item.source_detail || item.source_label);
  const interests = rmsStationTopCounts(rows, (item) => item.classified_product_name || item.product_interest || item.raw_recommended_action || item.coverage_type);
  const selectLabel = stage.key === "alimentacion"
    ? "Seleccionar cualificados"
    : stage.key === "curaduria"
      ? "Seleccionar clasificados"
      : "Checkear lote";
  return `
    <section class="rms-station-material-inventory" aria-label="Materia prima dentro de la estación">
      <div class="rms-station-material-head">
        <div>
          <span class="mono-label">Materia prima adentro</span>
          <strong>${Number(rows.length || 0).toLocaleString("es-CO")} leads en ${escapeHtml(stage.label || "esta estación")}</strong>
          <p>${escapeHtml(operation.description || "Revisa datos, selecciona leads y autoriza la salida solo cuando estén listos para la siguiente estación.")}</p>
        </div>
        <button class="solid-button compact" type="button" data-rms-station-select-all="${escapeHtml(stage.key || "")}" ${rows.length ? "" : "disabled"}>${escapeHtml(selectLabel)}</button>
      </div>
      <div class="rms-station-material-stats">
        <article><span>Con dato contacto</span><strong>${withContact.toLocaleString("es-CO")}</strong></article>
        <article><span>Con campaña/activación</span><strong>${withCampaign.toLocaleString("es-CO")}</strong></article>
        <article><span>Con ticket activo</span><strong>${withTicket.toLocaleString("es-CO")}</strong></article>
        <article><span>${stage.key === "curaduria" ? "Clasificados producto" : "Alta prioridad"}</span><strong>${(stage.key === "curaduria" ? productClassified : highPriority).toLocaleString("es-CO")}</strong></article>
      </div>
      <div class="rms-station-material-buckets">
        <div><span>Tipo de materia</span>${rmsStationCountChips(materialTypes)}</div>
        <div><span>Fuente / canal</span>${rmsStationCountChips(channels)}</div>
        <div><span>Interés / cobertura</span>${rmsStationCountChips(interests)}</div>
      </div>
    </section>
  `;
}

function rmsFunnelQualityCounts(rows = []) {
  return RMS_LEAD_QUALITY_OPTIONS.map((option) => ({
    ...option,
    count: rows.filter((item) => rmsLeadQualityValue(item) === option.value).length,
  }));
}

function rmsCurationAudit(item = {}) {
  const hasContact = Boolean(item.phone || item.email);
  const hasOrigin = Boolean(item.entry_summary || item.source_detail || item.campaign_name || item.activation_name || item.channel || item.source_label);
  const hasInterest = Boolean(item.product_interest || item.top_interest || item.interest || item.raw_recommended_action);
  const hasCoverage = Boolean(item.campaign_name || item.activation_name || item.active_tickets || item.coverage_type);
  const checks = [
    { key: "contact", label: "Contacto", ok: hasContact },
    { key: "origin", label: "Origen", ok: hasOrigin },
    { key: "interest", label: "Interés", ok: hasInterest },
    { key: "coverage", label: "Ticket/campaña", ok: hasCoverage },
  ];
  const missing = checks.filter((check) => !check.ok);
  return {
    checks,
    missing,
    ready: hasContact && hasOrigin && hasInterest,
    label: missing.length ? `Falta ${missing.map((check) => check.label.toLowerCase()).join(", ")}` : "Dato curado",
  };
}

function rmsStationFocusConsoleMarkup(phase = "", rows = [], nextPhase = null) {
  if (phase === "alimentacion") {
    const qualityCounts = rmsFunnelQualityCounts(rows);
    const qualified = rmsStationOutputEligibleRows(phase, rows).length;
    const unqualified = Math.max(0, rows.length - qualified);
    return `
      <section class="rms-station-focus-console is-funnel" aria-label="Consola visual del embudo">
        <div class="rms-station-focus-copy">
          <span class="mono-label">Compuerta del embudo</span>
          <h4>La salida no depende de chulear al azar: exige una probabilidad explícita.</h4>
          <p>${escapeHtml(qualified ? `${qualified.toLocaleString("es-CO")} lead(s) ya pueden pasar a ${nextPhase?.label || "Curados"}.` : "Selecciona calidad alta, media o baja para convertir entrada cruda en salida operable.")}</p>
        </div>
        <div class="rms-funnel-quality-board">
          ${qualityCounts.map((quality) => {
            const percent = rows.length ? Math.round((quality.count / rows.length) * 100) : 0;
            return `
              <article class="rms-quality-tile quality-${escapeHtml(quality.value.toLowerCase())}">
                <span>${escapeHtml(quality.shortLabel)}</span>
                <strong>${Number(quality.count || 0).toLocaleString("es-CO")}</strong>
                <small>${escapeHtml(quality.detail)}</small>
                <i style="--quality-fill:${percent}%"></i>
              </article>
            `;
          }).join("")}
          <article class="rms-quality-tile quality-pending">
            <span>Sin decidir</span>
            <strong>${unqualified.toLocaleString("es-CO")}</strong>
            <small>No aparecen en salida hasta asignar calidad.</small>
            <i style="--quality-fill:${rows.length ? Math.round((unqualified / rows.length) * 100) : 0}%"></i>
          </article>
        </div>
      </section>
    `;
  }
  if (phase === "curaduria") {
    const audits = rows.map(rmsCurationAudit);
    const ready = audits.filter((audit) => audit.ready).length;
    const missingContact = audits.filter((audit) => audit.missing.some((check) => check.key === "contact")).length;
    const missingOrigin = audits.filter((audit) => audit.missing.some((check) => check.key === "origin")).length;
    const missingInterest = audits.filter((audit) => audit.missing.some((check) => check.key === "interest")).length;
    const highQuality = rows.filter((item) => rmsLeadQualityValue(item) === "HIGH").length;
    const classified = rows.filter((item) => item.classified_product_id || item.classified_product_name || findInventoryProduct(item.product_interest || "")).length;
    const noInventoryMatch = rows.filter((item) => item.product_interest && !item.classified_product_id && !findInventoryProduct(item.product_interest)).length;
    return `
      <section class="rms-station-focus-console is-curation" aria-label="Mesa visual de clasificacion">
        <div class="rms-station-focus-copy">
          <span class="mono-label">Operacion: Clasificacion</span>
          <h4>La calidad ya viene de Curaduría; aquí se amarra cada lead al producto o servicio interno.</h4>
          <p>${escapeHtml(classified ? `${classified.toLocaleString("es-CO")} lead(s) ya tienen clasificación de producto o coincidencia automática.` : "Clasifica contra Productos o crea el producto si aún no existe en inventario.")}</p>
        </div>
        <div class="rms-curation-audit-board">
          <article><span>Con producto</span><strong>${classified.toLocaleString("es-CO")}</strong><small>Manual o automático</small></article>
          <article><span>Alta calidad</span><strong>${highQuality.toLocaleString("es-CO")}</strong><small>Vienen fuertes de Curaduría</small></article>
          <article><span>Sin match inventario</span><strong>${noInventoryMatch.toLocaleString("es-CO")}</strong><small>Crear producto aquí</small></article>
          <article><span>Sin contacto</span><strong>${missingContact.toLocaleString("es-CO")}</strong><small>Completar teléfono o correo</small></article>
          <article><span>Dato curado</span><strong>${ready.toLocaleString("es-CO")}</strong><small>Contacto, origen e interés</small></article>
          <article><span>Sin interés</span><strong>${missingInterest.toLocaleString("es-CO")}</strong><small>No se puede auto-clasificar</small></article>
        </div>
      </section>
    `;
  }
  return "";
}

