function rmsCaptureResponseText(value) {
  if (Array.isArray(value)) return value.map(rmsCaptureResponseText).filter(Boolean).join(", ");
  if (value === true) return "Sí";
  if (value === false) return "No";
  if (value === null || value === undefined || value === "") return "Sin respuesta";
  if (typeof value === "object") {
    try { return JSON.stringify(value, null, 2); } catch { return String(value); }
  }
  return String(value);
}

function rmsActivationFormRows(form = {}) {
  const rows = [];
  const seen = new Set();
  const push = (key, label, value) => {
    const normalizedKey = String(key || label || "respuesta");
    const text = rmsCaptureResponseText(value);
    if (seen.has(normalizedKey) || text === "Sin respuesta") return;
    seen.add(normalizedKey);
    rows.push({ key: normalizedKey, label: label || normalizedKey, value: text });
  };
  (Array.isArray(form.summary) ? form.summary : []).forEach((item) => push(item.key, item.label, item.value));
  const responses = form.responses && typeof form.responses === "object" ? form.responses : {};
  const fields = Array.isArray(form.fields) ? form.fields : [];
  fields.forEach((field) => push(field.key, field.label, responses[field.key]));
  Object.entries(responses).forEach(([key, value]) => push(key, form.labels?.[key] || key, value));
  return rows;
}

function rmsCaptureReviewGroups(detail = {}, item = {}) {
  const groups = [];
  const activations = (detail.activations || []).filter((activation) => (
    String(activation.source_type || "").toUpperCase() === "INTERACTIVE"
    || activation.participant_metadata?.activation_form
    || (Array.isArray(activation.answers) && activation.answers.length)
  ));
  activations.forEach((activation) => {
    const rows = rmsActivationFormRows(activation.participant_metadata?.activation_form || {});
    const existingKeys = new Set(rows.map((row) => row.key));
    (Array.isArray(activation.answers) ? activation.answers : []).forEach((answer) => {
      const key = String(answer.key || answer.label || "respuesta");
      if (existingKeys.has(key)) return;
      const value = rmsCaptureResponseText(answer.value);
      if (value === "Sin respuesta") return;
      existingKeys.add(key);
      rows.push({ key, label: answer.label || key, value });
    });
    if (!rows.length) return;
    groups.push({
      id: activation.activation_id || activation.id,
      title: activation.name || activation.game_name || activation.trivia_title || item.activation_name || "Activación Gaming Center",
      meta: [activation.activation_type, activation.campaign_name, activation.completed_at ? formatDate(activation.completed_at) : null].filter(Boolean).join(" · "),
      rows,
    });
  });
  if (!groups.length) {
    const leadRows = rmsActivationFormRows(detail.lead?.metadata?.activation_form || {});
    const fallbackRows = leadRows.length ? leadRows : (item.capture_summary || []).map((row) => ({
      key: row.key || row.label,
      label: row.label || row.key || "Dato capturado",
      value: rmsCaptureResponseText(row.value),
    }));
    if (fallbackRows.length) {
      groups.push({
        id: item.rms_intake?.activation_id || "capture",
        title: item.activation_name || detail.lead?.metadata?.activation_title || "Formulario de la activación",
        meta: [item.activation_type, item.campaign_name, item.created_at ? formatDate(item.created_at) : null].filter(Boolean).join(" · "),
        rows: fallbackRows,
      });
    }
  }
  return groups;
}

function renderRmsCaptureReview(detail = {}, item = {}) {
  const body = document.getElementById("rmsCaptureReviewBody");
  const title = document.getElementById("rmsCaptureReviewTitle");
  const subtitle = document.getElementById("rmsCaptureReviewSubtitle");
  const eyebrow = document.getElementById("rmsCaptureReviewEyebrow");
  const lead = detail.lead || {};
  const groups = rmsCaptureReviewGroups(detail, item);
  const stationLabel = item.stage_label || item.stage || "Estación RMS";
  if (eyebrow) eyebrow.textContent = `${stationLabel} · análisis de lead`;
  if (title) title.textContent = lead.name || item.name || "Respuestas del formulario";
  if (subtitle) subtitle.textContent = `${groups.length} formulario(s) encontrado(s) · revisa la información disponible para operar este lead.`;
  if (!body) return;
  body.innerHTML = `
    <section class="rms-capture-origin">
      <article><span>Estación actual</span><strong>${escapeHtml(stationLabel)}</strong></article>
      <article><span>Origen</span><strong>${escapeHtml(item.source_label || lead.channel || "Gaming Center")}</strong></article>
      <article><span>Activación</span><strong>${escapeHtml(item.activation_name || groups[0]?.title || "Activación interactiva")}</strong></article>
      <article><span>Campaña</span><strong>${escapeHtml(item.campaign_name || lead.campaign_name || "Sin campaña")}</strong></article>
      <article><span>Contacto</span><strong>${escapeHtml(lead.phone || lead.email || item.phone || item.email || "Sin contacto")}</strong></article>
    </section>
    ${groups.length ? groups.map((group) => `
      <section class="rms-capture-group">
        <div class="rms-capture-group-head">
          <div><strong>${escapeHtml(group.title)}</strong><small>${escapeHtml(group.meta || "Formulario completado")}</small></div>
          <span class="status-chip success">${group.rows.length.toLocaleString("es-CO")} respuesta(s)</span>
        </div>
        <div class="rms-capture-response-grid">
          ${group.rows.map((row) => `<article class="rms-capture-response-card"><span>${escapeHtml(row.label)}</span><strong>${escapeHtml(row.value)}</strong></article>`).join("")}
        </div>
      </section>
    `).join("") : `
      <div class="rms-capture-review-empty">
        <strong>No hay respuestas personalizadas guardadas para este lead.</strong>
        <p>La identidad y el origen sí están registrados. Puedes abrir la ficha completa para revisar su historial.</p>
      </div>
    `}
  `;
}

function rmsCollectorStationMarkup(rows = [], stage = {}, nextPhase = null, operation = {}) {
  const selectedRows = rmsStationSelectedRows(stage.key, rows);
  const eligibleRows = rmsStationOutputEligibleRows(stage.key, rows);
  const query = String(state.rmsStationSearch || "").trim();
  const matchingRows = query ? rows.filter((item) => rmsStationRowMatches(item, stage.key)) : rows;
  const renderLimit = 80;
  const selectedIds = new Set(state.rmsMachineSelectedIds || []);
  const renderedRows = matchingRows
    .slice()
    .sort((a, b) => Number(selectedIds.has(b.id)) - Number(selectedIds.has(a.id)))
    .slice(0, renderLimit);
  const hiddenCount = Math.max(0, matchingRows.length - renderedRows.length);
  return `
    <div class="rms-collector-station-shell">
      <section class="rms-station-clean-shell rms-collector-clean-shell rms-station-input-lane">
        <div class="rms-station-list-head">
          <div>
            <span class="mono-label">Leads en estación</span>
            <strong>${Number(rows.length || 0).toLocaleString("es-CO")} lead(s) recolectados</strong>
            <small>${eligibleRows.length.toLocaleString("es-CO")} cumplen mínimo para ${escapeHtml(nextPhase?.label || "Curaduría")} · ${selectedRows.length.toLocaleString("es-CO")} seleccionados.</small>
          </div>
          <small class="rms-station-visible-summary" aria-live="polite">Mostrando <strong data-rms-station-visible-count>${renderedRows.length}</strong> de ${matchingRows.length}${hiddenCount ? ` · ${hiddenCount.toLocaleString("es-CO")} más sin dibujar para mantener la estación rápida` : ""}</small>
        </div>
        <div class="rms-station-lead-toolbar">
          <label class="rms-station-search-field">
            <span class="material-symbols-outlined" aria-hidden="true">search</span>
            <input type="search" data-rms-station-search value="${escapeHtml(state.rmsStationSearch || "")}" placeholder="Buscar lead" aria-label="Buscar lead recolectado">
          </label>
          <div class="rms-station-view-filters" role="group" aria-label="Filtrar leads recolectados">
            <button type="button" data-rms-station-view="all" class="${state.rmsStationViewMode === "all" ? "is-active" : ""}" aria-pressed="${state.rmsStationViewMode === "all"}">Todos <span>${rows.length}</span></button>
            <button type="button" data-rms-station-view="selected" class="${state.rmsStationViewMode === "selected" ? "is-active" : ""}" aria-pressed="${state.rmsStationViewMode === "selected"}">Seleccionados <span>${selectedRows.length}</span></button>
            <button type="button" data-rms-station-view="ready" class="${state.rmsStationViewMode === "ready" ? "is-active" : ""}" aria-pressed="${state.rmsStationViewMode === "ready"}">Listos <span>${eligibleRows.length}</span></button>
            <button type="button" data-rms-station-view="risk" class="${state.rmsStationViewMode === "risk" ? "is-active" : ""}" aria-pressed="${state.rmsStationViewMode === "risk"}">Riesgo <span>${rows.filter((item) => Number(item.risk_score || 0) >= 50).length}</span></button>
          </div>
        </div>
        ${rmsStationOutputMarkup(stage.key || "", rows, nextPhase)}
        ${rmsStationLeadTableMarkup(renderedRows, stage, nextPhase, operation)}
        ${!renderedRows.length ? '<div class="rms-station-no-results" data-rms-station-no-results><span class="material-symbols-outlined" aria-hidden="true">search_off</span><strong>No hay leads con esta búsqueda.</strong><small>Limpia el texto de búsqueda para volver a ver la entrada.</small></div>' : '<div class="rms-station-no-results hidden" data-rms-station-no-results><span class="material-symbols-outlined" aria-hidden="true">search_off</span><strong>No hay leads con esta búsqueda.</strong><small>Limpia el texto de búsqueda para volver a ver la entrada.</small></div>'}
      </section>
    </div>
  `;
}

function rmsCollectorLeadCardMarkup(item = {}, stage = {}, nextPhase = null, operation = {}) {
  const selected = state.rmsMachineSelectedIds.includes(item.id);
  const readiness = rmsCollectorReadiness(item);
  const origin = item.entry_summary || item.source_detail || item.campaign_name || item.channel || item.source_label || item.source_type || "Origen sin definir";
  const interest = item.product_interest || item.top_interest || item.interest || item.raw_recommended_action || "Interés pendiente";
  const contact = [item.phone, item.email].filter(Boolean).join(" · ") || "Sin contacto";
  const campaignChannel = [item.campaign_name || item.activation_name, item.channel].filter(Boolean).join(" / ") || origin;
  const enteredAt = item.created_at || item.last_interaction_at || item.updated_at;
  const material = rmsStationMaterialLabel(item);
  const destination = nextPhase?.short_label || nextPhase?.label || "siguiente estación";
  return `
    <article class="rms-collector-lead-card ${selected ? "is-selected" : ""}" data-rms-station-lead="${escapeHtml(item.id)}">
      <label class="rms-station-lead-check rms-collector-select-control" title="Seleccionar para pasar a ${escapeHtml(destination)}">
        <input type="checkbox" data-rms-select="${escapeHtml(item.id)}" ${selected ? "checked" : ""}>
        <span class="material-symbols-outlined" aria-hidden="true">${selected ? "check_circle" : "radio_button_unchecked"}</span>
        <span>
          <strong>Pasar a ${escapeHtml(destination)}</strong>
          <small>${escapeHtml(readiness.ready ? "Listo para salida" : readiness.detail)}</small>
        </span>
      </label>
      <div class="rms-collector-lead-card-main" role="button" tabindex="0" data-rms-review-capture="${escapeHtml(item.id)}">
        <div>
          <div class="rms-collector-lead-title">
            <strong>${escapeHtml(item.name || "Contacto")}</strong>
            <span class="rms-priority ${escapeHtml(item.priority_class || "medium")}">${escapeHtml(item.priority_label || "Media")}</span>
            <span class="rms-collector-readiness-chip ${readiness.ready ? "" : "is-missing"}"><span class="material-symbols-outlined" aria-hidden="true">${readiness.ready ? "verified" : "error"}</span>${escapeHtml(readiness.label)}</span>
          </div>
          <div class="rms-collector-lead-meta">
            <span><strong>Contacto:</strong> ${escapeHtml(contact)}</span>
            <span><strong>Interés:</strong> ${escapeHtml(interest)}</span>
            <span><strong>Origen:</strong> ${escapeHtml(campaignChannel)}</span>
            <span><strong>Entrada:</strong> ${escapeHtml(enteredAt ? formatDate(enteredAt) : "-")} · ${escapeHtml(material)}</span>
          </div>
        </div>
        <span class="rms-collector-lead-open-hint"><span class="material-symbols-outlined" aria-hidden="true">visibility</span> Ver respuestas</span>
      </div>
    </article>
  `;
}

async function openRmsCaptureReview(item = {}) {
  if (!item.source_id && !item.lead_id) return;
  const modal = ensureRmsCaptureReviewModal();
  modal.classList.remove("hidden");
  const body = document.getElementById("rmsCaptureReviewBody");
  const title = document.getElementById("rmsCaptureReviewTitle");
  const subtitle = document.getElementById("rmsCaptureReviewSubtitle");
  const eyebrow = document.getElementById("rmsCaptureReviewEyebrow");
  if (eyebrow) eyebrow.textContent = `${item.stage_label || item.stage || "Estación RMS"} · análisis de lead`;
  if (title) title.textContent = item.name || "Respuestas del formulario";
  if (subtitle) subtitle.textContent = "Consultando datos, respuestas y contexto comercial...";
  if (body) body.innerHTML = '<div class="empty-state compact">Cargando respuestas del beneficiario...</div>';
  const fullLeadButton = document.getElementById("rmsCaptureOpenFullLead");
  if (fullLeadButton) {
    fullLeadButton.onclick = () => {
      closeRmsCaptureReview();
      openRmsOpportunityDetail(item);
    };
  }
  try {
    const detail = await api(`/api/business/leads/${encodeURIComponent(item.source_id || item.lead_id)}?source_type=${encodeURIComponent(item.source_type || "PLAYER")}`, { headers: authHeaders() });
    renderRmsCaptureReview(detail, item);
  } catch (error) {
    if (body) body.innerHTML = `<div class="rms-capture-review-empty"><strong>No se pudieron cargar las respuestas.</strong><p>${escapeHtml(error.message || "Intenta nuevamente.")}</p></div>`;
  }
}

